  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un procedimiento sancionador se propone una multa de 1.000 euros, sanción únicamente pecuniaria. El infractor reconoce su responsabilidad y paga voluntariamente antes de la resolución, renunciando a recurrir. Si se aplican las reducciones mínimas legales, ¿cuánto pagará?', 'El reconocimiento y el pago voluntario dan derecho cada uno a una reducción de al menos el 20 %, acumulables entre sí: 1.000 − 200 − 200 = 600 euros, condicionado al desistimiento o renuncia a recurrir en vía administrativa (art. 85.3).', 'age_adm_32_potestad_sancionadora', (select id from public.topics where slug = 'age-adm-32-potestad-sancionadora'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 85.1-3 LPAC', 'el órgano competente para resolver el procedimiento aplicará reducciones de, al menos, el 20 % sobre el importe de la sanción propuesta, siendo éstos acumulables entre sí.', null, '1b2f51b7b02f7dafeeafaf883e2242700213ca91507c325bd1ab7d57e8611212', false
