  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 40/2015, las personas físicas y jurídicas solo pueden ser sancionadas por hechos constitutivos de infracción administrativa cuando resulten responsables:', 'Rige el principio de culpabilidad: responsabilidad a título de dolo o culpa (art. 28.1).', 'age_adm_32_potestad_sancionadora', (select id from public.topics where slug = 'age-adm-32-potestad-sancionadora'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'Art. 28.1 LRJSP', 'que resulten responsables de los mismos a título de dolo o culpa.', null, 'b7edaec112a51510ab2454a7c627191c3d40b551e1abe9dde16c6b76670378ca', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b7edaec112a51510ab2454a7c627191c3d40b551e1abe9dde16c6b76670378ca')
  returning id
