  select 'Las sanciones administrativas, sean o no de naturaleza pecuniaria:', 'El art. 29.1 prohíbe toda privación de libertad, directa o subsidiaria, como sanción administrativa (en línea con el art. 25.3 CE).', 'age_adm_32_potestad_sancionadora', (select id from public.topics where slug = 'age-adm-32-potestad-sancionadora'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'Art. 29.1 LRJSP', 'Las sanciones administrativas, sean o no de naturaleza pecuniaria, en ningún caso podrán implicar, directa o subsidiariamente, privación de libertad.', null, '7b8e5f8cf0312b54e3952997e326ee297f7f921873c125ffbd843e09448d6661', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7b8e5f8cf0312b54e3952997e326ee297f7f921873c125ffbd843e09448d6661')
