with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Al establecer sanciones pecuniarias, el legislador debe prever que:', 'Es la regla del art. 29.2: infringir no debe salir más rentable que cumplir.', 'age_adm_32_potestad_sancionadora', (select id from public.topics where slug = 'age-adm-32-potestad-sancionadora'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'Art. 29.2 LRJSP', 'El establecimiento de sanciones pecuniarias deberá prever que la comisión de las infracciones tipificadas no resulte más beneficioso para el infractor que el cumplimiento de las normas infringidas.', null, 'c4db029e31a7783ba825017581e41cc2fa9c0626bb028b583ed3166793527c5b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c4db029e31a7783ba825017581e41cc2fa9c0626bb028b583ed3166793527c5b')
