with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Para poder vender un producto sin la autorización exigida (infracción grave), una empresa falsea necesariamente su etiquetado (infracción leve). Según la Ley 40/2015, ¿qué sanción procede?', 'Cuando de la comisión de una infracción deriva necesariamente la de otra u otras, solo se impone la sanción de la más grave (art. 29.5).', 'age_adm_32_potestad_sancionadora', (select id from public.topics where slug = 'age-adm-32-potestad-sancionadora'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'Art. 29.5 LRJSP', 'Cuando de la comisión de una infracción derive necesariamente la comisión de otra u otras, se deberá imponer únicamente la sanción correspondiente a la infracción más grave cometida.', null, '954c5653b2b17fbe7c4fd6f1852d097343f1d2714046b60c43fe2945d5cf9d24', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '954c5653b2b17fbe7c4fd6f1852d097343f1d2714046b60c43fe2945d5cf9d24')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Las dos sanciones, sumadas.', false), ('B', 'Únicamente la sanción correspondiente a la infracción más grave.', true), ('C', 'Únicamente la sanción de la infracción leve, por ser la primera cometida.', false), ('D', 'La sanción de la infracción grave incrementada en un 50 %.', false)) as v(label, body, ok)
)
