with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 40/2015, la realización de una pluralidad de acciones u omisiones que infrinjan el mismo o semejantes preceptos administrativos, en ejecución de un plan preconcebido o aprovechando idéntica ocasión, es sancionable como:', 'Es la definición de infracción continuada del art. 29.6. La reincidencia, en cambio, es un criterio de graduación (art. 29.3.d).', 'age_adm_32_potestad_sancionadora', (select id from public.topics where slug = 'age-adm-32-potestad-sancionadora'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'Art. 29.6 LRJSP', 'Será sancionable, como infracción continuada, la realización de una pluralidad de acciones u omisiones que infrinjan el mismo o semejantes preceptos administrativos, en ejecución de un plan preconcebido o aprovechando idéntica ocasión.', null, '619c6ff671702a3f2da0f0c7b38137888e2c1fd8d6b129a4e220ada9793ed80b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '619c6ff671702a3f2da0f0c7b38137888e2c1fd8d6b129a4e220ada9793ed80b')
