with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Se inicia, con conocimiento del interesado, un procedimiento sancionador por una infracción. Después, el expediente queda paralizado durante dos meses por causa no imputable al presunto responsable. ¿Qué ocurre con la prescripción de la infracción?', 'La iniciación con conocimiento del interesado interrumpe la prescripción, que se reinicia si el expediente está paralizado más de un mes por causa no imputable al presunto responsable (art. 30.2).', 'age_adm_32_potestad_sancionadora', (select id from public.topics where slug = 'age-adm-32-potestad-sancionadora'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'Art. 30.2 LRJSP', 'Interrumpirá la prescripción la iniciación, con conocimiento del interesado, de un procedimiento administrativo de naturaleza sancionadora, reiniciándose el plazo de prescripción si el expediente sancionador estuviera paralizado durante más de un mes por causa no imputable al presunto responsable.', null, '4e15005adea4eff76e7997257be3a11af8bcfbd84725bdd38e1daabffda8ba7f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4e15005adea4eff76e7997257be3a11af8bcfbd84725bdd38e1daabffda8ba7f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La prescripción queda interrumpida definitivamente mientras no se archive el expediente.', false), ('B', 'La paralización no afecta a la prescripción, que solo se reinicia con la resolución.', false), ('C', 'La infracción prescribe automáticamente por la paralización.', false), ('D', 'La iniciación la interrumpió, pero el plazo de prescripción se reinicia al estar paralizado más de un mes.', true)) as v(label, body, ok)
)
