with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una Subdirección adquiere ordenadores e impresoras para ampliar su dotación, sin sustituir equipos existentes. Según el código de la clasificación económica de los gastos, el gasto se imputa:', 'La adquisición de equipos de proceso de datos que incrementa el stock de capital es inversión nueva (concepto 620); si sustituyera equipos existentes por otros análogos sería reposición (concepto 630).', 'age_adm_52_modificaciones_credito', (select id from public.topics where slug = 'age-adm-52-modificaciones-credito'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-879'), 'Anexo IV, art. 62 (Resolución DGP 20/01/2014)', 'Concepto 620. Inversión nueva asociada al funcionamiento operativo de los servicios. Se imputarán a este concepto, los gastos relacionados con: […] Equipamiento para proceso de información. Adquisición de equipos de proceso de datos, unidades centrales, dispositivos auxiliares de memoria, monitores, impresoras', null, '5c65eaa64d1bcbde08f4a9ae6b330a26500b65f6203f47ea4e09888ada952380', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5c65eaa64d1bcbde08f4a9ae6b330a26500b65f6203f47ea4e09888ada952380')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al concepto 630 «Inversión de reposición asociada al funcionamiento operativo de los servicios», del capítulo 6.', false), ('B', 'Al subconcepto 220.02 «Material informático no inventariable», del capítulo 2.', false), ('C', 'Al concepto 620 «Inversión nueva asociada al funcionamiento operativo de los servicios», del capítulo 6.', true), ('D', 'Al concepto 216 «Equipos para procesos de la información», de reparaciones del capítulo 2.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Resolución de 20 de enero de 2014 de la Dirección General de Presupuestos, por la que se establecen los códigos de la clasificación económica, los gastos correspondientes a pensiones a funcionarios o familias, de carácter civil o militar, se imputan:', 'Uno de los cambios de la Resolución de 2014 fue llevar al capítulo 4 las pensiones a funcionarios o familias, que hasta 2014 se imputaban al capítulo 1.', 'age_adm_52_modificaciones_credito', (select id from public.topics where slug = 'age-adm-52-modificaciones-credito'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-879'), 'Resolución DGP 20/01/2014, preámbulo y cap. 4', 'Los principales cambios introducidos en la clasificación económica del gasto se refieren a la imputación al capítulo 4 «Transferencias Corrientes» de los gastos correspondientes a pensiones a funcionarios o familias de carácter civil o militar que hasta 2014 se han venido imputando al capítulo 1 «Gastos de personal».', null, '2203bb82255877a2a49e3270544fb1754fdee326aae87efbd4190ee5f380cb06', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2203bb82255877a2a49e3270544fb1754fdee326aae87efbd4190ee5f380cb06')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al capítulo 4 «Transferencias corrientes».', true), ('B', 'Al capítulo 1 «Gastos de personal».', false), ('C', 'Al capítulo 2 «Gastos corrientes en bienes y servicios».', false), ('D', 'Al capítulo 7 «Transferencias de capital».', false)) as v(label, body, ok)
)
