insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-53-documentos-contables' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Las normas y documentos contables aprobados por la Orden de 1 de febrero de 1996 son de aplicación a:', 'El apartado primero limita su ámbito a la Administración General del Estado; la Instrucción de operatoria contable regula en una disposición adicional su aplicación a los organismos autónomos.', 'age_adm_53_documentos_contables', (select id from public.topics where slug = 'age-adm-53-documentos-contables'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749'), 'Orden 1-2-1996 documentos contables, apdo. primero', 'Las normas y los documentos contables aprobados en la presente Orden serán de aplicación a la Administración General del Estado.', null, '006041985d0aeba8056cfa87036d249fc5448a0609400dbcdc7bb6052d4ee731', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '006041985d0aeba8056cfa87036d249fc5448a0609400dbcdc7bb6052d4ee731')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La Administración General del Estado.', true), ('B', 'Todas las Administraciones públicas, incluidas las entidades locales.', false), ('C', 'Únicamente a los organismos autónomos del Estado.', false), ('D', 'Solo a la Intervención General de la Administración del Estado.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Orden de 1 de febrero de 1996, ¿en qué soporte se expiden con carácter general los documentos contables?', 'Todos los documentos contables son electrónicos y se ajustan a los modelos y normas de la Orden y al procedimiento de tramitación electrónica que fije la IGAE.', 'age_adm_53_documentos_contables', (select id from public.topics where slug = 'age-adm-53-documentos-contables'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749'), 'Orden 1-2-1996 documentos contables, apdo. segundo.2', 'Todos los documentos contables serán electrónicos y se ajustarán a los modelos y normas de cumplimentación previstos en esta Orden', null, '5861a56e8777caeca175cfe170eab09a8694b2ff197c4944196a0c8c136b7cf7', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5861a56e8777caeca175cfe170eab09a8694b2ff197c4944196a0c8c136b7cf7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En papel, por triplicado.', false), ('B', 'Todos los documentos contables serán electrónicos.', true), ('C', 'En papel o en formato electrónico, a elección del servicio gestor.', false), ('D', 'En formato electrónico solo cuando superen los 50.000 euros.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿En qué caso pueden expedirse documentos contables en papel?', 'Es una excepción que decide la IGAE, a propuesta del responsable de la oficina de contabilidad, por circunstancias excepcionales.', 'age_adm_53_documentos_contables', (select id from public.topics where slug = 'age-adm-53-documentos-contables'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749'), 'Orden 1-2-1996 documentos contables, apdo. segundo.2', 'No obstante, cuando por circunstancias excepcionales así lo determine la Intervención General de la Administración del Estado a propuesta del responsable de la oficina de contabilidad, se podrán expedir documentos contables en papel.', null, 'eb0fab81f0de3914a7778d99b0e163e1e54f1ff3ab78c0f57c8f9b702ce0e8ea', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'eb0fab81f0de3914a7778d99b0e163e1e54f1ff3ab78c0f57c8f9b702ce0e8ea')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cuando lo solicite el servicio gestor por razones de urgencia, sin necesidad de autorización.', false), ('B', 'Cuando el gasto se tramite por el sistema de anticipos de caja fija.', false), ('C', 'Cuando por circunstancias excepcionales lo determine la Intervención General de la Administración del Estado, a propuesta del responsable de la oficina de contabilidad.', true), ('D', 'Nunca: la Orden prohíbe en todo caso el papel.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Los documentos contables cuya emisión se realice mediante actuación administrativa automatizada podrán autenticarse mediante:', 'El apartado tercero.2 remite al sello electrónico del art. 42.a) de la Ley 40/2015; los demás documentos se autorizan con firma electrónica de quien tenga la competencia (apdo. tercero.1).', 'age_adm_53_documentos_contables', (select id from public.topics where slug = 'age-adm-53-documentos-contables'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749'), 'Orden 1-2-1996 documentos contables, apdo. tercero.2', 'Los documentos contables cuya emisión se realice mediante actuación administrativa automatizada podrán ser autenticados mediante un sistema de sello electrónico de Administración Pública, órgano, organismo público o entidad de derecho público, basado en certificado electrónico reconocido o cualificado', null, 'e4f114ec10c24ec807a0c65b9a3bc77a03e05906c428b3a349cf6d0fd1b000ea', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e4f114ec10c24ec807a0c65b9a3bc77a03e05906c428b3a349cf6d0fd1b000ea')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La firma manuscrita escaneada del jefe de contabilidad.', false), ('B', 'Un código de barras sin certificado.', false), ('C', 'La firma electrónica del interesado acreedor.', false), ('D', 'Un sistema de sello electrónico basado en certificado electrónico reconocido o cualificado.', true)) as v(label, body, ok)
)
