with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un servicio gestor quiere incluir tres facturas registradas en el Registro Contable de Facturas en un único documento contable que incorpora la fase O. ¿Cuándo es posible?', 'El apartado tercero.4 solo permite agrupar varias facturas en un documento con fase O cuando coincide la fecha de inicio del cómputo del plazo de pago.', 'age_adm_53_documentos_contables', (select id from public.topics where slug = 'age-adm-53-documentos-contables'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749'), 'Orden 1-2-1996 documentos contables, apdo. tercero.4', 'solo se podrán agrupar varias facturas en un mismo documento contable que incorpore la fase O, cuando la fecha en la que se inicia el cómputo de los plazos para el abono del precio sea la misma para todas ellas.', null, 'b6c4bf8b05ab0dbaabf7d90e3d2e87e0a7ccff3848b9288e0b96fee10719d0e9', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b6c4bf8b05ab0dbaabf7d90e3d2e87e0a7ccff3848b9288e0b96fee10719d0e9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Siempre, sin limitación alguna.', false), ('B', 'Solo si las tres facturas son del mismo proveedor y del mismo mes natural.', false), ('C', 'Solo cuando la fecha en que se inicia el cómputo de los plazos para el abono del precio sea la misma para todas ellas.', true), ('D', 'Nunca: cada factura exige su propio documento contable.', false)) as v(label, body, ok)
)
