with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una Subdirección General aprueba en un único acto la realización de un gasto y su adjudicación a una empresa concreta. ¿Qué documento contable debe expedir?', 'Si la autorización y el compromiso se acuerdan en un acto único, se expide un documento mixto AD; la acumulación produce los mismos efectos que actos separados (regla 24).', 'age_adm_53_documentos_contables', (select id from public.topics where slug = 'age-adm-53-documentos-contables'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-2627'), 'Regla 24.2 Instrucción de operatoria contable', 'cuando la autorización y el compromiso de gasto se acuerdan en un acto único, se expedirá un documento mixto AD.', null, '8b8f0451bb53ab6073aaca8ddf0a47bb0f0d774a2ca5883f3d93313eb8752041', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8b8f0451bb53ab6073aaca8ddf0a47bb0f0d774a2ca5883f3d93313eb8752041')
  returning id
), o as (
