  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un documento A y, al mes siguiente, un documento D.', false), ('B', 'Un documento mixto AD.', true), ('C', 'Un documento ADOK.', false), ('D', 'Un documento RC.', false)) as v(label, body, ok)
)
