with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un servicio gestor recibe la factura de una pequeña compra ya entregada y, en un mismo acto, aprueba el gasto, lo compromete con el proveedor y reconoce la obligación. ¿Qué documento contable expide?', 'Cuando un mismo acto acumula autorización, compromiso y reconocimiento de la obligación se expide un documento mixto ADOK (regla 24.2).', 'age_adm_53_documentos_contables', (select id from public.topics where slug = 'age-adm-53-documentos-contables'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-2627'), 'Regla 24.2 Instrucción de operatoria contable', 'Cuando en un mismo acto se acumulen la autorización del gasto, su compromiso y el reconocimiento de la obligación, se expedirá documento mixto ADOK.', null, 'f07b475845869104a64b08d4f013861cc6a7530ae8e25f1220fa9426b983e4e4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f07b475845869104a64b08d4f013861cc6a7530ae8e25f1220fa9426b983e4e4')
  returning id
), o as (
