with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un servicio gestor remite a la oficina de contabilidad un documento D sin todos los datos exigidos. Según la Instrucción de operatoria contable, la oficina:', 'Las oficinas de contabilidad no toman razón y devuelven los documentos si faltan documentos, requisitos o datos, si no se acompaña la justificación o si hay incoherencias con el sistema (regla 2.2).', 'age_adm_53_documentos_contables', (select id from public.topics where slug = 'age-adm-53-documentos-contables'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-2627'), 'Regla 2.2 Instrucción de operatoria contable', 'las oficinas de contabilidad no tomarán razón de las operaciones, procediendo a devolver a los Servicios gestores los correspondientes documentos contables electrónicos: […] Cuando no se hayan recibido todos los documentos que se precisen para el registro de la operación en cuestión, o bien cuando los documentos no contengan todos los requisitos o datos exigidos.', null, '90269ab8baf59b7e8df755adc0382ea32920bab094518823a4aba55a0aa38424', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '90269ab8baf59b7e8df755adc0382ea32920bab094518823a4aba55a0aa38424')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No tomará razón de la operación y devolverá el documento al servicio gestor.', true), ('B', 'Lo contabilizará y comunicará el defecto a la Intervención Delegada.', false), ('C', 'Completará de oficio los datos que falten.', false), ('D', 'Lo contabilizará provisionalmente durante diez días.', false)) as v(label, body, ok)
)
