  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Recibida de conformidad la prestación de un servicio contratado, la autoridad competente reconoce la obligación. Según la Instrucción de operatoria contable, ¿qué supone ese reconocimiento y qué documento se expide?', 'Salvo en operaciones de Deuda Pública (documentos O y K), el reconocimiento de la obligación lleva implícita la propuesta de pago y se registra con un documento OK (regla 23.3).', 'age_adm_53_documentos_contables', (select id from public.topics where slug = 'age-adm-53-documentos-contables'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-2627'), 'Regla 23.3 Instrucción de operatoria contable', 'todo reconocimiento de la obligación llevará implícita la correspondiente propuesta de pago […] Una vez acordado el reconocimiento de la obligación, el Servicio gestor competente expedirá un documento OK', null, '717eb248450bb6e17127a47739088688911e5f99da1e80a6675b409f76000451', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '717eb248450bb6e17127a47739088688911e5f99da1e80a6675b409f76000451')
  returning id
), o as (
