with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un Ministerio paga los reconocimientos médicos periódicos de su personal. Según el código de la clasificación económica de los gastos (Resolución de 20 de enero de 2014 de la Dirección General de Presupuestos), ¿dónde se imputa ese gasto?', 'El código incluye expresamente en el subconcepto 162.09 los gastos de reconocimiento médico del personal y los derivados de accidentes de trabajo. La Orden HAC/557/2026, de elaboración de los PGE para 2027 (anexo II), mantiene el concepto 162 con el subconcepto 09 «Otros».', 'age_adm_60_supuesto_practico', (select id from public.topics where slug = 'age-adm-60-supuesto-practico'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-879'), 'Anexo IV, concepto 162 (Resolución DGP 20/01/2014)', 'Concepto 162. Gastos sociales del personal. […] Gastos de reconocimiento médico del personal y aquellos derivados de accidentes de trabajo.', null, 'be44dcf17e5e382350daf458ed9a73f1fb775b44d9fbfea5fca7b4b6e5abd195', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'be44dcf17e5e382350daf458ed9a73f1fb775b44d9fbfea5fca7b4b6e5abd195')
  returning id
), o as (
