with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 7 del Tratado de la Unión Europea, ¿quién puede constatar la existencia de una violación grave y persistente por un Estado miembro de los valores del artículo 2?', 'El Consejo constata el «riesgo claro» por cuatro quintos (art. 7.1); la violación «grave y persistente» la constata el Consejo Europeo por unanimidad (art. 7.2).', 'age_adm_examen_2024_p1', (select id from public.topics where slug = 'age-adm-examen-2024-p1'), 3, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12016M/TXT'), 'Art. 7.2 TUE', 'El Consejo Europeo, por unanimidad y a propuesta de un tercio de los Estados miembros o de la Comisión y previa aprobación del Parlamento Europeo, podrá constatar la existencia de una violación grave y persistente', null, '3e3683a1ba50d5b65604de672eefbb495122bebfeb87eaf01509b1c7a5945f55', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3e3683a1ba50d5b65604de672eefbb495122bebfeb87eaf01509b1c7a5945f55')
  returning id
), o as (
