  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Consejo Europeo, por unanimidad, previa aprobación del Parlamento Europeo.', true), ('B', 'El Consejo, por mayoría de cuatro quintos de sus miembros.', false), ('C', 'El Tribunal de Justicia de la Unión Europea, a instancia de la Comisión.', false), ('D', 'El Parlamento Europeo, por mayoría de dos tercios.', false)) as v(label, body, ok)
)
