with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el preámbulo del Real Decreto 371/2026, que regula el Foro de Gobierno Abierto, ¿qué plan de gobierno abierto aprobó España en el marco de la Cumbre Global de la Alianza para el Gobierno Abierto?', 'El IV Plan (2020-2024) ya concluyó; el vigente es el V Plan de Gobierno Abierto 2025-2029, cuyo Compromiso 1 es el fortalecimiento de la participación y del espacio cívico.', 'age_adm_examen_2024_p1', (select id from public.topics where slug = 'age-adm-examen-2024-p1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2026-9880'), 'Preámbulo RD 371/2026 (V Plan de Gobierno Abierto)', 'el V Plan de Gobierno Abierto 2025-2029, aprobado por España en el marco de la Cumbre Global de la Alianza para el Gobierno Abierto', 'El original preguntaba cuántos ejes tenía el IV Plan de Gobierno Abierto (2020-2024), ya terminado. Se pregunta por el plan vigente; el texto oficial capturado no enumera sus ejes.', '6658621d680176cd94a5f82c000a9ba7822f4d017576a3ca3c41d61355efc8dc', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6658621d680176cd94a5f82c000a9ba7822f4d017576a3ca3c41d61355efc8dc')
