insert into public.topics (slug, title) values ('age-adm-examen-2024-p2', 'Examen réplica · OEP 2023-2024 (INAP) · Segunda parte: supuesto práctico (20 preguntas)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-examen-2024-p2' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El crédito para las ayudas resulta insuficiente y no ampliable, y la necesidad surge en operaciones no financieras del presupuesto del Estado. Según la Ley General Presupuestaria, el suplemento de crédito se financiará:', 'Si la necesidad surge en operaciones no financieras, se financia con baja en el Fondo de Contingencia u otros créditos no financieros (art. 55.1.a); la Deuda Pública es para operaciones financieras y el remanente de tesorería, para organismos autónomos.', 'age_adm_examen_2024_p2', (select id from public.topics where slug = 'age-adm-examen-2024-p2'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 55.1.a LGP', 'Si la necesidad surgiera en operaciones no financieras del presupuesto, el crédito extraordinario o suplementario se financiará mediante baja en los créditos del Fondo de Contingencia o en otros no financieros que se consideren adecuados.', null, '1ce2b06b369e709b9bda288fac0867d31c7074738f07fdcace3a29313e49e1da', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1ce2b06b369e709b9bda288fac0867d31c7074738f07fdcace3a29313e49e1da')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Mediante baja en los créditos del Fondo de Contingencia o en otros no financieros que se consideren adecuados.', true), ('B', 'Con Deuda Pública en todo caso.', false), ('C', 'Con el remanente de tesorería del ministerio.', false), ('D', 'Con mayores ingresos de las tasas del ministerio.', false)) as v(label, body, ok)
)
