insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-examen-2024-p2' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 38/2003, General de Subvenciones, ¿por qué normas se rigen las ayudas que prepara Dña. Lucía Ferrer?', 'El art. 5.1 fija el orden: Ley 38/2003 y su desarrollo, resto del derecho administrativo y, supletoriamente, derecho privado.', 'age_adm_examen_2024_p2', (select id from public.topics where slug = 'age-adm-examen-2024-p2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977'), 'Art. 5.1 LGS', 'Las subvenciones se regirán, en los términos establecidos en el artículo 3, por esta ley y sus disposiciones de desarrollo, las restantes normas de derecho administrativo, y, en su defecto, se aplicarán las normas de derecho privado.', null, '4cfaafd5a670a3e5d67be230899f05909605d2e61c2530a94630beaafd9dbfc2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4cfaafd5a670a3e5d67be230899f05909605d2e61c2530a94630beaafd9dbfc2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Exclusivamente por las bases reguladoras de cada convocatoria.', false), ('B', 'Por el Código Civil y, en su defecto, por la Ley General de Subvenciones.', false), ('C', 'Por la Ley de Contratos del Sector Público, por tratarse de gasto público.', false), ('D', 'Por esa ley y sus disposiciones de desarrollo, las restantes normas de derecho administrativo y, en su defecto, las de derecho privado.', true)) as v(label, body, ok)
)
