with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Antes de establecer las ayudas a ganaderos, el ministerio debe concretar sus objetivos, plazos, costes y fuentes de financiación en:', 'El art. 8.1 exige concretar con carácter previo, en un plan estratégico de subvenciones, objetivos, efectos, plazo, costes y fuentes de financiación.', 'age_adm_examen_2024_p2', (select id from public.topics where slug = 'age-adm-examen-2024-p2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977'), 'Art. 8.1 LGS', 'deberán concretar en un plan estratégico de subvenciones los objetivos y efectos que se pretenden con su aplicación, el plazo necesario para su consecución, los costes previsibles y sus fuentes de financiación', null, 'aeb63fc370292c7747ee20a57539001f69a110a1239d2cce156d4a7747de3ed1', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'aeb63fc370292c7747ee20a57539001f69a110a1239d2cce156d4a7747de3ed1')
  returning id
