)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 38/2003, ¿qué trámite debe efectuarse con carácter previo a la convocatoria de las ayudas?', 'La aprobación del gasto debe efectuarse antes de la convocatoria o de la concesión directa (art. 34.1); el reconocimiento de la obligación y el pago son posteriores.', 'age_adm_examen_2024_p2', (select id from public.topics where slug = 'age-adm-examen-2024-p2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977'), 'Art. 34.1 LGS', 'Con carácter previo a la convocatoria de la subvención o a la concesión directa de la misma, deberá efectuarse la aprobación del gasto', null, '7a621573279220c009dc284404ddfaff2f90b4ec26b3b20dc628d24bb110212b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7a621573279220c009dc284404ddfaff2f90b4ec26b3b20dc628d24bb110212b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El reconocimiento de la obligación.', false), ('B', 'La propuesta de pago.', false), ('C', 'La aprobación del gasto.', true), ('D', 'La justificación de las ayudas por los beneficiarios.', false)) as v(label, body, ok)
)
