with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un ganadero solicitante de las ayudas alega una incapacidad permanente. ¿Cuál de los siguientes NO es un grado de incapacidad permanente según el artículo 194 de la Ley General de la Seguridad Social?', 'Los grados son parcial, total, absoluta y gran incapacidad (art. 194.1). La incapacidad temporal es otra prestación distinta.', 'age_adm_examen_2024_p2', (select id from public.topics where slug = 'age-adm-examen-2024-p2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11724'), 'Art. 194.1 LGSS', 'a) Incapacidad permanente parcial. […] c) Incapacidad permanente absoluta. […] d) Gran incapacidad.', null, 'bb1f20629e0546a47ee566e17d4f36989038d98e444cb3eb6fb71c3485d50ba2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'bb1f20629e0546a47ee566e17d4f36989038d98e444cb3eb6fb71c3485d50ba2')
  returning id
