insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 53/1984, de 26 de diciembre, de Incompatibilidades del personal al servicio de las Administraciones Públicas (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-151', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-adm-examen-2024-p2', 'Examen réplica · OEP 2023-2024 (INAP) · Segunda parte: supuesto práctico (20 preguntas)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-examen-2024-p2' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Dña. Lucía Ferrer, que redacta la convocatoria de ayudas a ganaderos, recibe una oferta para asesorar por las tardes a una asociación ganadera que va a solicitarlas. Según la Ley 53/1984, esa actividad:', 'El art. 12.1.a prohíbe en todo caso las actividades privadas en asuntos en que el empleado esté interviniendo, haya intervenido en los dos últimos años o tenga que intervenir por razón de su puesto.', 'age_adm_examen_2024_p2', (select id from public.topics where slug = 'age-adm-examen-2024-p2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-151'), 'Art. 12.1.a Ley 53/1984', 'El desempeño de actividades privadas, incluidas las de carácter profesional, sea por cuenta propia o bajo la dependencia o al servicio de Entidades o particulares, en los asuntos en que esté interviniendo, haya intervenido en los dos últimos años o tenga que intervenir por razón del puesto público.', null, '3a512065c3aa3eed98ae05680345e8b54a2ffc1c5e4a79489923b24aa2b1ec18', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3a512065c3aa3eed98ae05680345e8b54a2ffc1c5e4a79489923b24aa2b1ec18')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es compatible si la realiza fuera de su horario de trabajo.', false), ('B', 'Es incompatible en todo caso, porque se refiere a asuntos en los que interviene por razón de su puesto.', true), ('C', 'Es compatible si obtiene la autorización del Subsecretario.', false), ('D', 'Es compatible si no percibe más del 30 % de sus retribuciones.', false)) as v(label, body, ok)
)
