-- Lote age-adm-examen-2024-p2-lopdgdd-v1 (3 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 3/2018, de 5 de diciembre, de Protección de Datos Personales y garantía de los derechos digitales (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2018-16673', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-adm-examen-2024-p2', 'Examen réplica · OEP 2023-2024 (INAP) · Segunda parte: supuesto práctico (20 preguntas)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-examen-2024-p2' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El delegado de protección de datos del ministerio pide a la unidad de Dña. Lucía Ferrer acceso a los datos personales de los solicitantes de las ayudas para revisar su tratamiento. La unidad se opone alegando el deber de confidencialidad. Según la Ley Orgánica 3/2018:', 'En el ejercicio de sus funciones el DPD tiene acceso a los datos personales y procesos de tratamiento, sin que pueda oponérsele deber de confidencialidad o secreto alguno (art. 36.3).', 'age_adm_examen_2024_p2', (select id from public.topics where slug = 'age-adm-examen-2024-p2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2018-16673'), 'Art. 36.3 LOPDGDD', 'En el ejercicio de sus funciones el delegado de protección de datos tendrá acceso a los datos personales y procesos de tratamiento, no pudiendo oponer a este acceso el responsable o el encargado del tratamiento la existencia de cualquier deber de confidencialidad o secreto', null, 'aa1a9f22f586e272dfb64a68e713a334cfdf863a80f65e6fa56f1b25ef914a3b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'aa1a9f22f586e272dfb64a68e713a334cfdf863a80f65e6fa56f1b25ef914a3b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El delegado tiene acceso a los datos y no se le puede oponer ningún deber de confidencialidad o secreto.', true), ('B', 'El delegado solo puede acceder con autorización judicial.', false), ('C', 'El delegado solo puede acceder a datos anonimizados.', false), ('D', 'La unidad puede negarse si los datos son de categorías especiales.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un solicitante de las ayudas presenta una reclamación ante la Agencia Española de Protección de Datos, que la remite al delegado de protección de datos del ministerio. ¿En qué plazo debe responder el delegado?', 'Si la reclamación se presenta ante la AEPD y esta la remite al DPD, el DPD debe responder en un mes (art. 37.2). Los dos meses del art. 37.1 son para cuando el afectado se dirige primero al DPD.', 'age_adm_examen_2024_p2', (select id from public.topics where slug = 'age-adm-examen-2024-p2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2018-16673'), 'Art. 37.2 LOPDGDD', 'aquellas podrán remitir la reclamación al delegado de protección de datos a fin de que este responda en el plazo de un mes.', null, '3b32f8480cc596229c0c3b78cca9fb1a864b727d4dcc184b85b983432fecee65', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3b32f8480cc596229c0c3b78cca9fb1a864b727d4dcc184b85b983432fecee65')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En el plazo de un mes.', true), ('B', 'En el plazo de dos meses.', false), ('C', 'En el plazo de diez días hábiles.', false), ('D', 'En el plazo de tres meses.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Antes de admitir la reclamación, la AEPD advierte al ministerio, que adopta medidas correctivas que ponen fin al posible incumplimiento sin que se haya causado perjuicio al afectado. Según la Ley Orgánica 3/2018, la Agencia:', 'Es una facultad («podrá inadmitir») cuando, tras la advertencia, el responsable ha adoptado medidas correctivas y concurre alguna de las circunstancias del art. 65.3. La inadmisión obligatoria («inadmitirá») es la del art. 65.2.', 'age_adm_examen_2024_p2', (select id from public.topics where slug = 'age-adm-examen-2024-p2'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2018-16673'), 'Art. 65.3 LOPDGDD', 'Igualmente, la Agencia Española de Protección de Datos podrá inadmitir la reclamación cuando el responsable o encargado del tratamiento, previa advertencia formulada por la Agencia Española de Protección de Datos, hubiera adoptado las medidas correctivas', null, 'd49f9930584e58896fe2b3ef8f016ce7efecd032e61d7b75acbf6a14a32c6691', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd49f9930584e58896fe2b3ef8f016ce7efecd032e61d7b75acbf6a14a32c6691')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Deberá inadmitirla en todo caso.', false), ('B', 'Deberá admitirla y sancionar en todo caso al ministerio.', false), ('C', 'Podrá inadmitir la reclamación.', true), ('D', 'Deberá remitirla al Defensor del Pueblo.', false)) as v(label, body, ok)
)
