-- Lote age-adm-examen-2024-p2-lpac-v1 (3 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-adm-examen-2024-p2', 'Examen réplica · OEP 2023-2024 (INAP) · Segunda parte: supuesto práctico (20 preguntas)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-examen-2024-p2' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Dña. Lucía Ferrer informa un recurso de alzada que ya ha sido desestimado por el Ministro. El interesado pregunta qué recurso administrativo puede interponer ahora contra esa resolución. Según la Ley 39/2015:', 'Contra la resolución de un recurso de alzada solo cabe, en vía administrativa, el recurso extraordinario de revisión en los supuestos tasados (art. 122.3); queda abierta la vía contencioso-administrativa.', 'age_adm_examen_2024_p2', (select id from public.topics where slug = 'age-adm-examen-2024-p2'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 122.3 LPAC', 'Contra la resolución de un recurso de alzada no cabrá ningún otro recurso administrativo, salvo el recurso extraordinario de revisión, en los casos establecidos en el artículo 125.1.', null, '5c4f0d09c5d6ff02a903e61fc4bd73ca02b5eefccff3d4680dfadbb597c844ab', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5c4f0d09c5d6ff02a903e61fc4bd73ca02b5eefccff3d4680dfadbb597c844ab')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un recurso potestativo de reposición ante el mismo Ministro.', false), ('B', 'Un segundo recurso de alzada ante el Consejo de Ministros.', false), ('C', 'Ningún otro recurso administrativo, salvo el extraordinario de revisión en los casos del artículo 125.1.', true), ('D', 'Una reclamación previa ante el Consejo de Estado.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Al tramitar un recurso de alzada, Dña. Lucía Ferrer advierte que deben tenerse en cuenta documentos que no estaban en el expediente originario. Según la Ley 39/2015, ¿qué plazo debe darse a los interesados para formular alegaciones?', 'Cuando hayan de tenerse en cuenta nuevos hechos o documentos, se ponen de manifiesto a los interesados por un plazo de diez a quince días (art. 118.1).', 'age_adm_examen_2024_p2', (select id from public.topics where slug = 'age-adm-examen-2024-p2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 118.1 LPAC', 'Cuando hayan de tenerse en cuenta nuevos hechos o documentos no recogidos en el expediente originario, se pondrán de manifiesto a los interesados para que, en un plazo no inferior a diez días ni superior a quince, formulen las alegaciones', null, '9ef190d8dcf06d1cb3e820877533db8ae0d01d808184d2c20cb33a9b622ddac9', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9ef190d8dcf06d1cb3e820877533db8ae0d01d808184d2c20cb33a9b622ddac9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No inferior a cinco días ni superior a diez.', false), ('B', 'Un mes.', false), ('C', 'Veinte días hábiles.', false), ('D', 'No inferior a diez días ni superior a quince.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un interesado presenta un escrito titulado «recurso de reposición» contra una resolución de un Director General que no pone fin a la vía administrativa; de su contenido se deduce que lo que pretende es que la revise el órgano superior. ¿Qué debe hacer la unidad de Dña. Lucía Ferrer?', 'El error o la ausencia de calificación no es obstáculo para tramitar el recurso, siempre que se deduzca su verdadero carácter (art. 115.2); contra actos que no agotan la vía procede la alzada.', 'age_adm_examen_2024_p2', (select id from public.topics where slug = 'age-adm-examen-2024-p2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 115.2 LPAC', 'El error o la ausencia de la calificación del recurso por parte del recurrente no será obstáculo para su tramitación, siempre que se deduzca su verdadero carácter.', null, '971079bd4eac8d7fb448114087465fe384226f52f3670251ac9d2f31e534e853', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '971079bd4eac8d7fb448114087465fe384226f52f3670251ac9d2f31e534e853')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Inadmitirlo por error en la calificación del recurso.', false), ('B', 'Tramitarlo como recurso de alzada, porque el error en la calificación no impide su tramitación si se deduce su verdadero carácter.', true), ('C', 'Requerir al interesado para que presente un nuevo escrito con la calificación correcta, con apercibimiento de desistimiento.', false), ('D', 'Tramitarlo como recurso de reposición, ya que el órgano está vinculado por la calificación del recurrente.', false)) as v(label, body, ok)
)
