select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
-- Lote age-adm-examen-2024-p2-rd33-v1 (1 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 33/1986, de 10 de enero, Reglamento de Régimen Disciplinario de los Funcionarios de la Administración del Estado (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-adm-examen-2024-p2', 'Examen réplica · OEP 2023-2024 (INAP) · Segunda parte: supuesto práctico (20 preguntas)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-examen-2024-p2' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El funcionario expedientado pertenece al subgrupo A2. Según el Reglamento de Régimen Disciplinario (RD 33/1986), ¿quién puede ser nombrado instructor del expediente?', 'El instructor debe ser funcionario de un cuerpo o escala de igual o superior grupo al del inculpado; si depende de otro Departamento, se necesita autorización previa de su Subsecretario (art. 30).', 'age_adm_examen_2024_p2', (select id from public.topics where slug = 'age-adm-examen-2024-p2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-1216'), 'Art. 30 RD 33/1986', 'En la resolución por la que se incoe el procedimiento se nombrará Instructor, que deberá ser un funcionario público perteneciente a un cuerpo o escala de igual o superior grupo al del inculpado', null, '8cf2e2951a3933b5255bbb9bca62a2851c052293f8c2ab2a2d6652e61ca5e3dd', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8cf2e2951a3933b5255bbb9bca62a2851c052293f8c2ab2a2d6652e61ca5e3dd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un funcionario de un cuerpo o escala de igual o superior grupo al del inculpado.', true), ('B', 'Cualquier empleado público del Departamento, incluido personal laboral.', false), ('C', 'Solo un funcionario del subgrupo A1 con más de diez años de servicio.', false), ('D', 'Un letrado de la Abogacía del Estado.', false)) as v(label, body, ok)
