with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 3 del Reglamento (UE) 2024/1689, de inteligencia artificial, un «sistema de IA» es un sistema basado en una máquina que:', 'La definición legal subraya la autonomía, la adaptación y la inferencia para generar resultados de salida.', 'age_adm_examen_2025_p1', (select id from public.topics where slug = 'age-adm-examen-2025-p1'), 3, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/HTML/?uri=CELEX:32024R1689'), 'Sistema de IA (Reglamento UE 2024/1689)', '«sistema de IA»: un sistema basado en una máquina que está diseñado para funcionar con distintos niveles de autonomía y que puede mostrar capacidad de adaptación tras el despliegue, y que, para objetivos explícitos o implícitos, infiere de la información de entrada que recibe la manera de generar resultados de salida', 'La pregunta oficial trataba de la «web 4.0»; no hay definición oficial de ese término, así que la réplica pregunta por el concepto de IA con su definición legal.', '81db848b20cffba5439a5f0a90011a67f669142117dfe1f8f3288584a8f416a1', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '81db848b20cffba5439a5f0a90011a67f669142117dfe1f8f3288584a8f416a1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ejecuta siempre instrucciones fijas sin ningún grado de autonomía.', false), ('B', 'Infiere de la información de entrada que recibe la manera de generar resultados de salida, como predicciones, contenidos, recomendaciones o decisiones.', true), ('C', 'Solo funciona conectado a internet mediante la web semántica.', false), ('D', 'Se limita a almacenar páginas web dinámicas.', false)) as v(label, body, ok)
)
