with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 121 de la Ley 7/1985, el régimen de los municipios de gran población se aplica directamente, sin decisión de la Asamblea Legislativa autonómica:', 'Los supuestos de las letras a) y b) se aplican por la propia ley; para los de las letras c) (capitales y sedes autonómicas) y d) (más de 75.000 con circunstancias especiales) hace falta que lo decida la Asamblea Legislativa a iniciativa del ayuntamiento.', 'age_adm_examen_2025_p1', (select id from public.topics where slug = 'age-adm-examen-2025-p1'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392'), 'Art. 121.1 Ley 7/1985', 'a) A los municipios cuya población supere los 250.000 habitantes. […] En los supuestos previstos en los párrafos c) y d), se exigirá que así lo decidan las Asambleas Legislativas correspondientes a iniciativa de los respectivos ayuntamientos.', null, '5ffe5a043b882f27a5bdae27332a5b92f9a4a5a6ec2f6076b8dd028738d1e1bb', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5ffe5a043b882f27a5bdae27332a5b92f9a4a5a6ec2f6076b8dd028738d1e1bb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A todos los municipios capitales de provincia, cualquiera que sea su población.', false), ('B', 'A los municipios de más de 75.000 habitantes con circunstancias históricas especiales.', false), ('C', 'A los municipios cuya población supere los 250.000 habitantes.', true), ('D', 'A los municipios que sean sedes de instituciones autonómicas.', false)) as v(label, body, ok)
)
