  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Tras un diálogo competitivo, un Ministerio celebra un contrato con precios provisionales. Según el artículo 102.7 de la Ley 9/2017:', 'El art. 102.7 LCSP determina el precio definitivo en función de los costes reales y excluye expresamente la revisión de precios.', 'age_adm_examen_2025_p1', (select id from public.topics where slug = 'age-adm-examen-2025-p1'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 102.7 Ley 9/2017', 'En los contratos celebrados con precios provisionales no cabrá la revisión de precios.', null, 'bbba1cd2f5be6732dc635a07731bfc90ebcabbf5de7e600a3c11f95a19699c70', false
