  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El director de un organismo autónomo de la AGE va a conceder una subvención de 15 millones de euros. Según el artículo 10 de la Ley 38/2003:', 'Presidentes o directores de organismos son competentes (art. 10.1); por encima de 12 millones se requiere autorización del Consejo de Ministros (10.2); las facultades pueden desconcentrarse (10.3).', 'age_adm_examen_2025_p1', (select id from public.topics where slug = 'age-adm-examen-2025-p1'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-20977'), 'Art. 10 Ley 38/2003', 'la concesión de subvenciones de cuantía superior a 12 millones de euros requerirá la previa autorización del Consejo de Ministros […] Las facultades para conceder subvenciones, a que se refiere este artículo, podrán ser objeto de desconcentración mediante real decreto acordado en Consejo de Ministros.', null, 'fd4587f47a2b069019b1f715b5e7916f6b795bb7f4cdf82c5eae8b6e680828de', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'fd4587f47a2b069019b1f715b5e7916f6b795bb7f4cdf82c5eae8b6e680828de')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Solo puede concederla el Ministro de adscripción.', false), ('B', 'Es el órgano competente, pero necesita la previa autorización del Consejo de Ministros, y sus facultades pueden desconcentrarse por real decreto.', true), ('C', 'Puede concederla sin autorización, porque el límite de 12 millones solo rige para los Ministerios.', false), ('D', 'Necesita autorización de las Cortes Generales.', false)) as v(label, body, ok)
)
