  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una funcionaria con dos trienios en un cuerpo del subgrupo C2 accede a un cuerpo del subgrupo C1. Según el artículo 23 de la Ley 30/1984:', 'El art. 23.2.b) conserva los trienios devengados en los grupos anteriores cuando se prestan servicios sucesivos en cuerpos de distinto grupo.', 'age_adm_examen_2025_p1', (select id from public.topics where slug = 'age-adm-examen-2025-p1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-17387'), 'Art. 23.2.b) Ley 30/1984', 'En el caso de que un funcionario preste sus servicios sucesivamente en diferentes Cuerpos, Escalas, Clases o Categorías de distinto grupo de clasificación, tendrá derecho a seguir percibiendo los trienios devengados en los grupos anteriores.', null, 'e291cd4f05c5716cf1793d909f6b489c750c197253edd3d28f30714d3d2de6bc', false
