with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 5 de la Ley Orgánica 3/2018, el deber de confidencialidad de quienes intervienen en un tratamiento de datos:', 'El art. 5.1 extiende el deber a responsables, encargados y cualquier interviniente; el art. 5.3 lo mantiene tras finalizar la relación.', 'age_adm_examen_2025_p1', (select id from public.topics where slug = 'age-adm-examen-2025-p1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2018-16673'), 'Art. 5.1 y 5.3 LO 3/2018', 'Los responsables y encargados del tratamiento de datos así como todas las personas que intervengan en cualquier fase de este estarán sujetas al deber de confidencialidad […] Las obligaciones establecidas en los apartados anteriores se mantendrán aun cuando hubiese finalizado la relación del obligado con el responsable o encargado del tratamiento.', null, '70bfe056ac34b6315cec6de1d27c706c312924b7bd1a86592b6aab1b53c98338', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '70bfe056ac34b6315cec6de1d27c706c312924b7bd1a86592b6aab1b53c98338')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Solo afecta a los responsables del tratamiento y se extingue al cesar en el puesto.', false), ('B', 'Afecta únicamente a los empleados públicos sujetos a secreto profesional.', false), ('C', 'Afecta a responsables, encargados y a todas las personas que intervengan en cualquier fase del tratamiento, y se mantiene aunque haya finalizado su relación con el responsable o encargado.', true), ('D', 'Se limita al delegado de protección de datos.', false)) as v(label, body, ok)
)
