with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 2 de la Ley Orgánica 2/1982, son funciones propias del Tribunal de Cuentas:', 'La función interventora y el control financiero permanente son de la IGAE; la Cuenta General la aprueban las Cortes. Al Tribunal le corresponden la fiscalización externa y el enjuiciamiento contable.', 'age_adm_examen_2025_p1', (select id from public.topics where slug = 'age-adm-examen-2025-p1'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1982-11584'), 'Art. 2 LO 2/1982', 'a) La fiscalización externa, permanente y consuntiva de la actividad económico-financiera del sector público. b) El enjuiciamiento de la responsabilidad contable en que incurran quienes tengan a su cargo el manejo de caudales o efectos públicos.', null, '2d8af5f91d479f82fe9fbb81129b095ad244581776f41809a4486c6d199ccd93', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2d8af5f91d479f82fe9fbb81129b095ad244581776f41809a4486c6d199ccd93')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La función interventora previa de todos los gastos del Estado.', false), ('B', 'El control financiero permanente de los organismos autónomos.', false), ('C', 'La fiscalización externa, permanente y consuntiva de la actividad económico-financiera del sector público y el enjuiciamiento de la responsabilidad contable.', true), ('D', 'La aprobación de la Cuenta General del Estado.', false)) as v(label, body, ok)
)
