with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 16.1 de la Ley 39/2015, los Organismos públicos vinculados o dependientes de una Administración:', 'El art. 16.1 LPAC configura el registro propio de los organismos como una posibilidad («podrán»), siempre interoperable con el Registro Electrónico General.', 'age_adm_examen_2025_p1', (select id from public.topics where slug = 'age-adm-examen-2025-p1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 16.1 Ley 39/2015', 'Los Organismos públicos vinculados o dependientes de cada Administración podrán disponer de su propio registro electrónico plenamente interoperable e interconectado con el Registro Electrónico General de la Administración de la que depende.', null, '8e2adad8db212e516dffbfb8af2370826aef6ef9d745a6af1468ee8416a4d6e2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8e2adad8db212e516dffbfb8af2370826aef6ef9d745a6af1468ee8416a4d6e2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Podrán disponer de su propio registro electrónico, plenamente interoperable e interconectado con el Registro Electrónico General de su Administración.', true), ('B', 'Deberán disponer en todo caso de su propio registro electrónico independiente.', false), ('C', 'No pueden tener registro propio y deben usar el de su Ministerio de adscripción.', false), ('D', 'Podrán tener registro propio solo si lo autoriza el Consejo de Ministros.', false)) as v(label, body, ok)
)
