with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un servicio gestor tramita anticipadamente un contrato cuyo gasto se imputará a presupuestos futuros. Según la regla 42 de la Instrucción de operatoria contable (Orden de 1 de febrero de 1996), ¿qué documento expide primero?', 'Se expide un RC de «tramitación anticipada»; aprobado el gasto, un A de tramitación anticipada y, si se adjudica en el mismo ejercicio, un D (o AD si se acumulan fases).', 'age_adm_examen_2025_p1', (select id from public.topics where slug = 'age-adm-examen-2025-p1'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-2627'), 'Regla 42 Orden 1/2/1996 (operatoria contable)', 'un documento RC de "tramitación anticipada" detallando el importe que del gasto en cuestión corresponde a cada uno de los ejercicios posteriores afectados.', null, '763f41d840950b9491f0ffe1cc6d605442878a069412c394aa960c43e7feeec9', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '763f41d840950b9491f0ffe1cc6d605442878a069412c394aa960c43e7feeec9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un documento RC de «tramitación anticipada», con el importe que corresponde a cada ejercicio posterior afectado.', true), ('B', 'Un documento A de «ejercicio corriente».', false), ('C', 'Un documento ADOK de «ejercicios posteriores».', false), ('D', 'Un documento RC de «ejercicio corriente» y otro de «ejercicios posteriores».', false)) as v(label, body, ok)
)
