with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En informática, la unidad funcional de un ordenador que se encarga de buscar, interpretar y ejecutar las instrucciones es:', 'El DLE define el procesador como la unidad que busca, interpreta y ejecuta instrucciones; el byte es una unidad de información de ocho bits.', 'age_adm_examen_2025_p1', (select id from public.topics where slug = 'age-adm-examen-2025-p1'), 1, 'es', true, (select id from public.sources where url = 'https://dle.rae.es/'), 'Procesador (DLE)', 'procesador: m. Informática Unidad funcional de una computadora u otro dispositivo electrónico, que se encarga de la búsqueda, interpretación y ejecución de instrucciones.', null, '466332153ea5570b7a06bdec8c4a80487a6fedc81378105b68bc1e332514bf24', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '466332153ea5570b7a06bdec8c4a80487a6fedc81378105b68bc1e332514bf24')
  returning id
), o as (
