with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Diccionario de la lengua española, ¿qué memoria de acceso rápido guarda temporalmente las últimas informaciones procesadas por el ordenador?', 'El DLE define la memoria caché como la memoria de acceso rápido que guarda temporalmente las últimas informaciones procesadas.', 'age_adm_examen_2025_p1', (select id from public.topics where slug = 'age-adm-examen-2025-p1'), 2, 'es', true, (select id from public.sources where url = 'https://dle.rae.es/'), 'Memoria caché (DLE)', 'memoria caché: f. Informática memoria (➝ 1b) de acceso rápido de una computadora u otro dispositivo electrónico, que guarda temporalmente las últimas informaciones procesadas.', 'La pregunta oficial trataba de la memoria RAM; el DLE no tiene entrada para «RAM», así que la réplica usa el concepto más próximo con definición oficial.', '10f2cbc851b8e7f84cad5ab16e94441a7f064fd19997f674db18c0cb1d08b6a7', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '10f2cbc851b8e7f84cad5ab16e94441a7f064fd19997f674db18c0cb1d08b6a7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La memoria caché.', true), ('B', 'El disco duro.', false), ('C', 'La memoria USB.', false), ('D', 'El procesador de textos.', false)) as v(label, body, ok)
)
