  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un cajero pagador recibe fondos «a justificar» el 1 de marzo y los invierte el 10 de abril. Según el artículo 10.1 del Real Decreto 640/1987, debe justificar su aplicación:', 'El art. 10.1 fija el mes siguiente a la inversión, con el límite de tres meses desde la percepción, sin perjuicio del art. 11.', 'age_adm_examen_2025_p1', (select id from public.topics where slug = 'age-adm-examen-2025-p1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1987-12158'), 'Art. 10.1 RD 640/1987', 'Los Cajeros pagadores quedarán obligados a justificar la aplicación de las cantidades recibidas dentro del mes siguiente a la inversión de las mismas y en todo caso en el plazo de tres meses desde la percepción de los correspondientes fondos', null, '3c1833901f6d00f9a6ffa07764a982371be7fa84541a3ad0091a9265b4df20b2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3c1833901f6d00f9a6ffa07764a982371be7fa84541a3ad0091a9265b4df20b2')
