with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 56 del TREBEP, ¿qué requisito de edad es necesario con carácter general para participar en un proceso selectivo?', 'El art. 56.1.c) fija los dieciséis años y la edad de jubilación forzosa; solo por ley puede establecerse otra edad máxima.', 'age_adm_examen_2025_p1', (select id from public.topics where slug = 'age-adm-examen-2025-p1'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 56.1.c) TREBEP', 'c) Tener cumplidos dieciséis años y no exceder, en su caso, de la edad máxima de jubilación forzosa. Sólo por ley podrá establecerse otra edad máxima, distinta de la edad de jubilación forzosa, para el acceso al empleo público.', null, 'cf9b7b8181d34fb95f070225e6b6fcd621b48c78aaaf49e7def701dfe2d343ac', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'cf9b7b8181d34fb95f070225e6b6fcd621b48c78aaaf49e7def701dfe2d343ac')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tener cumplidos dieciocho años y no superar los sesenta y cinco.', false), ('B', 'Ser mayor de edad, sin límite máximo.', false), ('C', 'Tener cumplidos dieciséis años, sin que pueda fijarse por ley otra edad máxima.', false), ('D', 'Tener cumplidos dieciséis años y no exceder, en su caso, de la edad máxima de jubilación forzosa.', true)) as v(label, body, ok)
)
