with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Autorizado el suplemento de crédito de 15.000 euros para los ascensores de la Confederación, ¿qué documento contable registra esa operación?', 'El documento MC se usa en las modificaciones presupuestarias que aumentan o disminuyen los créditos. RC retiene crédito, A aprueba gasto y ADOK acumula fases de ejecución.', 'age_adm_examen_2025_p2', (select id from public.topics where slug = 'age-adm-examen-2025-p2'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-2749'), 'Orden 1-2-1996 documentos contables, regla 1.a', 'Documento MC: Se utilizará en las modificaciones presupuestarias que aumenten o disminuyan los créditos.', null, '09d82baa6b5248411faf4b2cb42a8d375a684fc5270e5bda8382a673959a4f00', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '09d82baa6b5248411faf4b2cb42a8d375a684fc5270e5bda8382a673959a4f00')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
