with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Tras la queja, la Confederación prepara un contrato de obras para instalar una rampa y una plataforma elevadora en su sede, con un valor estimado de 98.000 euros. ¿Está sujeto a regulación armonizada?', 'Los contratos de obras son SARA cuando su valor estimado es igual o superior a 5.404.000 euros (art. 20.1); 40.000 euros es el límite del contrato menor de obras.', 'age_adm_examen_2025_p2', (select id from public.topics where slug = 'age-adm-examen-2025-p2'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 20.1 LCSP', 'Están sujetos a regulación armonizada los contratos de obras, de concesión de obras y de concesión de servicios cuyo valor estimado sea igual o superior a 5.404.000 euros.', null, '43b4bfccbfe33fa6dce76e4c82c2b42eaeebf97e26bc84d03db252188ee96e32', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '43b4bfccbfe33fa6dce76e4c82c2b42eaeebf97e26bc84d03db252188ee96e32')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No, porque el umbral de los contratos de obras es un valor estimado igual o superior a 5.404.000 euros.', true), ('B', 'Sí, porque todos los contratos de obras de organismos autónomos están sujetos a regulación armonizada.', false), ('C', 'Sí, porque supera los 40.000 euros de valor estimado.', false), ('D', 'No, porque las obras de accesibilidad están excluidas de la Ley 9/2017.', false)) as v(label, body, ok)
)
