with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'La Confederación adjudica la obra de accesibilidad (valor estimado de 98.000 euros) por el procedimiento abierto simplificado. ¿Dónde debe publicarse el anuncio de licitación?', 'En el abierto simplificado el anuncio únicamente precisa publicarse en el perfil de contratante, y toda la documentación debe estar disponible electrónicamente desde ese día (art. 159.2).', 'age_adm_examen_2025_p2', (select id from public.topics where slug = 'age-adm-examen-2025-p2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 159.2 LCSP', 'El anuncio de licitación del contrato únicamente precisará de publicación en el perfil de contratante del órgano de contratación.', null, '717293f4c82b0ae76aac48aab75f4475f958e5b7493019e1b93f1a88bf44d7e9', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '717293f4c82b0ae76aac48aab75f4475f958e5b7493019e1b93f1a88bf44d7e9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En el Diario Oficial de la Unión Europea y en el perfil de contratante.', false), ('B', 'Únicamente en el perfil de contratante del órgano de contratación.', true), ('C', 'En el «Boletín Oficial del Estado» y en el perfil de contratante.', false), ('D', 'No requiere anuncio, porque se invita directamente a tres empresas.', false)) as v(label, body, ok)
)
