with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'La mejor oferta para la obra de accesibilidad de la Confederación asciende a 80.000 euros más 16.800 euros de IVA. Si el pliego no prevé garantía complementaria, ¿cuál será la garantía definitiva?', 'La garantía definitiva es el 5 % del precio final ofertado, excluido el IVA: 5 % de 80.000 = 4.000 euros (art. 107.1). 4.840 resulta de aplicar el 5 % con IVA (96.800) y 8.000 sería un 10 %.', 'age_adm_examen_2025_p2', (select id from public.topics where slug = 'age-adm-examen-2025-p2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2017-12902'), 'Art. 107.1 LCSP', 'deberán constituir a disposición del órgano de contratación una garantía de un 5 por 100 del precio final ofertado por aquellos, excluido el Impuesto sobre el Valor Añadido.', null, '1ff0298c0d94d2ecf7e30405417e2dff415da8325031012e5e91109a222af7de', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1ff0298c0d94d2ecf7e30405417e2dff415da8325031012e5e91109a222af7de')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '4.000 euros.', true), ('B', '4.840 euros.', false), ('C', '4.900 euros.', false), ('D', '8.000 euros.', false)) as v(label, body, ok)
)
