insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 47/2003, de 26 de noviembre, General Presupuestaria (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-adm-examen-2025-p2', 'Examen réplica · Convocatoria 2025 (INAP) · Segunda parte: supuesto práctico (20 preguntas)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-examen-2025-p2' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El contrato de mantenimiento de ascensores de la Confederación (organismo autónomo) necesita 15.000 euros más de lo presupuestado y el crédito no es ampliable. El capítulo 2 de su presupuesto inicial de gastos es de 120.000 euros y no hay otras modificaciones en el ejercicio. ¿Quién autoriza el suplemento de crédito?', '15.000 euros son el 12,5 % del capítulo: supera el 10 % que permite autorizar al Presidente o Director, pero no llega al 20 % ni a 1.000.000 de euros, así que corresponde al Ministro de Hacienda (art. 56.3.b).', 'age_adm_examen_2025_p2', (select id from public.topics where slug = 'age-adm-examen-2025-p2'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 56.3 LGP', 'Al Ministro de Hacienda cuando, superándose alguno de los anteriores límites, no se alcance el 20 % del correspondiente capítulo de su presupuesto inicial de gastos ni se supere la cuantía de 1.000.000 de euros.', null, '86d5aa80838addf219585efb444e48d4684a25705aa673480bec113869c6c261', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '86d5aa80838addf219585efb444e48d4684a25705aa673480bec113869c6c261')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Presidente de la Confederación.', false), ('B', 'El Consejo de Ministros.', false), ('C', 'El Ministro de Hacienda.', true), ('D', 'Las Cortes Generales mediante ley.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Con qué recursos podrá financiar la Confederación Hidrográfica del Tajo (organismo autónomo) el suplemento de crédito para el mantenimiento de los ascensores?', 'Los créditos extraordinarios y suplementarios de los organismos autónomos solo pueden financiarse con remanente de tesorería no aplicado o con mayores ingresos (art. 56.2). El Fondo de Contingencia es la financiación de los del Estado (art. 55).', 'age_adm_examen_2025_p2', (select id from public.topics where slug = 'age-adm-examen-2025-p2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614'), 'Art. 56.2 LGP', 'La financiación de los créditos extraordinarios o suplementarios únicamente podrá realizarse con cargo a la parte del remanente de tesorería al fin del ejercicio anterior que no haya sido aplicada en el presupuesto del organismo, o con mayores ingresos sobre los previstos inicialmente.', null, 'c802fd646b87559e25b4c80bc3e78aff061bc8b82862ab61761931f15ab9e485', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c802fd646b87559e25b4c80bc3e78aff061bc8b82862ab61761931f15ab9e485')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Exclusivamente con baja en el Fondo de Contingencia del Estado.', false), ('B', 'Con Deuda Pública emitida por el propio organismo.', false), ('C', 'Con baja en cualquier crédito de otro ministerio.', false), ('D', 'Con la parte del remanente de tesorería al fin del ejercicio anterior no aplicada en su presupuesto, o con mayores ingresos sobre los previstos.', true)) as v(label, body, ok)
)
