-- Lote age-adm-examen-2025-p2-lpac-v1 (5 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-adm-examen-2025-p2', 'Examen réplica · Convocatoria 2025 (INAP) · Segunda parte: supuesto práctico (20 preguntas)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-examen-2025-p2' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D. Martín Olmedo presenta en la Confederación Hidrográfica del Tajo una solicitud de autorización de obras en zona de policía de cauces sin firmar ni acreditar de otro modo la autenticidad de su voluntad. Se le requiere para subsanarlo y deja pasar el plazo sin hacer nada. Según la Ley 39/2015, ¿qué ocurre?', 'La firma (o acreditación de la voluntad) es contenido obligatorio de la solicitud (art. 66.1.e). Si no se subsana en plazo, se tiene al interesado por desistido, pero siempre previa resolución (art. 68.1 en relación con el art. 21).', 'age_adm_examen_2025_p2', (select id from public.topics where slug = 'age-adm-examen-2025-p2'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 68.1 LPAC', 'se requerirá al interesado para que, en un plazo de diez días, subsane la falta o acompañe los documentos preceptivos, con indicación de que, si así no lo hiciera, se le tendrá por desistido de su petición, previa resolución que deberá ser dictada en los términos previstos en el artículo 21.', null, 'efe796ae0dfce3f99bfc7dcfa103e4affafbd7a4a55da86f8d41b55fa9decdf4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'efe796ae0dfce3f99bfc7dcfa103e4affafbd7a4a55da86f8d41b55fa9decdf4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La solicitud se entiende estimada por silencio administrativo positivo.', false), ('B', 'La Confederación debe continuar el procedimiento de oficio, porque la firma no es un requisito de la solicitud.', false), ('C', 'La solicitud se archiva sin necesidad de resolución, al no haber llegado a iniciarse el procedimiento.', false), ('D', 'Se le tendrá por desistido de su petición, previa resolución dictada en los términos del artículo 21.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El requerimiento de subsanación dirigido a D. Martín Olmedo (plazo de diez días) se le notifica el miércoles 5 de noviembre de 2025. Si no hubiera ningún día festivo en el periodo, ¿cuál sería el último día para subsanar?', 'El plazo es de diez días hábiles (art. 68.1), excluidos sábados, domingos y festivos (art. 30.2), y se cuenta desde el día siguiente a la notificación (art. 30.3): del jueves 6 al miércoles 19 de noviembre hay diez días hábiles.', 'age_adm_examen_2025_p2', (select id from public.topics where slug = 'age-adm-examen-2025-p2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Arts. 68.1 y 30.2-3 LPAC', 'cuando los plazos se señalen por días, se entiende que éstos son hábiles, excluyéndose del cómputo los sábados, los domingos y los declarados festivos. […] Los plazos expresados en días se contarán a partir del día siguiente a aquel en que tenga lugar la notificación o publicación del acto de que se trate', null, '7fd403acd208170093d5291c21e585fa4a2af8e11d33d79c5c94d293f8a4edd6', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7fd403acd208170093d5291c21e585fa4a2af8e11d33d79c5c94d293f8a4edd6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sábado 15 de noviembre de 2025.', false), ('B', 'Miércoles 19 de noviembre de 2025.', true), ('C', 'Lunes 17 de noviembre de 2025.', false), ('D', 'Viernes 21 de noviembre de 2025.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'La Confederación Hidrográfica del Tajo concedió en septiembre de 2025 la autorización a D. Martín Olmedo. Meses después, un informe técnico revela que la parcela es inundable y la Confederación considera que la autorización es anulable y perjudicial para el interés público. ¿Qué vía debe seguir para dejarla sin efecto?', 'Los actos favorables anulables no se pueden anular directamente: la Administración debe declararlos lesivos y recurrirlos en vía contencioso-administrativa (art. 107.1). La revocación del art. 109 solo sirve para actos de gravamen o desfavorables.', 'age_adm_examen_2025_p2', (select id from public.topics where slug = 'age-adm-examen-2025-p2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 107.1 LPAC', 'Las Administraciones Públicas podrán impugnar ante el orden jurisdiccional contencioso-administrativo los actos favorables para los interesados que sean anulables conforme a lo dispuesto en el artículo 48, previa su declaración de lesividad para el interés público.', null, 'bc1f163e39a19d8b11a92ce9c2db6b080d53271db61ee678d5bb69148920705e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'bc1f163e39a19d8b11a92ce9c2db6b080d53271db61ee678d5bb69148920705e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
