with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Antes de declarar lesiva la autorización de D. Martín Olmedo, la Confederación debe darle audiencia. ¿De qué plazo dispondrá, como mínimo, para presentar alegaciones?', 'La declaración de lesividad exige la audiencia previa de los interesados en los términos del art. 82 (art. 107.2), cuyo plazo no puede ser inferior a diez días ni superior a quince.', 'age_adm_examen_2025_p2', (select id from public.topics where slug = 'age-adm-examen-2025-p2'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Arts. 107.2 y 82.2 LPAC', 'Los interesados, en un plazo no inferior a diez días ni superior a quince, podrán alegar y presentar los documentos y justificaciones que estimen pertinentes.', null, '5f6de47a6bc79ae702dd50b76aa863f9a741adf8c7e9180d2ae5ab4663391bb0', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5f6de47a6bc79ae702dd50b76aa863f9a741adf8c7e9180d2ae5ab4663391bb0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Diez días.', true), ('B', 'Cinco días.', false), ('C', 'Quince días.', false), ('D', 'Un mes.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
