with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'La Confederación inicia el procedimiento para declarar lesiva la autorización de D. Martín Olmedo el 10 de febrero de 2026, pero deja pasar el tiempo sin declararla. Según la Ley 39/2015, ¿qué ocurrirá si transcurren seis meses desde la iniciación sin que se haya declarado la lesividad?', 'El plazo de cuatro años limita cuándo puede adoptarse la declaración (art. 107.2), pero una vez iniciado el procedimiento, si pasan seis meses sin declarar la lesividad, este caduca (art. 107.3).', 'age_adm_examen_2025_p2', (select id from public.topics where slug = 'age-adm-examen-2025-p2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 107.3 LPAC', 'Transcurrido el plazo de seis meses desde la iniciación del procedimiento sin que se hubiera declarado la lesividad, se producirá la caducidad del mismo.', null, '62654386f978ab267555db57365f498c3c469d079963471e1f781d1d178939f2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '62654386f978ab267555db57365f498c3c469d079963471e1f781d1d178939f2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se entenderá declarada la lesividad por silencio.', false), ('B', 'El procedimiento caducará.', true), ('C', 'La autorización quedará anulada de forma automática.', false), ('D', 'La Confederación podrá declarar la lesividad en cualquier momento, porque el único límite es de cuatro años.', false)) as v(label, body, ok)
)
