with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Dña. Sara Linares supera la promoción interna al Cuerpo de Gestión de la Administración Civil del Estado y toma posesión en él. ¿En qué situación queda en su cuerpo de origen (subgrupo C1)?', 'Quien está en servicio activo en otro cuerpo o escala de cualquier Administración pasa, en el de origen, a excedencia voluntaria por prestación de servicios en el sector público, salvo que haya obtenido la compatibilidad (art. 15.1).', 'age_adm_examen_2025_p2', (select id from public.topics where slug = 'age-adm-examen-2025-p2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730'), 'Art. 15.1 RD 365/1995', 'Procederá declarar, de oficio o a instancia de parte, en la situación regulada en este artículo a los funcionarios de carrera que se encuentren en servicio activo en otro cuerpo o escala de cualquiera de las Administraciones públicas, salvo que hubieran obtenido la oportuna compatibilidad', null, '8675ba4872662c1864bd3aedbf40a16570566755926535535b76f949862a7b41', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8675ba4872662c1864bd3aedbf40a16570566755926535535b76f949862a7b41')
  returning id
