)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El Secretario General de la Confederación Hidrográfica del Tajo, funcionario de carrera, obtiene por libre designación un puesto de Subdirector General en otro ministerio, incluido en la relación de puestos de trabajo. ¿En qué situación administrativa queda?', 'Desempeñar un puesto adscrito a funcionarios según la RPT es servicio activo, sea cual sea la forma de provisión (art. 3.a).', 'age_adm_examen_2025_p2', (select id from public.topics where slug = 'age-adm-examen-2025-p2'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8730'), 'Art. 3.a RD 365/1995', 'Cuando desempeñen un puesto que, conforme a la correspondiente relación de puestos de trabajo, esté adscrito a los funcionarios comprendidos en el ámbito de aplicación de la Ley 30/1984, de 2 de agosto, de Medidas para la Reforma de la Función Pública.', null, '667729bfa7182391e50a8d9d6404780ec00e7cd2c3429079512c551bb9a617ee', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '667729bfa7182391e50a8d9d6404780ec00e7cd2c3429079512c551bb9a617ee')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Servicios especiales.', false), ('B', 'Excedencia voluntaria por prestación de servicios en el sector público.', false), ('C', 'Servicio activo.', true), ('D', 'Expectativa de destino.', false)) as v(label, body, ok)
)
