insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 951/2005, de 29 de julio, marco general para la mejora de la calidad en la Administración General del Estado (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2005-14836', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-adm-examen-2025-p2', 'Examen réplica · Convocatoria 2025 (INAP) · Segunda parte: supuesto práctico (20 preguntas)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-examen-2025-p2' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D. Martín Olmedo usa silla de ruedas y no puede acceder a la oficina de registro de la Confederación porque solo hay escaleras. Decide presentar una queja por correo electrónico. Según el Real Decreto 951/2005, ¿qué requisito debe cumplir esa queja?', 'Las quejas y sugerencias pueden formularse presencialmente, por correo postal o por medios telemáticos; las presentadas por correo electrónico o por Internet deben ir firmadas electrónicamente (art. 15.2).', 'age_adm_examen_2025_p2', (select id from public.topics where slug = 'age-adm-examen-2025-p2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2005-14836'), 'Art. 15.2 RD 951/2005', 'Las quejas y sugerencias presentadas por correo electrónico o a través de Internet deberán estar suscritas con la firma electrónica del interesado.', null, 'f60902048ff3ba8e5c4404ddd67dc49337c2d5df61a283ab28d8a1d6f1c165c4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f60902048ff3ba8e5c4404ddd67dc49337c2d5df61a283ab28d8a1d6f1c165c4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Debe presentarse en el formulario en papel diseñado por el organismo.', false), ('B', 'Debe ir acompañada de copia compulsada del documento de identidad.', false), ('C', 'Debe estar suscrita con la firma electrónica del interesado.', true), ('D', 'No necesita ningún requisito adicional, porque basta con indicar nombre y apellidos.', false)) as v(label, body, ok)
)
