insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 364/1995, de 10 de marzo, Reglamento General de Ingreso del Personal al servicio de la AGE y de Provisión de Puestos de Trabajo y Promoción Profesional (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
