insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-examen-2025-p2' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Dña. Sara Linares (C1) ocupa con carácter definitivo desde el 1 de febrero de 2021 un puesto de nivel 15 en la Confederación, con el que ya consolidó su grado inicial. Desde el 1 de junio de 2023 desempeña en comisión de servicios un puesto de nivel 18, que no ha obtenido con carácter definitivo. ¿Qué grado tiene consolidado en noviembre de 2025?', 'El grado se consolida con dos años continuados en puestos de un nivel (art. 70.2): el 15 quedó consolidado en febrero de 2023. El tiempo en comisión solo computa para el nivel 18 si obtiene ese puesto u otro igual o superior con carácter definitivo (art. 70.6).', 'age_adm_examen_2025_p2', (select id from public.topics where slug = 'age-adm-examen-2025-p2'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Art. 70.2 y 70.6 RD 364/1995', 'el tiempo prestado en comisión de servicios será computable para consolidar el grado correspondiente al puesto desempeñado siempre que se obtenga con carácter definitivo dicho puesto u otro de igual o superior nivel.', null, '6d3e4fabd2b3e9b06911a194cc14e02782ed23624ea86807cb55a152e3d93751', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6d3e4fabd2b3e9b06911a194cc14e02782ed23624ea86807cb55a152e3d93751')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El 15.', true), ('B', 'El 16.', false), ('C', 'El 17.', false), ('D', 'El 18.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Dña. Sara Linares, funcionaria de carrera en servicio activo, accede por promoción interna al Cuerpo de Gestión y su nuevo destino está en la misma localidad. Según el Reglamento General de Ingreso, ¿qué permiso retribuido le corresponde a partir de la toma de posesión?', 'Quien accede a un nuevo Cuerpo o Escala tiene un permiso retribuido de tres días hábiles si no cambia de residencia y de un mes si la cambia (DA 5.ª).', 'age_adm_examen_2025_p2', (select id from public.topics where slug = 'age-adm-examen-2025-p2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'DA 5.ª RD 364/1995', 'Los funcionarios de carrera en servicio activo o situación asimilada que accedan a un nuevo Cuerpo o Escala tendrán derecho, a partir de la toma de posesión, a un permiso retribuido de tres días hábiles si el destino no implica cambio de residencia del funcionario y de un mes si lo comporta.', 'El original preguntaba por el plazo de toma de posesión del nuevo funcionario, que fija cada convocatoria y no el texto del RD 364/1995 capturado; la réplica se centra en el mismo momento (acceso al nuevo cuerpo) con el dato que sí da el Reglamento.', 'c3955984b4b4202861fad7732563f1001debed547f2b6d37a376fad55d954522', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c3955984b4b4202861fad7732563f1001debed547f2b6d37a376fad55d954522')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un mes.', false), ('B', 'Tres días hábiles.', true), ('C', 'Quince días naturales.', false), ('D', 'Ninguno, porque no cambia de residencia.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('administrativo-estado');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El Secretario General de la Confederación cesa en Toledo el martes 4 de noviembre de 2025 para tomar posesión de su nuevo puesto de libre designación en Madrid, lo que supone cambio de residencia. Sin prórrogas ni permisos, ¿hasta qué día puede tomar posesión?', 'Con cambio de residencia el plazo es de un mes, contado desde el día siguiente al cese (art. 48.1, aplicable a la libre designación por el art. 57); el mes vence el mismo día del mes siguiente: 4 de diciembre (art. 30.4 LPAC).', 'age_adm_examen_2025_p2', (select id from public.topics where slug = 'age-adm-examen-2025-p2'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-8729'), 'Art. 48.1 RD 364/1995', 'El plazo para tomar posesión será de tres días hábiles si no implica cambio de residencia del funcionario, o de un mes si comporta cambio de residencia o el reingreso al servicio activo. […] El plazo de toma de posesión empezará a contarse a partir del día siguiente al del cese', null, '30e86f073b05ffe40c05a0a00281dbb0d130e2a93255c8a0d3e9555760bef288', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '30e86f073b05ffe40c05a0a00281dbb0d130e2a93255c8a0d3e9555760bef288')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Hasta el viernes 7 de noviembre de 2025.', false), ('B', 'Hasta el jueves 4 de diciembre de 2025.', true), ('C', 'Hasta el miércoles 3 de diciembre de 2025.', false), ('D', 'Hasta el jueves 18 de diciembre de 2025.', false)) as v(label, body, ok)
)
