insert into public.topics (slug, title) values ('age-adm-examen-2025-p2', 'Examen réplica · Convocatoria 2025 (INAP) · Segunda parte: supuesto práctico (20 preguntas)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('administrativo-estado') and t.slug = 'age-adm-examen-2025-p2' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Dña. Sara Linares va a adoptar a un menor y quiere disfrutar de forma interrumpida las semanas no obligatorias de su permiso. Según el TREBEP, ¿qué preaviso debe dar para cada periodo de disfrute?', 'Para el disfrute interrumpido del permiso se exige, en cada periodo, un preaviso de al menos quince días, y se disfruta por semanas completas (art. 49.b; la misma regla se repite en el permiso por nacimiento del art. 49.c).', 'age_adm_examen_2025_p2', (select id from public.topics where slug = 'age-adm-examen-2025-p2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 49.b TREBEP', 'En el caso del disfrute interrumpido del permiso se requerirá, para cada período de disfrute, un preaviso de al menos quince días y se realizará por semanas completas.', null, '4edac37b3b0c15d5e598599b6b6b7080aa3014164c33089c5f25c2a6bc42c9db', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4edac37b3b0c15d5e598599b6b6b7080aa3014164c33089c5f25c2a6bc42c9db')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al menos quince días, y por semanas completas.', true), ('B', 'Al menos diez días hábiles, y por días sueltos.', false), ('C', 'Al menos un mes, y por quincenas.', false), ('D', 'No necesita preaviso si lo comunica por registro electrónico.', false)) as v(label, body, ok)
)
