with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Dña. Sara Linares, adoptante en una familia con dos progenitores, quiere disfrutar a tiempo parcial todo lo que la ley le permita de su permiso por adopción. ¿Cuántas semanas podría disfrutar en ese régimen, si lo permiten las necesidades del servicio?', 'De las diecinueve semanas, las seis primeras son obligatorias y a jornada completa; pueden disfrutarse a tiempo parcial las once del apartado 2.º y las dos del apartado 3.º: trece en total (art. 49.b).', 'age_adm_examen_2025_p2', (select id from public.topics where slug = 'age-adm-examen-2025-p2'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 49.b TREBEP', 'Seis semanas ininterrumpidas inmediatamente posteriores a la resolución judicial por la que se constituye la adopción o bien de la decisión administrativa de guarda con fines de adopción o de acogimiento, serán obligatorias y habrán de disfrutarse a jornada completa. […] El permiso previsto en los apartados 2.º y 3.º podrá disfrutarse a jornada completa o a tiempo parcial', 'El original preguntaba lo mismo para el permiso por nacimiento del progenitor distinto de la madre biológica (art. 49.c), cuyo reparto es idéntico; aquí se aplica al permiso por adopción para no repetir el supuesto.', 'eff00d702e84d394775383d7ce47f4dfa4656f3e689d090ad46af8d255a3dc85', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'eff00d702e84d394775383d7ce47f4dfa4656f3e689d090ad46af8d255a3dc85')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Diecinueve semanas.', false), ('B', 'Seis semanas.', false), ('C', 'Once semanas.', false), ('D', 'Trece semanas.', true)) as v(label, body, ok)
)
