  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Qué mayoría exige el artículo 167.1 de la Constitución para aprobar un proyecto de reforma constitucional?', 'El procedimiento ordinario de reforma (art. 167.1 CE) exige tres quintos en cada Cámara; si no hay acuerdo, se forma una comisión paritaria y, en su defecto, basta mayoría absoluta del Senado y dos tercios del Congreso (art. 167.2).', 'age_aux_examen_2024_b1', (select id from public.topics where slug = 'age-aux-examen-2024-b1'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 167.1 CE', 'Los proyectos de reforma constitucional deberán ser aprobados por una mayoría de tres quintos de cada una de las Cámaras.', null, '1cf5e84d8c5c74e7b9a2ae4297d4da4061a25aae12bf65cfc2132727e1fc1d67', false
