  select 'Según el artículo 21 de la Ley 50/1997, ¿cuál de estas facultades NO puede ejercer el Presidente del Gobierno en funciones?', 'El Presidente en funciones no puede proponer la disolución de las Cámaras, plantear la cuestión de confianza ni proponer un referéndum consultivo (art. 21.4). El Gobierno en funciones tampoco puede aprobar el proyecto de Presupuestos ni presentar proyectos de ley (art. 21.5).', 'age_aux_examen_2024_b1', (select id from public.topics where slug = 'age-aux-examen-2024-b1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1997-25336'), 'Art. 21.4 Ley 50/1997', 'El Presidente del Gobierno en funciones no podrá ejercer las siguientes facultades: […] b) Plantear la cuestión de confianza.', null, 'a0f9e839ae330e793908d1930450ae8475557be66f0b3d61106edf579df66ae8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a0f9e839ae330e793908d1930450ae8475557be66f0b3d61106edf579df66ae8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Representar al Gobierno.', false), ('B', 'Dirigir la acción del Gobierno en el despacho ordinario de asuntos.', false), ('C', 'Convocar y presidir las reuniones del Consejo de Ministros.', false), ('D', 'Plantear la cuestión de confianza.', true)) as v(label, body, ok)
)
