  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 5 de la Ley 40/2015, tienen la consideración de órganos administrativos:', 'El art. 5.1 define el órgano administrativo por sus funciones: efectos jurídicos frente a terceros o actuación preceptiva. Su creación exige determinar su integración y dependencia, delimitar funciones y dotar créditos (art. 5.3).', 'age_aux_examen_2024_b1', (select id from public.topics where slug = 'age-aux-examen-2024-b1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'Art. 5.1 Ley 40/2015', 'Tendrán la consideración de órganos administrativos las unidades administrativas a las que se les atribuyan funciones que tengan efectos jurídicos frente a terceros, o cuya actuación tenga carácter preceptivo.', null, 'c3523e0740b881ad7fd1fd30b72b5f0914d3905a0bc1d34feb0c2945fa698d07', false
