with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la disposición transitoria sexta del Real Decreto-ley 6/2023, ¿cuál es el intervalo de niveles de los puestos del subgrupo C2?', 'Hasta que se apruebe la norma reglamentaria, los intervalos son: A1 24-30, A2 20-26, B 18-24, C1 16-22 y C2 14-18. El examen citaba la Resolución de la SEFP de 7 de mayo de 2024 para la adecuación de puestos a esta disposición; esa resolución no se publicó en el BOE y la réplica cita la norma que fija los intervalos.', 'age_aux_examen_2024_b1', (select id from public.topics where slug = 'age-aux-examen-2024-b1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2023-25758'), 'RDL 6/2023, disp. trans. 6.ª', 'Grupo C2. | 14 | 18', null, 'e815eb3a23b266c74b0940d3f1d22bdea82309eb919e703da334438716895e73', false
