with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Resolución de 7 de mayo de 2014 sobre listas de candidatos a personal funcionario interino gestionadas por las Delegaciones y Subdelegaciones del Gobierno, ¿en qué plazo debe presentarse el candidato nombrado para tomar posesión?', 'El apartado cuarto fija tres días naturales desde el nombramiento; si no se presenta, se entiende que renuncia al nombramiento y a permanecer en las listas. También son tres días naturales para aportar la documentación tras la oferta (apartado tercero).', 'age_aux_examen_2024_b1', (select id from public.topics where slug = 'age-aux-examen-2024-b1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-5443'), 'Resolución de 7/5/2014 (SEAP), apartado cuarto', 'En el plazo máximo de tres días naturales desde el nombramiento, el candidato deberá presentarse para tomar posesión de su puesto de trabajo.', null, 'de9e2a437a6735b1411a29901f97ef3bedde4bb2b9cd6fade6db1f5d21ca64ca', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'de9e2a437a6735b1411a29901f97ef3bedde4bb2b9cd6fade6db1f5d21ca64ca')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En el plazo de un mes desde la publicación del nombramiento.', false), ('B', 'En el plazo de diez días hábiles desde la notificación.', false), ('C', 'En el plazo de cinco días hábiles desde el nombramiento.', false), ('D', 'En el plazo máximo de tres días naturales desde el nombramiento.', true)) as v(label, body, ok)
)
