  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 29 del TREBEP, las cantidades destinadas a financiar aportaciones a planes de pensiones o contratos de seguros tienen a todos los efectos la consideración de:', 'El art. 29 las califica como retribución diferida, con el límite de masa salarial que fijen las Leyes de Presupuestos.', 'age_aux_examen_2024_b1', (select id from public.topics where slug = 'age-aux-examen-2024-b1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 29 TREBEP', 'Las cantidades destinadas a financiar aportaciones a planes de pensiones o contratos de seguros tendrán a todos los efectos la consideración de retribución diferida.', null, '3753f8c75c52d7e840c127cb534968d17c008a681dacea98e82e4fbed3df3175', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3753f8c75c52d7e840c127cb534968d17c008a681dacea98e82e4fbed3df3175')
  returning id
