with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Acuerdo de 21 de marzo de 2019 sobre la gobernanza de la Agenda 2030 (Orden PCI/383/2019), el Grupo de Trabajo Interministerial para la Agenda 2030, foro técnico de coordinación entre ministerios, está presidido por:', 'La Orden PCI/383/2019 crea el Grupo de Trabajo Interministerial, de carácter técnico, presidido por la Alta Comisionada para la Agenda 2030. El examen real preguntó por el órgano que estudia las actuaciones de la AGE para cumplir los ODS; esta réplica pregunta por la gobernanza de la Agenda 2030 tal como la recoge la norma publicada en el BOE que tenemos.', 'age_aux_examen_2026_b1', (select id from public.topics where slug = 'age-aux-examen-2026-b1'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2019-4905'), 'Orden PCI/383/2019, acuerdo tres', 'un Grupo de Trabajo Interministerial, de carácter técnico, que estará presidido por la Alta Comisionada para la Agenda 2030', 'La estructura de gobernanza de la Agenda 2030 ha cambiado varias veces desde 2019 (Comisión Delegada para la Agenda 2030, cambios de ministerio); la Orden PCI/383/2019 sigue en el BOE como vigente, pero conviene confirmar que el Grupo de Trabajo Interministerial sigue presidido así.', '6e20a2ad2d7d7a398f7320f16c477d4d67d17c3a1f866297e06e292696cff458', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6e20a2ad2d7d7a398f7320f16c477d4d67d17c3a1f866297e06e292696cff458')
