  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 11.2 de la Ley 39/2015, las Administraciones Públicas solo exigirán el uso obligatorio de firma a los interesados para, entre otras actuaciones:', 'El art. 11.2 limita la firma obligatoria a formular solicitudes, presentar declaraciones responsables o comunicaciones, interponer recursos, desistir de acciones y renunciar a derechos. Para lo demás basta acreditar la identidad (art. 11.1).', 'age_aux_examen_2026_b1', (select id from public.topics where slug = 'age-aux-examen-2026-b1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 11.2 Ley 39/2015', 'Las Administraciones Públicas sólo requerirán a los interesados el uso obligatorio de firma para: […] e) Renunciar a derechos.', null, '916b87503d745fbb8e58104f2b8be09e9d6618601b90256619c7f2422c0326f3', false
