  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 20.5 de la Ley 19/2013, las resoluciones dictadas en materia de acceso a la información pública:', 'El art. 20.5 permite ir directamente a la vía contencioso-administrativa; la reclamación ante el CTBG del art. 24 es potestativa y sustituye a los recursos administrativos (art. 23).', 'age_aux_examen_2026_b1', (select id from public.topics where slug = 'age-aux-examen-2026-b1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2013-12887'), 'Art. 20.5 Ley 19/2013', 'Las resoluciones dictadas en materia de acceso a la información pública son recurribles directamente ante la Jurisdicción Contencioso-administrativa, sin perjuicio de la posibilidad de interposición de la reclamación potestativa prevista en el artículo 24.', null, '172b5b913854ab8674fba88fadfcc1de0163e3bf3f397aff2d1ffba94e89749b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '172b5b913854ab8674fba88fadfcc1de0163e3bf3f397aff2d1ffba94e89749b')
