with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Cuál de los siguientes figura entre los principios éticos del artículo 53 del TREBEP, y no entre los principios de conducta del artículo 54?', 'No aceptar trato de favor o privilegios es principio ético (art. 53.7). Rechazar regalos más allá de los usos habituales, la formación y la conservación de documentos son principios de conducta (art. 54).', 'age_aux_examen_2026_b1', (select id from public.topics where slug = 'age-aux-examen-2026-b1'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 53.7 TREBEP', 'No aceptarán ningún trato de favor o situación que implique privilegio o ventaja injustificada, por parte de personas físicas o entidades privadas.', null, '205a7d5601bba2f250648656057ff2a9c20e431d6668a100f3d5926a1f3150a8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '205a7d5601bba2f250648656057ff2a9c20e431d6668a100f3d5926a1f3150a8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No aceptar ningún trato de favor o situación que implique privilegio o ventaja injustificada por parte de personas físicas o entidades privadas.', true), ('B', 'Mantener actualizada su formación y cualificación.', false), ('C', 'Garantizar la constancia y permanencia de los documentos para su transmisión.', false), ('D', 'Rechazar cualquier regalo, favor o servicio en condiciones ventajosas que vaya más allá de los usos habituales.', false)) as v(label, body, ok)
)
