with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 97 del TREBEP, ¿en qué plazos prescriben las infracciones disciplinarias?', 'Las infracciones prescriben a los 3 años (muy graves), 2 años (graves) y 6 meses (leves). Las sanciones prescriben a los 3 años, 2 años y 1 año, respectivamente.', 'age_aux_examen_2026_b1', (select id from public.topics where slug = 'age-aux-examen-2026-b1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 97 TREBEP', 'Las infracciones muy graves prescribirán a los tres años, las graves a los dos años y las leves a los seis meses', null, '63a5cc3fc4a5f63b16b052073abfb20bda3c1a2881e2cb117dc74a081da50ad1', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '63a5cc3fc4a5f63b16b052073abfb20bda3c1a2881e2cb117dc74a081da50ad1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Muy graves a los seis años, graves a los tres años y leves al año.', false), ('B', 'Muy graves a los tres años, graves al año y leves a los tres meses.', false), ('C', 'Muy graves a los tres años, graves a los dos años y leves a los seis meses.', true), ('D', 'Muy graves a los cuatro años, graves a los dos años y leves al mes.', false)) as v(label, body, ok)
)
