with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Cuál de las siguientes NO figura entre las sanciones disciplinarias del artículo 96.1 del TREBEP?', 'El art. 96.1 enumera separación del servicio, despido disciplinario, suspensión firme de funciones (máx. 6 años), traslado forzoso, demérito, apercibimiento y cualquier otra que establezca una ley. La pérdida de trienios no figura.', 'age_aux_examen_2026_b1', (select id from public.topics where slug = 'age-aux-examen-2026-b1'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 96.1 TREBEP', 'd) Traslado forzoso, con o sin cambio de localidad de residencia, por el período que en cada caso se establezca. […] e) Demérito, que consistirá en la penalización a efectos de carrera, promoción o movilidad voluntaria. […] Apercibimiento.', null, '3ef77b0ef47a2f55260917eabd2d94292107a0f62f723cc0e9a3593111306aaa', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3ef77b0ef47a2f55260917eabd2d94292107a0f62f723cc0e9a3593111306aaa')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Demérito.', false), ('B', 'Apercibimiento.', false), ('C', 'Traslado forzoso, con o sin cambio de localidad de residencia.', false), ('D', 'Pérdida de los trienios consolidados.', true)) as v(label, body, ok)
)
