  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El artículo 49.2 de la Constitución, en su redacción vigente, ordena atender particularmente las necesidades específicas de:', 'El art. 49.2 CE, reformado en 2024, termina con el mandato de atender particularmente las necesidades específicas de las mujeres y los menores con discapacidad.', 'age_aux_examen_2026_b2', (select id from public.topics where slug = 'age-aux-examen-2026-b2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 49.2 CE', 'Se atenderán particularmente las necesidades específicas de las mujeres y los menores con discapacidad.', null, '91d55b948b3e12803f7f4ab827413e8e880d8a6ce4513b52bda72c0362875efe', false
