with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el glosario de ciberseguridad de INCIBE, ¿qué término figura como sinónimo de «adware», el software que se apoya en anuncios como parte del propio programa?', 'INCIBE define el adware como software que se apoya en anuncios, normalmente para financiarse, y recoge «malvertising» como sinónimo. El keylogger registra las pulsaciones del teclado y la botnet es una red de equipos controlados remotamente.', 'age_aux_examen_2026_b2', (select id from public.topics where slug = 'age-aux-examen-2026-b2'), 2, 'es', true, (select id from public.sources where url = 'https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf'), 'INCIBE · Adware (sinónimo: Malvertising)', 'Software que se apoya en anuncios (normalmente para financiarse) como parte del propio programa. […] Sinónimo: Malvertising', null, 'eaef42ad9edb10c7c0649d5b37a444b624e03c4225d607a9958c9a80acb5e495', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'eaef42ad9edb10c7c0649d5b37a444b624e03c4225d607a9958c9a80acb5e495')
  returning id
