with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un Sistema de Gestión de la Seguridad de la Información (SGSI) es, según INCIBE, un conjunto de políticas de seguridad de la información que siguen la norma:', 'INCIBE define el SGSI como un conjunto de políticas de seguridad de la información que siguen la norma ISO/IEC 27001 (familia ISO 27000). ISO 9001 es de gestión de la calidad e ISO 14001, ambiental.', 'age_aux_examen_2026_b2', (select id from public.topics where slug = 'age-aux-examen-2026-b2'), 2, 'es', true, (select id from public.sources where url = 'https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf'), 'INCIBE · SGSI (ISO/IEC 27001)', 'Un Sistema de Gestión de la seguridad de la Información (SGSI) es un conjunto de políticas de seguridad de la información que siguen la norma ISO/IEC 27001.', null, 'f6f825a908dc065d8a88e9302f03dd73253b724fd24a57de3d0ac28e6b91f134', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f6f825a908dc065d8a88e9302f03dd73253b724fd24a57de3d0ac28e6b91f134')
  returning id
), o as (
