  select q.id, v.label, v.body, v.ok from q, (values ('A', 'ISO/IEC 27001.', true), ('B', 'ISO 9001.', false), ('C', 'ISO 14001.', false), ('D', 'ISO/IEC 20000.', false)) as v(label, body, ok)
)
