with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En ciberseguridad, ¿qué es un «insider» según el glosario de INCIBE?', 'Para INCIBE, insider es una persona perteneciente a la organización que divulga información sensible de forma intencionada. La vulnerabilidad desconocida por el fabricante es un día cero; el programa espía es spyware. (La pregunta oficial equivalente fue anulada.)', 'age_aux_examen_2026_b2', (select id from public.topics where slug = 'age-aux-examen-2026-b2'), 2, 'es', true, (select id from public.sources where url = 'https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf'), 'INCIBE · Insider (pregunta oficial anulada)', 'Persona perteneciente a una organización o empresa que divulga información sensible sobre dicha empresa de forma intencionada.', null, '2a878819646f86620636f2ab59b2d5a93b7147e1359affd71ccc1f12ac1da22b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2a878819646f86620636f2ab59b2d5a93b7147e1359affd71ccc1f12ac1da22b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un programa que se instala sin permiso y espía la actividad del usuario.', false), ('B', 'Un atacante externo que suplanta la identidad de un empleado por correo electrónico.', false), ('C', 'Una vulnerabilidad desconocida por el fabricante del software.', false), ('D', 'Una persona de la propia organización que divulga intencionadamente información sensible de ella.', true)) as v(label, body, ok)
)
