with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Qué es una VPN (red privada virtual)?', 'INCIBE define la VPN como tecnología de red que permite una extensión segura de una LAN sobre una red pública o no controlada como Internet. Traducir nombres en IP es función del DNS.', 'age_aux_examen_2026_b2', (select id from public.topics where slug = 'age-aux-examen-2026-b2'), 1, 'es', true, (select id from public.sources where url = 'https://www.incibe.es/sites/default/files/contenidos/guias/doc/guia_glosario_ciberseguridad_2021.pdf'), 'INCIBE · VPN', 'Una red privada virtual, también conocida por sus siglas VPN (Virtual Private Network) es una tecnología de red que permite una extensión segura de una red local (LAN) sobre una red pública o no controlada como Internet.', null, 'c2b504ac8b4071612412027ae394aeb7837b58fa81b07476fbda55592f06b262', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c2b504ac8b4071612412027ae394aeb7837b58fa81b07476fbda55592f06b262')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un programa antivirus de uso empresarial.', false), ('B', 'Un servidor que traduce nombres de dominio en direcciones IP.', false), ('C', 'Una tecnología que extiende de forma segura una red local sobre una red pública como Internet.', true), ('D', 'Un tipo de cable para conectar redes locales.', false)) as v(label, body, ok)
)
