  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El texto refundido de la Ley General de derechos de las personas con discapacidad define la inclusión como un proceso o estado irrenunciable que asegura, desde la valoración positiva de la diversidad humana:', 'Redacción vigente del art. 2.j) del RDL 1/2013: la antigua definición de «inclusión social» se sustituyó por la de «inclusión», que además se declara incompatible con cualquier forma de segregación, discriminación o exclusión.', 'age_aux_examen_2026_b2', (select id from public.topics where slug = 'age-aux-examen-2026-b2'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2013-12632'), 'Art. 2.j RDL 1/2013', 'Inclusión: proceso o estado irrenunciable que asegura, desde la valoración positiva de la diversidad humana, la presencia, participación y progreso plenos de todas las personas en las diferentes esferas de la vida', null, '9cd8e63bc05e6a66763db7e14167541dbdba6dabd8ab5ee0d0c1a594cd093bb9', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9cd8e63bc05e6a66763db7e14167541dbdba6dabd8ab5ee0d0c1a594cd093bb9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La igualdad de oportunidades en el acceso al empleo público y privado.', false), ('B', 'La presencia, participación y progreso plenos de todas las personas en las diferentes esferas de la vida.', true), ('C', 'La supresión de toda barrera física en los entornos urbanos.', false), ('D', 'El reconocimiento de prestaciones económicas a las personas con discapacidad.', false)) as v(label, body, ok)
)
