with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 16 de la Ley 39/2015, los registros electrónicos de todas las Administraciones deben ser plenamente interoperables para garantizar:', 'La Ley 39/2015 exige la plena interoperabilidad de los registros electrónicos para garantizar compatibilidad informática, interconexión y transmisión telemática de los asientos registrales y de los documentos presentados.', 'age_aux_examen_2026_b2', (select id from public.topics where slug = 'age-aux-examen-2026-b2'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 16.4 Ley 39/2015', 'Los registros electrónicos de todas y cada una de las Administraciones, deberán ser plenamente interoperables, de modo que se garantice su compatibilidad informática e interconexión, así como la transmisión telemática de los asientos registrales y de los documentos que se presenten en cualquiera de los registros.', null, '45ec708e35afa1b434c54ce9419434ae296e151233c97c60729d7dc646c166ce', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '45ec708e35afa1b434c54ce9419434ae296e151233c97c60729d7dc646c166ce')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Su compatibilidad informática e interconexión, así como la transmisión telemática de asientos y documentos.', true), ('B', 'Únicamente la conservación de los documentos durante el plazo legal.', false), ('C', 'La publicación de los asientos registrales en la sede electrónica.', false), ('D', 'La gratuidad de la presentación de documentos por los interesados.', false)) as v(label, body, ok)
)
