with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Qué oración está correctamente escrita?', 'Sino (conjunción adversativa) introduce lo que sustituye a lo negado: «no lo compró, sino que lo alquiló»; «no quiero café, sino té». Si no es la conjunción condicional si más el adverbio no: «si no lo haces tú»; «si no, me marcho».', 'age_aux_psicotecnicos_verbales', (select id from public.topics where slug = 'age-aux-psicotecnicos-verbales'), 2, 'es', true, (select id from public.sources where url = 'https://www.rae.es/dpd/'), 'DPD, s. v. sino, 3', 'No debe confundirse la conjunción adversativa sino antes descrita con si no, secuencia formada por la conjunción si (→ si) seguida del adverbio de negación no', null, '87be4653ef412b699481bcdc560869b15cd89ff5ec00948a677dbcb7a879758c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '87be4653ef412b699481bcdc560869b15cd89ff5ec00948a677dbcb7a879758c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '¿Quién lo hará, si no lo haces tú?', true), ('B', 'No lo compró, si no que lo alquiló.', false), ('C', 'Te espero a las ocho; sino, me marcho.', false), ('D', 'No quiero café, si no té.', false)) as v(label, body, ok)
)
