with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Orden TDF/379/2024, ¿en qué plazo deben presentarse las solicitudes en los procedimientos de provisión de puestos de personal directivo público profesional?', 'Las convocatorias se publican en el BOE y las solicitudes se dirigen al órgano convocante en los diez días naturales siguientes, con currículum normalizado, justificación de idoneidad, proyecto directivo si se exige y cuestionario de autoevaluación.', 'age_aux_b1_13_funcion_publica', (select id from public.topics where slug = 'age-aux-b1-13-funcion-publica'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2024-8609'), 'Art. 4.2 Orden TDF/379/2024', 'Las solicitudes se dirigirán dentro de los diez días naturales siguientes al de la publicación de la convocatoria al órgano convocante', null, '198a5ce7d814f03a51e49b3e5e2429e16514c374e9abd1166eb2c58e5e7f0549', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '198a5ce7d814f03a51e49b3e5e2429e16514c374e9abd1166eb2c58e5e7f0549')
  returning id
), o as (
