  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Diez días naturales siguientes al de la publicación de la convocatoria.', true), ('B', 'Quince días hábiles desde la publicación de la convocatoria.', false), ('C', 'Un mes desde la publicación de la convocatoria.', false), ('D', 'Veinte días naturales siguientes al de la publicación de la convocatoria.', false)) as v(label, body, ok)
)
