  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En la provisión de un puesto de personal directivo público profesional conforme a la Orden TDF/379/2024, el órgano competente para el nombramiento actúa asesorado por:', 'El art. 4.3 exige el asesoramiento de al menos dos personas expertas en las materias del puesto o en selección de directivos, presentes en las entrevistas y que emiten informe de valoración.', 'age_aux_b1_13_funcion_publica', (select id from public.topics where slug = 'age-aux-b1-13-funcion-publica'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2024-8609'), 'Art. 4.3 Orden TDF/379/2024', 'El órgano competente para el nombramiento actuará asesorado, al menos, por dos personas expertas en las materias específicas del puesto o en procesos de selección de directivos públicos, que deberán estar presentes en las entrevistas y emitir informe de valoración.', null, '2d2974969632b6d8fe353f61c1a4c5fe5cf98586717b28861b57dff3d6aea426', false
