with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 108 del Real Decreto-ley 6/2023, en la oferta de empleo público de la Administración del Estado se reservará para personas con discapacidad un porcentaje no inferior al:', 'El art. 108.4 del RDL 6/2023 eleva en el ámbito estatal la reserva a un mínimo del 10 % (frente al 7 % del art. 59 TREBEP), de modo que al menos el 2 % de las plazas ofertadas sea para personas con discapacidad intelectual.', 'age_aux_b1_13_funcion_publica', (select id from public.topics where slug = 'age-aux-b1-13-funcion-publica'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2023-25758'), 'Art. 108.4 RDL 6/2023', 'En la oferta de empleo público se reservará un porcentaje no inferior al diez por ciento de las plazas convocadas para ser cubiertas entre personas con discapacidad […] al menos el dos por ciento de las plazas ofertadas lo sea para ser cubiertas por personas que acrediten discapacidad intelectual', null, 'd50fc8df863bc8f29b76c079384e060845fd92ccda2eb41603369b5808ec9e95', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd50fc8df863bc8f29b76c079384e060845fd92ccda2eb41603369b5808ec9e95')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Siete por ciento de las plazas convocadas, con al menos un dos por ciento para personas con discapacidad intelectual.', false), ('B', 'Cinco por ciento de las plazas convocadas, sin distinguir tipos de discapacidad.', false), ('C', 'Diez por ciento de las plazas convocadas, con al menos un cinco por ciento para discapacidad intelectual.', false), ('D', 'Diez por ciento de las plazas convocadas, con al menos un dos por ciento para personas con discapacidad intelectual.', true)) as v(label, body, ok)
)
