insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 462/2002, de 24 de mayo, sobre indemnizaciones por razón del servicio (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2002-10337', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('age-aux-b1-14-derechos-deberes-funcionarios', 'I.14 Derechos y deberes de los funcionarios, retribuciones y régimen disciplinario') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxiliar-administrativo-estado') and t.slug = 'age-aux-b1-14-derechos-deberes-funcionarios' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Cuál de los siguientes supuestos NO figura entre los que, según el artículo 1 del Real Decreto 462/2002, dan origen a indemnización o compensación?', 'El art. 1.1 del RD 462/2002 enumera las comisiones de servicio con derecho a indemnización, los desplazamientos dentro del término municipal por razón del servicio, los traslados de residencia y las asistencias. Los servicios extraordinarios no son una indemnización por razón del servicio.', 'age_aux_b1_14_derechos_deberes_funcionarios', (select id from public.topics where slug = 'age-aux-b1-14-derechos-deberes-funcionarios'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2002-10337'), 'Art. 1.1 RD 462/2002', 'Darán origen a indemnización o compensación los supuestos siguientes, en las circunstancias, condiciones y límites contenidos en el presente Real Decreto: a) Comisiones de servicio con derecho a indemnización. b) Desplazamientos dentro del término municipal por razón de servicio. c) Traslados de residencia. d) Asistencias por concurrencia a Consejos de Administración u Órganos Colegiados, por participación en tribunales de oposiciones y concursos', null, '90b9f362a062e8057d45ee47a7eaefc8a53c85a32dc16345c9a33cbba464af64', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '90b9f362a062e8057d45ee47a7eaefc8a53c85a32dc16345c9a33cbba464af64')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Las comisiones de servicio con derecho a indemnización.', false), ('B', 'La realización de horas extraordinarias en el propio centro de trabajo.', true), ('C', 'Los traslados de residencia.', false), ('D', 'Las asistencias por participación en tribunales de oposiciones y concursos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
