  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 6 del Real Decreto 462/2002, la duración de la residencia eventual no podrá exceder de:', 'El art. 6.2 limita la residencia eventual a un año, prorrogable por el tiempo estrictamente indispensable sin que la prórroga pueda superar otro año.', 'age_aux_b1_14_derechos_deberes_funcionarios', (select id from public.topics where slug = 'age-aux-b1-14-derechos-deberes-funcionarios'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2002-10337'), 'Art. 6.2 RD 462/2002', 'La duración de la residencia eventual no podrá exceder de un año, salvo que se prorrogue por el tiempo estrictamente indispensable por la autoridad que haya designado la comisión según lo previsto en el artículo 4.1 anterior. La duración de la prórroga no podrá en ningún caso exceder de un año.', null, 'a1f3cb301fec704b5e13d03d5c32c82ba42c9ecb15cf6b8f9a8ec39fec09b0c8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a1f3cb301fec704b5e13d03d5c32c82ba42c9ecb15cf6b8f9a8ec39fec09b0c8')
