insert into public.sources (title, url, kind, publisher, published_on) values ('Tratado de la Unión Europea (versión consolidada), arts. 1-6 y 9-11', 'https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12016M/TXT', 'web_oficial'::public.source_kind, 'Unión Europea · EUR-Lex (DOUE C 202 de 7.6.2016)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('jus-05-union-europea', 'Tema 5. La Unión Europea: competencias, instituciones y órganos') on conflict (slug) do nothing;
