with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 5 del TUE, ¿qué principio rige la delimitación de las competencias de la Unión?', 'La delimitación se rige por la atribución; el ejercicio, por la subsidiariedad y la proporcionalidad.', 'jus_05_union_europea', (select id from public.topics where slug = 'jus-05-union-europea'), 1, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12016M/TXT'), 'Art. 5.1 TUE', '1. La delimitación de las competencias de la Unión se rige por el principio de atribución. El ejercicio de las competencias de la Unión se rige por los principios de subsidiariedad y proporcionalidad.', null, 'e57776716d83736d555676debff840308c5dc70eb3a75264bfb9866a508f1f45', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e57776716d83736d555676debff840308c5dc70eb3a75264bfb9866a508f1f45')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El principio de atribución.', true), ('B', 'El principio de subsidiariedad.', false), ('C', 'El principio de proporcionalidad.', false), ('D', 'El principio de cooperación leal.', false)) as v(label, body, ok)
)
