  select 'Según el artículo 10 del TUE, ¿a través de qué institución están directamente representados los ciudadanos en la Unión?', 'Los ciudadanos están representados directamente en el Parlamento Europeo; los Estados, en el Consejo Europeo y en el Consejo.', 'jus_05_union_europea', (select id from public.topics where slug = 'jus-05-union-europea'), 1, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12016M/TXT'), 'Art. 10.2 TUE', '2. Los ciudadanos estarán directamente representados en la Unión a través del Parlamento Europeo.', null, '68cfc5bc70a16814c7ec838aaee20e9a5c4cf1e72532ff09482743628fc74edb', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '68cfc5bc70a16814c7ec838aaee20e9a5c4cf1e72532ff09482743628fc74edb')
