  select 'Las actuaciones por videoconferencia de la LEC deberán realizarse garantizando:', 'El art. 137 bis.6 LEC exige garantizar la accesibilidad universal.', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 137 bis.6 LEC', '6\. Lo dispuesto en este artículo deberá realizarse garantizando la accesibilidad universal.', null, '1846d395da67265033301f1ce900fb220b364df07d51574aa5dea064396ef166', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1846d395da67265033301f1ce900fb220b364df07d51574aa5dea064396ef166')
