insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Las reglas del artículo 137 bis de la LEC sobre videoconferencia, ¿se aplican a las actuaciones que se realizan únicamente ante el LAJ?', 'El art. 137 bis.5 LEC extiende su régimen a las actuaciones que se realizan únicamente ante los LAJ.', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 137 bis.5 LEC', '5\. Lo dispuesto en los apartados anteriores será de aplicación también a aquellas actuaciones que hayan de realizarse únicamente ante los Letrados de la Administración de Justicia.', null, 'a2f20b0034a6a68528774aeed078aea62c8cbf39729b81130cf4edc7e29cc4fd', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a2f20b0034a6a68528774aeed078aea62c8cbf39729b81130cf4edc7e29cc4fd')
  returning id
), o as (
