  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sí, también se aplican a esas actuaciones.', true), ('B', 'No, solo se aplican a las actuaciones ante el juez.', false), ('C', 'Solo si el LAJ lo acuerda por decreto.', false), ('D', 'Solo en los procesos de jurisdicción voluntaria.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Cuando el declarante por videoconferencia es menor de edad, ¿desde dónde puede hacerse la declaración?', 'Aunque el juez puede autorizar intervenciones desde cualquier lugar, la declaración de menores o de personas sobre las que verse un procedimiento de apoyos solo puede hacerse desde una oficina judicial.', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 137 bis.3 LEC', 'En todo caso, cuando el declarante sea menor de edad o persona sobre la que verse un procedimiento de medidas judiciales de apoyo de personas con discapacidad, la declaración por videoconferencia solo se podrá hacer desde una oficina judicial', null, '00a4149fee6e6371b056813b273061510cb25eda3eab07fc04a7342712526f71', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '00a4149fee6e6371b056813b273061510cb25eda3eab07fc04a7342712526f71')
