  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Desde cualquier lugar, si el juez lo estima oportuno.', false), ('B', 'Solo desde una oficina judicial.', true), ('C', 'Desde su domicilio, acompañado de sus progenitores.', false), ('D', 'Desde el centro escolar.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Las víctimas de violencia de género, violencia sexual o trata de seres humanos, ¿desde dónde pueden intervenir por videoconferencia?', 'El art. 137 bis.3 LEC permite su intervención desde los lugares de asistencia o protección, o desde otro lugar autorizado por el juez.', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 137 bis.3 LEC', 'podrán intervenir desde los lugares donde se encuentren recibiendo oficialmente asistencia, atención, asesoramiento y protección, o desde cualquier otro lugar si así lo estima oportuno el juez', null, 'dde15efe2201ce16fd8479c01e801f18526b9dd68c4659e560787a084d8c9380', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'dde15efe2201ce16fd8479c01e801f18526b9dd68c4659e560787a084d8c9380')
  returning id
), o as (
