insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('jus-10-oficina-judicial', 'Tema 10. La modernización de la oficina judicial y las nuevas tecnologías') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial', 'tramitacion-procesal') and t.slug = 'jus-10-oficina-judicial' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 435 de la Ley Orgánica del Poder Judicial, la Oficina judicial es:', 'El art. 435.1 LOPJ define la Oficina judicial como organización instrumental de soporte y apoyo a la actividad jurisdiccional. Las unidades administrativas, en cambio, no están integradas en ella (art. 439).', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 435.1 LOPJ', '1. La Oficina judicial es la organización de carácter instrumental que sirve de soporte y apoyo a la actividad jurisdiccional de jueces y tribunales.', null, '89720988a9de286d4c7af7a84d3c12b8a1c80fa8ee1f9d9c3addd1a6c32d72ef', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '89720988a9de286d4c7af7a84d3c12b8a1c80fa8ee1f9d9c3addd1a6c32d72ef')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El órgano de gobierno de cada Tribunal de Instancia.', false), ('B', 'La organización de carácter instrumental que sirve de soporte y apoyo a la actividad jurisdiccional de jueces y tribunales.', true), ('C', 'La unidad administrativa que gestiona los recursos humanos y materiales de la Administración de Justicia.', false), ('D', 'El conjunto de jueces y magistrados destinados en un mismo partido judicial.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con la Ley Orgánica del Poder Judicial, la estructura básica de la Oficina judicial, homogénea en todo el territorio nacional, estará basada en los principios de:', 'El art. 435.2 LOPJ basa la estructura de la Oficina judicial en jerarquía, división de funciones y coordinación; su funcionamiento se rige por criterios de agilidad, eficacia, eficiencia y racionalización del trabajo, entre otros (art. 435.3).', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 435.2 LOPJ', '2. La estructura básica de la Oficina judicial, que será homogénea en todo el territorio nacional como consecuencia del carácter único del Poder al que sirve, estará basada en los principios de jerarquía, división de funciones y coordinación.', null, '101b031a177bfdfae0f29f5d0f05f2a0dd137e71e3ee5328cb9c70ee26dd6198', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '101b031a177bfdfae0f29f5d0f05f2a0dd137e71e3ee5328cb9c70ee26dd6198')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Unidad de actuación y dependencia jerárquica.', false), ('B', 'Descentralización, desconcentración y eficacia.', false), ('C', 'Independencia, inamovilidad y responsabilidad.', false), ('D', 'Jerarquía, división de funciones y coordinación.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica del Poder Judicial, la dirección de cada servicio común de la Oficina judicial corresponderá a:', 'El art. 436.6 LOPJ atribuye la dirección de cada servicio común a un letrado de la Administración de Justicia, del que dependen funcionalmente los demás letrados y el personal del servicio.', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 436.6 LOPJ', '6. La dirección de cada servicio común corresponderá a un letrado o una letrada de la Administración de Justicia', null, '198daea9b1999512ffab4defd3fef5c311d19d51529e611c3939c50fe51857ae', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '198daea9b1999512ffab4defd3fef5c311d19d51529e611c3939c50fe51857ae')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El juez o magistrado que presida el Tribunal de Instancia.', false), ('B', 'Un funcionario del Cuerpo de Gestión Procesal y Administrativa.', false), ('C', 'Un letrado o una letrada de la Administración de Justicia.', true), ('D', 'El Secretario de Gobierno del Tribunal Superior de Justicia.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley Orgánica del Poder Judicial, se entiende por servicio común de tramitación aquella unidad de la Oficina judicial que:', 'El art. 437.1 LOPJ define el servicio común de tramitación por la ordenación del procedimiento; cada Tribunal de Instancia, Audiencia Provincial, TSJ, la Audiencia Nacional, el Tribunal Supremo y el Tribunal Central de Instancia son asistidos por uno (art. 437.2).', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 437.1 LOPJ', '1. A los efectos de esta ley orgánica se entiende por servicio común de tramitación aquella unidad de la Oficina judicial que realiza todas las funciones requeridas para la ordenación del procedimiento.', null, 'ae90f4cfee5b5997b601da5ac42af02c8787da78aabedd830c3b8d2367d9ae7b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ae90f4cfee5b5997b601da5ac42af02c8787da78aabedd830c3b8d2367d9ae7b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Realiza todas las funciones requeridas para la ordenación del procedimiento.', true), ('B', 'Realiza exclusivamente los actos de comunicación y de auxilio judicial.', false), ('C', 'Presta servicios a la ciudadanía en los municipios donde no hay Tribunal de Instancia.', false), ('D', 'Gestiona los recursos humanos y los medios informáticos sin realizar funciones procesales.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 437 de la Ley Orgánica del Poder Judicial, deberá existir al menos un área en el servicio común de tramitación para la ordenación de los procedimientos de una sección cuando en un Tribunal de Instancia el número de plazas judiciales de esa misma sección sea:', 'El art. 437.3 LOPJ obliga a crear al menos un área cuando una sección tenga doce o más plazas judiciales; el área puede extenderse a otras secciones del mismo orden jurisdiccional.', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 437.3 LOPJ', 'No obstante, cuando en un Tribunal de Instancia el número de plazas judiciales de una misma sección sea igual o superior a doce, deberá existir al menos un área para la ordenación de los procedimientos de que conozcan', null, 'bf0b0a4b41985baf80107b0def0c64f3635c07e54897c5ae946276cf1a55e144', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'bf0b0a4b41985baf80107b0def0c64f3635c07e54897c5ae946276cf1a55e144')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Igual o superior a ocho.', false), ('B', 'Igual o superior a cinco.', false), ('C', 'Igual o superior a veinte.', false), ('D', 'Igual o superior a doce.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 438 de la Ley Orgánica del Poder Judicial, cuando el Ministerio de Justicia o las comunidades autónomas creen servicios comunes procesales que asuman funciones distintas de las de registro y reparto, apoyo, actos de comunicación, auxilio judicial, ejecución y jurisdicción voluntaria, será preciso:', 'El art. 438 LOPJ atribuye al Ministerio de Justicia y a las comunidades autónomas la creación de servicios comunes (registro y reparto, apoyo, actos de comunicación, auxilio judicial, ejecución y jurisdicción voluntaria); si asumen otras funciones, se necesita informe favorable del CGPJ.', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 438 LOPJ', 'Asimismo, podrán crear servicios comunes procesales que asuman otras funciones distintas a las relacionadas en este número, en cuyo caso será preciso el informe favorable del Consejo General del Poder Judicial.', null, 'cfaf5a970044242f9b988719b2d57ec252e6aed65128c698d85e3ee513230e2a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'cfaf5a970044242f9b988719b2d57ec252e6aed65128c698d85e3ee513230e2a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La autorización de la Sala de Gobierno del Tribunal Supremo.', false), ('B', 'El informe favorable del Consejo General del Poder Judicial.', true), ('C', 'El acuerdo de la Junta de Jueces del partido judicial.', false), ('D', 'La aprobación por ley de las Cortes Generales.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica del Poder Judicial, las unidades administrativas que se constituyen en el ámbito de la organización de la Administración de Justicia:', 'El art. 439.1 LOPJ define la unidad administrativa como no integrada en la Oficina judicial y excluye de sus servicios las funciones procesales propias del personal de los Cuerpos de la Administración de Justicia.', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 439.1 LOPJ', '1. A los efectos de esta ley, se entiende por unidad administrativa aquélla que, sin estar integrada en la Oficina judicial, se constituye en el ámbito de la organización de la Administración de Justicia para la prestación de servicios que se consideren necesarios o convenientes para el funcionamiento del servicio público de Justicia. Estos servicios no comprenderán la realización de funciones de carácter procesal que correspondan al personal funcionario de los Cuerpos de la Administración de Justicia.', null, 'ed10d374bd1c908c98801cf89f85192a459cfa1dc75d84bf85cdbb9db69460e2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ed10d374bd1c908c98801cf89f85192a459cfa1dc75d84bf85cdbb9db69460e2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Están integradas en la Oficina judicial y realizan funciones de ordenación del procedimiento.', false), ('B', 'Están integradas en la Oficina judicial bajo la dirección de un juez.', false), ('C', 'No están integradas en la Oficina judicial y sus servicios no comprenden funciones de carácter procesal que correspondan a los Cuerpos de la Administración de Justicia.', true), ('D', 'No están integradas en la Oficina judicial, pero asumen la práctica de los actos de comunicación procesal.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 229 de la Ley Orgánica del Poder Judicial, las declaraciones, interrogatorios, testimonios y vistas podrán realizarse a través de videoconferencia u otro sistema similar que permita:', 'El art. 229.3 LOPJ admite la videoconferencia o sistema similar con comunicación bidireccional y simultánea de imagen y sonido, garantizando la contradicción y el derecho de defensa.', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 229.3 LOPJ', '3. Estas actuaciones podrán realizarse a través de videoconferencia u otro sistema similar que permita la comunicación bidireccional y simultánea de la imagen y el sonido y la interacción visual, auditiva y verbal entre dos personas o grupos de personas geográficamente distantes', null, '01048f0f80232fdb7f71a0643545f0323ed3509bd818ec9d56e5a9285dde7bfb', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '01048f0f80232fdb7f71a0643545f0323ed3509bd818ec9d56e5a9285dde7bfb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La grabación del sonido para su posterior transcripción.', false), ('B', 'El envío diferido de mensajes de vídeo entre las partes.', false), ('C', 'La comunicación bidireccional y simultánea de la imagen y el sonido y la interacción visual, auditiva y verbal.', true), ('D', 'La comunicación únicamente de sonido, siempre que el juez lo autorice.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica del Poder Judicial, para el tratamiento de los datos personales en el ejercicio de la actividad jurisdiccional:', 'El art. 236 ter.3 LOPJ exime del consentimiento del interesado el tratamiento de datos en el ejercicio de la actividad jurisdiccional, sin perjuicio de las normas procesales sobre validez de la prueba.', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 236 ter.3 LOPJ', '3. No será necesario el consentimiento del interesado para que se proceda al tratamiento de los datos personales en el ejercicio de la actividad jurisdiccional, ya sean éstos facilitados por las partes o recabados a solicitud de los órganos competentes, sin perjuicio de lo dispuesto en las normas procesales para la validez de la prueba.', null, 'fee5b21541918f515933c85289e5077e3cb0b8dc66373e6f27b567a4a4504cc2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'fee5b21541918f515933c85289e5077e3cb0b8dc66373e6f27b567a4a4504cc2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No será necesario el consentimiento del interesado, ya sean los datos facilitados por las partes o recabados a solicitud de los órganos competentes.', true), ('B', 'Será necesario en todo caso el consentimiento expreso y por escrito del interesado.', false), ('C', 'Será necesario el consentimiento del interesado, salvo en el orden penal.', false), ('D', 'Será necesaria la autorización previa de la Agencia Española de Protección de Datos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 236 octies de la Ley Orgánica del Poder Judicial, los tratamientos de datos con fines no jurisdiccionales en el ámbito de la Administración de Justicia estarán sometidos a la competencia de:', 'El art. 236 octies LOPJ atribuye la supervisión de los tratamientos con fines jurisdiccionales al CGPJ y a la Fiscalía General del Estado en sus respectivos ámbitos, y la de los no jurisdiccionales a la Agencia Española de Protección de Datos.', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 236 octies LOPJ', '2. Los tratamientos de datos con fines no jurisdiccionales estarán sometidos a la competencia de la Agencia Española de Protección de Datos', null, '7a29fe0963151448e99285a3d64baf4beedc011152b90f621f05d90d3924300f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7a29fe0963151448e99285a3d64baf4beedc011152b90f621f05d90d3924300f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Consejo General del Poder Judicial.', false), ('B', 'La Agencia Española de Protección de Datos.', true), ('C', 'La Fiscalía General del Estado.', false), ('D', 'El Comité técnico estatal de la Administración judicial electrónica.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 236 bis de la LOPJ, ¿cuándo tiene fines jurisdiccionales el tratamiento de datos personales?', 'Tienen fines jurisdiccionales los tratamientos de datos incorporados a procesos con finalidad jurisdiccional; los demás son no jurisdiccionales.', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 236 bis.1 LOPJ', 'Tendrá fines jurisdiccionales el tratamiento de los datos que se encuentren incorporados a los procesos que tengan por finalidad el ejercicio de la actividad jurisdiccional.', null, '17515d4273b90a706b756614e19f47fe878bb6ba0d17e1521e82ce4dc45f6833', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '17515d4273b90a706b756614e19f47fe878bb6ba0d17e1521e82ce4dc45f6833')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cuando los datos están incorporados a procesos que tienen por finalidad el ejercicio de la actividad jurisdiccional.', true), ('B', 'Siempre que los trate un funcionario de la Administración de Justicia.', false), ('C', 'Cuando los datos figuran en el registro de personal de la Oficina judicial.', false), ('D', 'Solo cuando los trata el Consejo General del Poder Judicial.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Cuándo se deniega en todo caso el acceso a datos tratados con fines jurisdiccionales?', 'El art. 236 septies.2 LOPJ deniega el acceso cuando las diligencias son o fueron declaradas secretas o reservadas.', 'jus_10_oficina_judicial', (select id from public.topics where slug = 'jus-10-oficina-judicial'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 236 septies.2 LOPJ', '2\. En todo caso se denegará el acceso a los datos objeto de tratamiento con fines jurisdiccionales cuando las diligencias procesales en que se haya recabado la información sean o hayan sido declaradas secretas o reservadas.', null, '629f0425671fb828621dca62124ec1bb0cce1bb54798f60e41d8b0719c3a7af3', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '629f0425671fb828621dca62124ec1bb0cce1bb54798f60e41d8b0719c3a7af3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
