with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Entre los principios generales de la acción preventiva del artículo 15 de la Ley 31/1995, de Prevención de Riesgos Laborales, figura el de:', 'El art. 15.1 de la Ley 31/1995 enumera, entre otros, evitar los riesgos, evaluar los que no se puedan evitar, combatirlos en su origen, adaptar el trabajo a la persona y anteponer la protección colectiva a la individual.', 'jus_15_libertad_sindical', (select id from public.topics where slug = 'jus-15-libertad-sindical'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 15.1.h Ley 31/1995', 'h) Adoptar medidas que antepongan la protección colectiva a la individual.', null, 'f3fc66c3b1ef11af226c89e2659d8a0f5302a9e6a8fb87f4f25aae37bfd31d43', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f3fc66c3b1ef11af226c89e2659d8a0f5302a9e6a8fb87f4f25aae37bfd31d43')
  returning id
