with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 21 de la Ley 31/1995, de Prevención de Riesgos Laborales, cuando un trabajador considere que su actividad entraña un riesgo grave e inminente para su vida o su salud:', 'El art. 21.2 de la Ley 31/1995 reconoce al trabajador el derecho a interrumpir la actividad y abandonar el lugar de trabajo ante un riesgo grave e inminente; la paralización acordada por los representantes debe comunicarse a la autoridad laboral, que la anula o ratifica en 24 horas (art. 21.3).', 'jus_15_libertad_sindical', (select id from public.topics where slug = 'jus-15-libertad-sindical'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 21.2 Ley 31/1995', 'el trabajador tendrá derecho a interrumpir su actividad y abandonar el lugar de trabajo, en caso necesario, cuando considere que dicha actividad entraña un riesgo grave e inminente para su vida o su salud.', null, '560c73fd0ea9e2efdb2df4be1f7cd55ffaccd7962ee23aa2f00d328fceac95f1', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '560c73fd0ea9e2efdb2df4be1f7cd55ffaccd7962ee23aa2f00d328fceac95f1')
  returning id
