with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Cómo se considera el tiempo que los Delegados de Prevención dedican a su formación en materia preventiva?', 'El art. 37.2 PRL lo considera tiempo de trabajo y prohíbe que su coste recaiga sobre los Delegados.', 'jus_15_libertad_sindical', (select id from public.topics where slug = 'jus-15-libertad-sindical'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 37.2 Ley 31/1995', 'El tiempo dedicado a la formación será considerado como tiempo de trabajo a todos los efectos y su coste no podrá recaer en ningún caso sobre los Delegados de Prevención.', null, 'd45010065bc7f33ab6e47c6c65ebc013bf49d87dd30f76bc57909f1d60a3f7e7', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd45010065bc7f33ab6e47c6c65ebc013bf49d87dd30f76bc57909f1d60a3f7e7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
