with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Qué es un «riesgo laboral grave e inminente» según la Ley de Prevención de Riesgos Laborales?', 'El art. 4.4.º PRL atiende a la probabilidad racional de materialización inmediata y a la gravedad del daño.', 'jus_15_libertad_sindical', (select id from public.topics where slug = 'jus-15-libertad-sindical'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 4.4.º Ley 31/1995', '4.º Se entenderá como «riesgo laboral grave e inminente» aquel que resulte probable racionalmente que se materialice en un futuro inmediato y pueda suponer un daño grave para la salud de los trabajadores.', null, '14117b70c05eb2821673c1e4622b1e18a36daa595687b4f0736913092a13b4b3', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '14117b70c05eb2821673c1e4622b1e18a36daa595687b4f0736913092a13b4b3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cualquier riesgo que haya causado ya un accidente.', false), ('B', 'Aquel que resulte probable racionalmente que se materialice en un futuro inmediato y pueda suponer un daño grave para la salud.', true), ('C', 'El que afecte a más de diez trabajadores a la vez.', false), ('D', 'El que la empresa no haya incluido en su evaluación de riesgos.', false)) as v(label, body, ok)
)
