with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Para calcular el número de Delegados de Prevención, ¿cómo se computan los trabajadores contratados por término de hasta un año?', 'Los contratos de más de un año cuentan como fijos; los de hasta un año, por cada doscientos días trabajados o fracción.', 'jus_15_libertad_sindical', (select id from public.topics where slug = 'jus-15-libertad-sindical'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 35.3 Ley 31/1995', 'b) Los contratados por término de hasta un año se computarán según el número de días trabajados en el período de un año anterior a la designación. Cada doscientos días trabajados o fracción se computarán como un trabajador más.', null, '71a2cee908c7f7224e4eee18819c17068fd8440b95e8867a0a7b22ab0c6623cb', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '71a2cee908c7f7224e4eee18819c17068fd8440b95e8867a0a7b22ab0c6623cb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Como trabajadores fijos de plantilla.', false), ('B', 'Según los días trabajados en el año anterior a la designación: cada doscientos días trabajados o fracción, un trabajador más.', true), ('C', 'No se computan.', false), ('D', 'Cada cien días trabajados, un trabajador más.', false)) as v(label, body, ok)
)
