with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El tiempo de los Delegados de Prevención dedicado a las reuniones del Comité de Seguridad y Salud, ¿se imputa a su crédito horario?', 'El art. 37.1 PRL excluye del crédito horario esas reuniones, las convocadas por el empresario y ciertas visitas.', 'jus_15_libertad_sindical', (select id from public.topics where slug = 'jus-15-libertad-sindical'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 37.1 Ley 31/1995', 'será considerado en todo caso como tiempo de trabajo efectivo, sin imputación al citado crédito horario, el correspondiente a las reuniones del Comité de Seguridad y Salud', null, 'd2b9105ebb4cd6ac38904980770cea37971bbd390e278c33af7a28f63d953351', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd2b9105ebb4cd6ac38904980770cea37971bbd390e278c33af7a28f63d953351')
  returning id
), o as (
