with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Qué son procesos, equipos o productos «potencialmente peligrosos» según la Ley de Prevención de Riesgos Laborales?', 'El art. 4.5.º PRL los define por originar riesgos en ausencia de medidas preventivas específicas.', 'jus_15_libertad_sindical', (select id from public.topics where slug = 'jus-15-libertad-sindical'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 4.5.º Ley 31/1995', '5.º Se entenderán como procesos, actividades, operaciones, equipos o productos «potencialmente peligrosos» aquellos que, en ausencia de medidas preventivas específicas, originen riesgos para la seguridad y la salud de los trabajadores que los desarrollan o utilizan.', null, 'ee1df3227e051d7dc26c5ccb3fd72c24c8a67635cb7b925b1662af1da675666b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ee1df3227e051d7dc26c5ccb3fd72c24c8a67635cb7b925b1662af1da675666b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Los que, en ausencia de medidas preventivas específicas, originan riesgos para la seguridad y salud de quienes los desarrollan o utilizan.', true), ('B', 'Los que figuran en una lista aprobada por la Unión Europea.', false), ('C', 'Los que ya han causado algún accidente en la empresa.', false), ('D', 'Los que utilizan energía eléctrica de alta tensión, exclusivamente.', false)) as v(label, body, ok)
)
