select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Los trabajadores designados por el empresario para ocuparse de la prevención, ¿qué protección tienen?', 'El art. 30.4 PRL prohíbe perjudicarles y les reconoce garantías del art. 68 a), b) y c) y 56.4 del Estatuto de los Trabajadores.', 'jus_15_libertad_sindical', (select id from public.topics where slug = 'jus-15-libertad-sindical'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 30.4 Ley 31/1995', '4\. Los trabajadores designados no podrán sufrir ningún perjuicio derivado de sus actividades de protección y prevención de los riesgos profesionales en la empresa.', null, 'd85146ef08d3779982035290a43d77ff6b99cff8adc5d82ea908d68c32fd7581', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd85146ef08d3779982035290a43d77ff6b99cff8adc5d82ea908d68c32fd7581')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ninguna especial; pueden ser despedidos libremente.', false), ('B', 'Solo la protección de la Inspección de Trabajo.', false), ('C', 'No pueden sufrir perjuicio por esas actividades y gozan de determinadas garantías de los representantes de los trabajadores.', true), ('D', 'La condición de funcionarios públicos.', false)) as v(label, body, ok)
)
