insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 1/2000, de 7 de enero, de Enjuiciamiento Civil (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('jus-17-ejecucion-civil', 'Tema 17. Los procedimientos de ejecución en la Ley de Enjuiciamiento Civil y las medidas cautelares') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial', 'tramitacion-procesal') and t.slug = 'jus-17-ejecucion-civil' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 517 de la Ley de Enjuiciamiento Civil, ¿cuál de los siguientes títulos tiene aparejada ejecución?', 'El art. 517.2 LEC incluye la sentencia de condena firme (1.º). Los acuerdos de mediación solo son título si se elevan a escritura pública (2.º), los títulos al portador deben representar obligaciones vencidas (6.º) y los certificados de anotaciones en cuenta no han de estar caducados (7.º).', 'jus_17_ejecucion_civil', (select id from public.topics where slug = 'jus-17-ejecucion-civil'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 517.2 LEC', '2. Solo tendrán aparejada ejecución los siguientes títulos: 1.º La sentencia de condena firme.', null, '1cbfc7006ccd7b4e6e360bf07a801168a6e3ce1422f788e3b7153c241a173f42', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1cbfc7006ccd7b4e6e360bf07a801168a6e3ce1422f788e3b7153c241a173f42')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El acuerdo de mediación que no haya sido elevado a escritura pública.', false), ('B', 'Los títulos al portador que representen obligaciones todavía no vencidas.', false), ('C', 'Los certificados caducados expedidos por las entidades encargadas de los registros contables de valores.', false), ('D', 'La sentencia de condena firme.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'La acción ejecutiva fundada en sentencia judicial caducará si no se interpone la correspondiente demanda ejecutiva dentro de:', 'El art. 518 LEC fija un plazo de caducidad de cinco años desde la firmeza de la sentencia o resolución para interponer la demanda ejecutiva.', 'jus_17_ejecucion_civil', (select id from public.topics where slug = 'jus-17-ejecucion-civil'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 518 LEC', 'caducará si no se interpone la correspondiente demanda ejecutiva dentro de los cinco años siguientes a la firmeza de la sentencia o resolución.', null, '7a2bff53a9ec272d16c234294e2bb8e3d746a60ad12fbfd576009f6007c61ec9', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7a2bff53a9ec272d16c234294e2bb8e3d746a60ad12fbfd576009f6007c61ec9')
  returning id
