with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Cuando el título ejecutivo sea una sentencia que obligue a entregar una cantidad determinada de dinero, según el artículo 580 de la Ley de Enjuiciamiento Civil:', 'El art. 580 LEC excluye el requerimiento de pago cuando el título es una resolución judicial, arbitral o del LAJ, una transacción o convenio aprobado en el proceso o un acuerdo de mediación. Para los demás títulos sí procede (art. 581).', 'jus_17_ejecucion_civil', (select id from public.topics where slug = 'jus-17-ejecucion-civil'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 580 LEC', 'Cuando el título ejecutivo consista en resoluciones del Letrado de la Administración de Justicia, resoluciones judiciales o arbitrales o que aprueben transacciones o convenios alcanzados dentro del proceso, o acuerdos de mediación, que obliguen a entregar cantidades determinadas de dinero, no será necesario requerir de pago al ejecutado para proceder al embargo de sus bienes.', null, '66a51c2fb23b2491dc32f3dcfa76131d5f2e93557da7ceedebb2e2a146bf8b92', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '66a51c2fb23b2491dc32f3dcfa76131d5f2e93557da7ceedebb2e2a146bf8b92')
  returning id
), o as (
