with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Si el depositario judicial no cumple sus obligaciones de conservación de los bienes embargados, ¿quién puede removerlo de su cargo y mediante qué resolución?', 'El art. 627.1 LEC permite al LAJ, de oficio o a instancia de parte, remover al depositario mediante decreto y designar a otro, sin perjuicio de su responsabilidad civil y penal.', 'jus_17_ejecucion_civil', (select id from public.topics where slug = 'jus-17-ejecucion-civil'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 627.1 LEC', 'A instancia de parte o, de oficio, si no cumpliere sus obligaciones, el Letrado de la Administración de Justicia encargado de la ejecución, mediante decreto, podrá remover de su cargo al depositario, designando a otro, sin perjuicio de la responsabilidad penal y civil en que haya podido incurrir el depositario removido.', null, 'fbbc49d6736a3260726ac15e71fd18d9ad6b0e031966de0d98660a2751e5a741', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'fbbc49d6736a3260726ac15e71fd18d9ad6b0e031966de0d98660a2751e5a741')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
