  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Cuando el ejecutado no lleva a cabo en plazo un hacer no personalísimo, según el artículo 706 de la Ley de Enjuiciamiento Civil el ejecutante podrá pedir:', 'En el hacer no personalísimo el art. 706.1 LEC permite encargarlo a un tercero a costa del ejecutado o pedir daños y perjuicios. Las multas mensuales y el equivalente pecuniario con multa única corresponden al hacer personalísimo (art. 709).', 'jus_17_ejecucion_civil', (select id from public.topics where slug = 'jus-17-ejecucion-civil'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 706.1 LEC', '1. Cuando el hacer a que obligue el título ejecutivo no sea personalísimo, si el ejecutado no lo llevara a cabo en el plazo señalado por el Letrado de la Administración de Justicia, el ejecutante podrá pedir que se le faculte para encargarlo a un tercero, a costa del ejecutado, o reclamar el resarcimiento de daños y perjuicios.', null, '8ee18158d8795b9f9d46a36c64345905dd18fa57bb5945788d1c8c1ec322731b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8ee18158d8795b9f9d46a36c64345905dd18fa57bb5945788d1c8c1ec322731b')
  returning id
), o as (
