  select '¿Cómo se insta la ejecución provisional según el artículo 524 de la LEC?', 'La ejecución provisional se insta por demanda o simple solicitud, en los términos del art. 549 LEC.', 'jus_17_ejecucion_civil', (select id from public.topics where slug = 'jus-17-ejecucion-civil'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 524.1 LEC', '1\. La ejecución provisional se instará por demanda o simple solicitud, según lo dispuesto en el artículo 549 de la presente ley.', null, '764ca180bc973777523ccecf664aac422398d09eada6de9571b8029221448153', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '764ca180bc973777523ccecf664aac422398d09eada6de9571b8029221448153')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Por demanda o simple solicitud, según el artículo 549.', true), ('B', 'Solo mediante demanda de juicio ordinario.', false), ('C', 'De oficio por el tribunal al dictar sentencia.', false), ('D', 'Mediante comparecencia ante el Ministerio Fiscal.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
