with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quien obtiene una sentencia de condena favorable en primera instancia, ¿debe prestar caución para pedir su ejecución provisional?', 'El art. 526 LEC permite la ejecución provisional sin simultánea prestación de caución, salvo los casos excluidos del art. 525.', 'jus_17_ejecucion_civil', (select id from public.topics where slug = 'jus-17-ejecucion-civil'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 526 LEC', 'podrá, sin simultánea prestación de caución, pedir y obtener su ejecución provisional', null, '8d3922d55fd9953093805159deee837755e88749eeac20550ea3490bfbb949a5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8d3922d55fd9953093805159deee837755e88749eeac20550ea3490bfbb949a5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sí, por el importe total de la condena.', false), ('B', 'Sí, por la mitad del importe de la condena.', false), ('C', 'Solo si el condenado es una Administración pública.', false), ('D', 'No, puede pedirla y obtenerla sin simultánea prestación de caución.', true)) as v(label, body, ok)
)
