select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿En qué plazo debe presentarse el escrito de oposición a la ejecución provisional?', 'El art. 529.1 LEC fija cinco días desde la notificación del despacho o de las actuaciones concretas.', 'jus_17_ejecucion_civil', (select id from public.topics where slug = 'jus-17-ejecucion-civil'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 529.1 LEC', '1\. El escrito de oposición a la ejecución provisional habrá de presentarse al tribunal de la ejecución dentro de los cinco días siguientes al de la notificación de la resolución que acuerde el despacho de ejecución o las actuaciones concretas a que se oponga.', null, '63a71ac2bd231cb12c22ebb7bdad6f51ebf5b039abe6000b98d829097040a42b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '63a71ac2bd231cb12c22ebb7bdad6f51ebf5b039abe6000b98d829097040a42b')
  returning id
), o as (
