with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En el proceso de ejecución, ¿deben estar el ejecutante y el ejecutado dirigidos por letrado y representados por procurador?', 'El art. 539.1 LEC exige letrado y procurador salvo en la ejecución de resoluciones de procesos en que no sean preceptivos.', 'jus_17_ejecucion_civil', (select id from public.topics where slug = 'jus-17-ejecucion-civil'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 539.1 LEC', '1\. El ejecutante y el ejecutado deberán estar dirigidos por letrado y representados por procurador, salvo que se trate de la ejecución de resoluciones dictadas en procesos en que no sea preceptiva la intervención de dichos profesionales.', null, '6a7d03677ed74ab1247a21c738f956dce94c05b1837ee3726a37057bac5912ef', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6a7d03677ed74ab1247a21c738f956dce94c05b1837ee3726a37057bac5912ef')
  returning id
