  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Si se revoca totalmente una condena dineraria ejecutada provisionalmente, ¿qué debe hacer el ejecutante?', 'El art. 533.1 LEC impone la devolución, el reintegro de costas y el resarcimiento de daños y perjuicios; el LAJ sobresee la ejecución provisional.', 'jus_17_ejecucion_civil', (select id from public.topics where slug = 'jus-17-ejecucion-civil'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 533.1 LEC', 'el ejecutante deberá devolver la cantidad que, en su caso, hubiere percibido, reintegrar al ejecutado las costas de la ejecución provisional que éste hubiere satisfecho y resarcirle de los daños y perjuicios que dicha ejecución le hubiere ocasionado.', null, '21e1916c48f625baf88bd203d9b90c9f9799db4160eb2ecad6125530ca44b0a8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '21e1916c48f625baf88bd203d9b90c9f9799db4160eb2ecad6125530ca44b0a8')
