  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En la ejecución provisional de una condena no dineraria, ¿en qué puede fundarse la oposición, además de en la infracción del artículo 527?', 'El art. 528.2.2.º LEC admite esa causa en las condenas no dinerarias.', 'jus_17_ejecucion_civil', (select id from public.topics where slug = 'jus-17-ejecucion-civil'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 528.2 LEC', '2.º Si la sentencia fuese de condena no dineraria, resultar imposible o de extrema dificultad, atendida la naturaleza de las actuaciones ejecutivas, restaurar la situación anterior a la ejecución provisional o compensar económicamente al ejecutado', null, 'f52f83f28d4dfab65fc9cb748d03c41fb907b12e887f83cda074c576c6badf9b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f52f83f28d4dfab65fc9cb748d03c41fb907b12e887f83cda074c576c6badf9b')
