)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Si se estima la oposición a la ejecución provisional por haberse despachado con infracción del artículo 527 de la LEC, ¿qué se acuerda?', 'El art. 530.1 LEC ordena un auto que declara no haber lugar a proseguir la ejecución provisional y alza las trabas.', 'jus_17_ejecucion_civil', (select id from public.topics where slug = 'jus-17-ejecucion-civil'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 530.1 LEC', 'la oposición a la ejecución provisional se resolverá mediante auto en el que se declarará no haber lugar a que prosiga dicha ejecución provisional, alzándose los embargos y trabas y las medidas de garantía que pudieran haberse adoptado.', null, 'd0800df9b7e7ab0bc44097739b6d369e6e9b1ad03770494661c8df0275060fba', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd0800df9b7e7ab0bc44097739b6d369e6e9b1ad03770494661c8df0275060fba')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Por decreto, la suspensión temporal hasta que se subsane.', false), ('B', 'Por auto, que no ha lugar a que prosiga la ejecución provisional, alzándose embargos, trabas y medidas de garantía.', true), ('C', 'Por sentencia, la condena en costas del ejecutante.', false), ('D', 'Por providencia, la conversión en ejecución definitiva.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Si la sentencia de condena dineraria ejecutada provisionalmente se revoca solo en parte, ¿qué se devuelve?', 'El art. 533.2 LEC solo obliga a devolver la diferencia, con el interés legal anual desde la percepción.', 'jus_17_ejecucion_civil', (select id from public.topics where slug = 'jus-17-ejecucion-civil'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 533.2 LEC', '2\. Si la revocación de la sentencia fuese parcial, sólo se devolverá la diferencia entre la cantidad percibida por el ejecutante y la que resulte de la confirmación parcial, con el incremento que resulte de aplicar a dicha diferencia, anualmente, desde el momento de la percepción, el tipo del interés legal del dinero.', null, '1f8261e30e16db2b8a47e0dc8c95f94c1a57ad838bef111beb8bc929e82c2ffa', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1f8261e30e16db2b8a47e0dc8c95f94c1a57ad838bef111beb8bc929e82c2ffa')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
