)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial', 'tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Si se revoca una resolución ejecutada provisionalmente que condenaba a entregar un bien determinado y la restitución es imposible, ¿qué puede pedir el ejecutado?', 'El art. 534.1 LEC prevé la restitución con rentas y frutos y, si es imposible, la indemnización liquidada por los arts. 712 y ss.', 'jus_17_ejecucion_civil', (select id from public.topics where slug = 'jus-17-ejecucion-civil'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 534.1 LEC', 'Si la restitución fuese imposible, de hecho o de derecho, el ejecutado podrá pedir que se le indemnicen los daños y perjuicios, que se liquidarán por el procedimiento establecido en los artículos 712 y siguientes.', null, 'b8f5540cec9856a4681874dfe1e843a5fccc5a8f9ab28fb2be6c7744a45e461d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b8f5540cec9856a4681874dfe1e843a5fccc5a8f9ab28fb2be6c7744a45e461d')
