with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 795 de la Ley de Enjuiciamiento Criminal, el procedimiento para el enjuiciamiento rápido de determinados delitos se aplica a delitos castigados con pena privativa de libertad que no exceda de:', 'El art. 795.1 LECrim limita los juicios rápidos a delitos con pena privativa de libertad no superior a cinco años (u otras penas cuya duración no exceda de diez años), incoados por atestado policial con detenido o citado ante el Juzgado de guardia.', 'jus_18_procedimientos_penales', (select id from public.topics where slug = 'jus-18-procedimientos-penales'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 795.1 LECrim', 'el procedimiento regulado en este Título se aplicará a la instrucción y al enjuiciamiento de delitos castigados con pena privativa de libertad que no exceda de cinco años, o con cualesquiera otras penas, bien sean únicas, conjuntas o alternativas, cuya duración no exceda de diez años', null, '0d9c36ae971d4955168f5b00c3b1c12948fcde92de9ab15f33688465785513ef', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0d9c36ae971d4955168f5b00c3b1c12948fcde92de9ab15f33688465785513ef')
