with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Si la injuria o calumnia se infirió por escrito, ¿qué debe presentarse con la querella, siendo posible?', 'El art. 806 LECrim exige presentar, siendo posible, el documento que contenga la injuria o calumnia.', 'jus_18_procedimientos_penales', (select id from public.topics where slug = 'jus-18-procedimientos-penales'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 806 LECrim', 'Si la injuria y calumnia se hubieren inferido por escrito, se presentará, siendo posible, el documento que la contenga.', null, 'f44b46d597c126508a88f1f475ea5d6c7b32e7945c9c8ebf33233eb4c3d3da57', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f44b46d597c126508a88f1f475ea5d6c7b32e7945c9c8ebf33233eb4c3d3da57')
  returning id
