insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial') and t.slug = 'jus-examen-2026-auxilio-casos' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 1. Marta tiene reconocido el derecho a la asistencia jurídica gratuita para este recurso. ¿Qué alcance tiene ese derecho en la instancia?', 'El art. 7.1 de la Ley 1/1996 extiende el beneficio a todos los trámites e incidencias de la instancia, incluida la ejecución, pero no a un proceso distinto.', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-750'), 'Art. 7.1 Ley 1/1996', '1\. La asistencia jurídica gratuita en el transcurso de una misma instancia se extiende a todos sus trámites e incidencias, incluida la ejecución, pero no podrá aplicarse a un proceso distinto.', null, '6c5cdf513cb01d6114bdc2230c1a2172725bef02481b1dd94e5b4bd104a918aa', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6c5cdf513cb01d6114bdc2230c1a2172725bef02481b1dd94e5b4bd104a918aa')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se extiende a todos sus trámites e incidencias, incluida la ejecución, pero no a un proceso distinto.', true), ('B', 'Se limita a la primera instancia y excluye la ejecución.', false), ('C', 'Se extiende a cualquier otro proceso que Marta inicie con posterioridad.', false), ('D', 'Solo alcanza a la vista y a la sentencia.', false)) as v(label, body, ok)
)
