insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial') and t.slug = 'jus-examen-2026-auxilio-casos' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 1. Marta está personada y representada por procurador. Aplicando supletoriamente el artículo 153 de la LEC, ¿cómo se le comunicará la sentencia?', 'La comunicación con las partes personadas se hace a través del procurador, que firma todas las notificaciones a su poderdante, incluidas las de sentencias.', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 153 LEC', 'La comunicación con las partes personadas en el juicio se hará a través de su procurador cuando éste las represente. El procurador firmará las notificaciones, emplazamientos, citaciones y requerimientos de todas clases que deban hacerse a su poderdante en el curso del pleito, incluso las de sentencias', null, '81ab3c075b3aa4d27999778fa03dd9e13817bc31562ba35f6aae776552854a50', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '81ab3c075b3aa4d27999778fa03dd9e13817bc31562ba35f6aae776552854a50')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Personalmente a Marta en su domicilio, por tratarse de una sentencia.', false), ('B', 'A Marta y a su procurador por separado, con efectos desde la última notificación.', false), ('C', 'A través de su procurador, que firmará la notificación, incluso la de la sentencia.', true), ('D', 'Mediante edicto en el Tablón Edictal Judicial Único.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 1. Se comunica una resolución a los servicios jurídicos de la comunidad autónoma demandada por medios electrónicos con los requisitos del artículo 162 de la LEC. ¿Cuándo se tiene por realizado el acto de comunicación?', 'Los actos de comunicación a los servicios jurídicos de las Administraciones autonómicas se tienen por realizados al día siguiente hábil a la fecha de recepción (art. 151.2 LEC).', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 151.2 LEC', 'se tendrán por realizados al día siguiente hábil a la fecha de recepción que conste en la diligencia o en el resguardo acreditativo de su efectiva recepción', null, 'e53a9d1c35192bab46dc346f7dc47d95a6205fc2f725e84c232b45a670fa9bf3', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e53a9d1c35192bab46dc346f7dc47d95a6205fc2f725e84c232b45a670fa9bf3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El mismo día de la recepción que conste en el resguardo.', false), ('B', 'Transcurridos tres días hábiles desde la remisión.', false), ('C', 'Al día siguiente hábil a la fecha de recepción que conste en el resguardo acreditativo.', true), ('D', 'Cuando el letrado de la comunidad autónoma firme el acuse.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 1. Una notificación dirigida al procurador de Marta a través del servicio de notificaciones del Colegio de Procuradores se remite a las 17:30 horas. ¿Cuándo se tiene por recibida?', 'Cuando el acto de comunicación se remite después de las 15:00 horas, se tiene por recibido al día siguiente hábil (art. 151.2 LEC).', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 151.2 LEC', 'Cuando el acto de comunicación fuera remitido con posterioridad a las 15:00 horas, se tendrá por recibido al día siguiente hábil.', null, '26cdbcf2759d984a7608b355f9d43780d76ac5b54642fcb2bd3786d5681c1345', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '26cdbcf2759d984a7608b355f9d43780d76ac5b54642fcb2bd3786d5681c1345')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ese mismo día, a las 17:30 horas.', false), ('B', 'Al día siguiente hábil.', true), ('C', 'A los tres días hábiles.', false), ('D', 'Al día siguiente, aunque sea inhábil.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 1. Notificada la sentencia, el procurador de Marta advierte un concepto oscuro en el fallo y quiere pedir su aclaración. ¿En qué plazos se pide y se resuelve?', 'La aclaración se solicita en los dos días hábiles siguientes a la publicación y se resuelve en los tres días siguientes; solo los errores materiales y aritméticos se rectifican en cualquier momento.', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 214.2 LEC', 'dentro de los dos días hábiles siguientes al de la publicación de la resolución, o a petición de parte o del Ministerio Fiscal formulada dentro del mismo plazo, siendo en este caso resuelta por quien hubiera dictado la resolución de que se trate dentro de los tres días siguientes al de la presentación del escrito en que se solicite la aclaración.', null, 'e90d23f320a1dc9b97e652c07f9f61b0bb15a910ffb09fd64a7ba125b97c5e3b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e90d23f320a1dc9b97e652c07f9f61b0bb15a910ffb09fd64a7ba125b97c5e3b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se pide dentro de los dos días hábiles siguientes a la publicación de la resolución y se resuelve dentro de los tres días siguientes a la presentación del escrito.', true), ('B', 'Se pide dentro de los cinco días siguientes a la notificación y se resuelve dentro de los diez días siguientes.', false), ('C', 'Se pide en cualquier momento y se resuelve dentro de los tres días siguientes.', false), ('D', 'Se pide dentro de los tres días siguientes a la notificación y se resuelve dentro de los dos días siguientes.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 2. La empresa, obligada a relacionarse electrónicamente con la Administración de Justicia y sin procurador, no accede en tres días a la primera citación remitida por medios electrónicos. ¿Qué procede, según la LEC aplicable supletoriamente?', 'Si se trata del primer emplazamiento o citación y pasan tres días sin acceso, se practica la comunicación domiciliaria (art. 161 LEC) y, si fracasa, la edictal (art. 155.1 LEC).', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 155.1 LEC', 'No obstante, si el acto de comunicación tuviese por objeto el primer emplazamiento o citación, o la realización o intervención personal de las partes en determinadas actuaciones procesales, y transcurrieran tres días sin que el destinatario acceda a su contenido, se procederá a la comunicación domiciliaria mediante entrega al destinatario en los términos del artículo 161. Si esta segunda comunicación resultara infructuosa, se procederá a su publicación en el Tablón Edictal Judicial Único', null, '98b038fb833daa92ef24983806935404d58c3376449868b1f4df5743cf3b1878', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '98b038fb833daa92ef24983806935404d58c3376449868b1f4df5743cf3b1878')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tenerla por citada al cuarto día, sin más trámite.', false), ('B', 'Publicar directamente la citación en el Tablón Edictal Judicial Único.', false), ('C', 'La comunicación domiciliaria mediante entrega y, si resulta infructuosa, la publicación en el Tablón Edictal Judicial Único.', true), ('D', 'Suspender el juicio hasta que acceda al sistema.', false)) as v(label, body, ok)
)
