select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
-- Lote jus-examen-2026-auxilio-casos-ljca-v1 (15 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 29/1998, de 13 de julio, reguladora de la Jurisdicción Contencioso-administrativa (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('jus-examen-2026-auxilio-casos', 'Examen réplica 2026 · Auxilio Judicial, segundo ejercicio (2 casos prácticos, 40 preguntas)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial') and t.slug = 'jus-examen-2026-auxilio-casos' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 1. Marta recurre una sanción de la Consejería de Medio Ambiente de su comunidad autónoma y vive en otra provincia de la misma comunidad. Según el artículo 14.1 de la LJCA, ¿qué Juzgado es territorialmente competente?', 'En materia de sanciones rige el fuero electivo de la regla segunda del art. 14.1 LJCA (domicilio del demandante o sede del órgano). Si el acto es autonómico, la elección queda limitada a la circunscripción del TSJ donde tiene su sede el órgano autor del acto.', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718'), 'Art. 14.1 LJCA', 'Segunda. Cuando el recurso tenga por objeto actos de las Administraciones públicas en materia de responsabilidad patrimonial, personal, propiedades especiales y sanciones será competente, a elección del demandante, el juzgado o el tribunal en cuya circunscripción tenga aquél su domicilio o se halle la sede del órgano autor del acto originario impugnado. […] la elección a que se refiere esta regla segunda se entenderá limitada a la circunscripción del Tribunal Superior de Justicia en que tenga su sede el órgano que hubiere dictado el acto originario impugnado.', null, '596d1a3df51d7e3fb8c47c6fedae396a3801dfbf2c9962a5cde3a489fc3178f2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '596d1a3df51d7e3fb8c47c6fedae396a3801dfbf2c9962a5cde3a489fc3178f2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Únicamente el de la circunscripción en que tenga su sede el órgano que dictó la sanción.', false), ('B', 'Únicamente el de la circunscripción del domicilio de Marta, por tratarse de una sanción.', false), ('C', 'A elección de Marta, el de la circunscripción de su domicilio o el de la sede del órgano autor del acto originario, dentro de la circunscripción del Tribunal Superior de Justicia donde tenga su sede ese órgano.', true), ('D', 'El Juzgado Central de lo Contencioso-Administrativo, por ser la sanción de una Administración autonómica.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 1. El recurso de Marta se sigue ante un Juzgado (órgano unipersonal). Si, en lugar de a un procurador, hubiera conferido su representación a su abogado, ¿a quién se notificarían las actuaciones según el artículo 23 de la LJCA?', 'Ante órganos unipersonales las partes pueden conferir su representación a un procurador y son asistidas en todo caso por abogado. Si la representación se confiere al abogado, a él se notifican las actuaciones.', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718'), 'Art. 23.1 LJCA', 'Cuando las partes confieran su representación al Abogado, será a éste a quien se notifiquen las actuaciones.', null, '19e9b98481353f573574f75bcceed08be9ab32fff74181ceddb2d3ff5132eccd', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '19e9b98481353f573574f75bcceed08be9ab32fff74181ceddb2d3ff5132eccd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A Marta personalmente, en su domicilio.', false), ('B', 'Al procurador que designe de oficio el Colegio.', false), ('C', 'Al abogado y, además, a Marta en su domicilio.', false), ('D', 'Al abogado.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 1. La sanción impugnada por Marta es de 6.500 €. ¿Por qué procedimiento conocerá el Juzgado de lo Contencioso-Administrativo?', 'El art. 78.1 LJCA atribuye al procedimiento abreviado, entre otros, todos los asuntos cuya cuantía no supere los 30.000 euros.', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718'), 'Art. 78.1 LJCA', 'así como todas aquellas cuya cuantía no supere los 30.000 euros.', null, '9cf4bd9e32de496c62762e84e6fecb4012395d691b72037693a50ec1d486ac1b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9cf4bd9e32de496c62762e84e6fecb4012395d691b72037693a50ec1d486ac1b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Por el procedimiento abreviado, al no superar la cuantía los 30.000 euros.', true), ('B', 'Por el procedimiento ordinario, por tratarse de una sanción.', false), ('C', 'Por el procedimiento para la protección de los derechos fundamentales.', false), ('D', 'Por el procedimiento abreviado solo si la Administración demandada presta su conformidad.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 1. Al examinar la comparecencia de Marta se advierte que no se ha acompañado el documento que acredita la representación del procurador. Según el artículo 45.3 de la LJCA, ¿qué plazo se concede para subsanarlo?', 'Si faltan los documentos o son incompletos, se requiere inmediatamente la subsanación con un plazo de diez días; de no hacerse, el Juez o Tribunal resuelve sobre el archivo.', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718'), 'Art. 45.3 LJCA', 'requerirá inmediatamente la subsanación de los mismos, señalando un plazo de diez días para que el recurrente pueda llevarla a efecto y, si no lo hiciere, el Juez o Tribunal se pronunciará sobre el archivo de las actuaciones.', null, 'af4a469161f582e372910f95f47280b0a6ebf833bedf2dc6d1b5f1bc57cf9069', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'af4a469161f582e372910f95f47280b0a6ebf833bedf2dc6d1b5f1bc57cf9069')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cinco días; si no se subsana, se tendrá a la recurrente por desistida sin más trámite.', false), ('B', 'Diez días; si no se subsana, el Juez o Tribunal se pronunciará sobre el archivo de las actuaciones.', true), ('C', 'Quince días; si no se subsana, se inadmitirá el recurso por decreto.', false), ('D', 'Tres días; si no se subsana, se nombrará procurador de oficio.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 1. La resolución sancionadora, que pone fin a la vía administrativa, se notificó expresamente a Marta. ¿Cuál es el plazo para interponer el recurso contencioso-administrativo?', 'Para actos expresos que ponen fin a la vía administrativa, el art. 46.1 LJCA fija dos meses desde el día siguiente a la notificación; los seis meses son para el acto presunto.', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718'), 'Art. 46.1 LJCA', 'El plazo para interponer el recurso contencioso-administrativo será de dos meses contados desde el día siguiente al de la publicación de la disposición impugnada o al de la notificación o publicación del acto que ponga fin a la vía administrativa, si fuera expreso.', null, '9269137c0c30784bf0b4b3af209f9c83d956873005b43bb0776eced885efbd34', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9269137c0c30784bf0b4b3af209f9c83d956873005b43bb0776eced885efbd34')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dos meses, contados desde el mismo día de la notificación.', false), ('B', 'Dos meses, contados desde el día siguiente al de la notificación.', true), ('C', 'Seis meses, contados desde el día siguiente al de la notificación.', false), ('D', 'Un mes, contado desde el día siguiente al de la notificación.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 1. Marta pidió por otrosí que el recurso se fallara sin prueba ni vista, y la Administración, al contestar, solicita la inadmisión del recurso. Según el artículo 57 de la LJCA, ¿qué procede?', 'Cuando no hay prueba ni vista y el demandado pide la inadmisión, se oye al demandante cinco días sobre la causa de inadmisión y luego se declara concluso el pleito.', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718'), 'Art. 57 LJCA', 'si el demandado solicita la inadmisión del recurso, se dará traslado al demandante para que en el plazo de cinco días formule las alegaciones que estime procedentes sobre la posible causa de inadmisión, y seguidamente se declarará concluso el pleito.', null, '695b26fbb5ebe5df62c42a6cb706686a9eefc7b77acf548d06442ca15d53b345', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '695b26fbb5ebe5df62c42a6cb706686a9eefc7b77acf548d06442ca15d53b345')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dar traslado a Marta para que en cinco días formule alegaciones sobre la posible causa de inadmisión y, seguidamente, declarar concluso el pleito.', true), ('B', 'Convocar de oficio a las partes a una vista para resolver sobre la inadmisión.', false), ('C', 'Dictar directamente auto de inadmisión, sin oír a la demandante.', false), ('D', 'Dar traslado a Marta por diez días para que amplíe la demanda.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 1. Marta pidió que se fallara sin vista, pero la Administración, dentro de los diez primeros días del plazo para contestar, solicita su celebración y el juez la acuerda por auto. ¿Qué recurso cabe contra ese auto?', 'El art. 78.3 LJCA declara irrecurrible el auto que acuerda la vista; solo el que la rechaza admite reposición.', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718'), 'Art. 78.3 LJCA', 'El auto que acuerde la celebración de vista no será recurrible', null, '24e0e76714e88150de01fd48d4ca759f6936c0b9cd50f31d535689a58b512cfe', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '24e0e76714e88150de01fd48d4ca759f6936c0b9cd50f31d535689a58b512cfe')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Recurso de reposición.', false), ('B', 'Recurso de apelación en un solo efecto.', false), ('C', 'Ninguno: el auto que acuerda la celebración de vista no es recurrible.', true), ('D', 'Recurso de revisión ante el juez.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 1. La Consejería remite el expediente administrativo de la sanción de Marta. Según el artículo 78.4 de la LJCA, ¿qué se hace con él?', 'Recibido el expediente, el LAJ lo entrega al actor y a los interesados personados para que puedan alegar en la vista.', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718'), 'Art. 78.4 LJCA', '4\. Recibido el expediente administrativo, el letrado o la letrada de la Administración de Justicia lo entregarán al actor y a las personas interesadas que se hubieren personado para que puedan hacer alegaciones en el acto de la vista.', null, '4372fbb1aa014bc1c7771b07770a3513091a7cb3a8229e8f71f0f7a41d1da173', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4372fbb1aa014bc1c7771b07770a3513091a7cb3a8229e8f71f0f7a41d1da173')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se une a los autos sin traslado a las partes hasta que se dicte sentencia.', false), ('B', 'Se entrega solo al juez para que lo examine antes de la vista.', false), ('C', 'Se devuelve a la Administración una vez comprobado que está completo.', false), ('D', 'El letrado o la letrada de la Administración de Justicia lo entrega a Marta y a los interesados personados para que puedan hacer alegaciones en el acto de la vista.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 1. El día señalado para la vista solo comparece el letrado de la comunidad autónoma; ni Marta ni su procurador acuden. ¿Qué acordará el juez?', 'Si no comparece ninguna parte o solo el demandado, el actor se tiene por desistido y se le condena en costas (art. 78.5 LJCA).', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718'), 'Art. 78.5 LJCA', 'Si las partes no comparecieren o lo hiciere sólo el demandado, el Juez o Tribunal tendrá al actor por desistido del recurso y le condenará en costas', null, 'ee0a06a910002e8b86a0cb733eeb7078ac8530d2c56c1d450922ac13375e2963', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ee0a06a910002e8b86a0cb733eeb7078ac8530d2c56c1d450922ac13375e2963')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tener a Marta por desistida del recurso y condenarla en costas.', true), ('B', 'Celebrar la vista en ausencia de la actora y dictar sentencia.', false), ('C', 'Suspender la vista y señalar nueva fecha.', false), ('D', 'Declarar a Marta en rebeldía y continuar el procedimiento.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 1. Celebrada la vista del recurso de Marta, ¿en qué plazo debe dictarse sentencia si no se dicta oralmente?', 'El art. 78.20 LJCA fija diez días desde la vista, sin perjuicio de que la sentencia se dicte oralmente al concluir el acto.', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718'), 'Art. 78.20 LJCA', 'El juez o la jueza dictarán sentencia en el plazo de diez días desde la celebración de la vista.', null, 'ebad587c0a465704a954fec27ce49b2b9d0573250a6e0b28fb920911ad18a406', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ebad587c0a465704a954fec27ce49b2b9d0573250a6e0b28fb920911ad18a406')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En cinco días desde la celebración de la vista.', false), ('B', 'En diez días desde la celebración de la vista.', true), ('C', 'En veinte días desde la celebración de la vista.', false), ('D', 'En un mes desde la celebración de la vista.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 1. El Juzgado desestima el recurso de Marta contra la sanción de 6.500 € en una sentencia sobre el fondo. ¿Cabe recurso de apelación?', 'No son apelables las sentencias en asuntos de cuantía no superior a 30.000 € (art. 81.1.a), salvo los casos del art. 81.2, como la que declara la inadmisibilidad.', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718'), 'Art. 81.1.a) LJCA', 'a) Aquellos cuya cuantía no exceda de 30.000 euros.', null, '9679fb4ae5b946a7bfd982138c7d0a6fc6263e19cd8b4ce14140207ce386f377', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9679fb4ae5b946a7bfd982138c7d0a6fc6263e19cd8b4ce14140207ce386f377')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sí, porque las sentencias de los Juzgados son siempre apelables.', false), ('B', 'Sí, pero solo si la Administración se adhiere.', false), ('C', 'No, porque en el procedimiento abreviado solo cabe recurso de casación.', false), ('D', 'No, porque la cuantía no excede de 30.000 euros.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 1. Admitida la demanda de Marta y citadas las partes a la vista, ¿con qué antelación mínima se requiere a la Consejería que remita el expediente administrativo?', 'En el abreviado, el LAJ requiere a la Administración el expediente en soporte electrónico con al menos quince días de antelación al término señalado para la vista (art. 78.3 LJCA).', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718'), 'Art. 78.3 LJCA', 'requerirá a la Administración demandada que remita el expediente administrativo en soporte electrónico, con al menos quince días de antelación del término señalado para la vista.', null, 'f5ef01755ec39924363a3e959a4a13fbad66c238a2cbc9a5c0d9471ef3d033e0', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f5ef01755ec39924363a3e959a4a13fbad66c238a2cbc9a5c0d9471ef3d033e0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al menos diez días antes de la vista, en soporte papel o electrónico.', false), ('B', 'Dentro de los veinte días siguientes a la recepción del requerimiento, con independencia de la fecha de la vista.', false), ('C', 'El mismo día de la vista, en soporte electrónico.', false), ('D', 'Al menos quince días antes del término señalado para la vista, en soporte electrónico.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 1. Transcurre el plazo de un trámite sin que la parte lo evacue y se le tiene por caducado el derecho. La parte presenta el escrito el mismo día en que se le notifica esa resolución, y no se trata de preparar ni interponer un recurso. ¿Qué ocurre?', 'Aunque los plazos son improrrogables, el art. 128.1 LJCA admite el escrito presentado dentro del día en que se notifica la resolución, salvo en plazos para preparar o interponer recursos.', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718'), 'Art. 128.1 LJCA', 'No obstante, se admitirá el escrito que proceda, y producirá sus efectos legales, si se presentare dentro del día en que se notifique la resolución, salvo cuando se trate de plazos para preparar o interponer recursos.', null, '81da23ad62832c040f225a8fdd13f630dc43831af00e5972162f7f2ec14fcaa5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '81da23ad62832c040f225a8fdd13f630dc43831af00e5972162f7f2ec14fcaa5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se rechaza, porque los plazos son improrrogables.', false), ('B', 'Se admite solo si la parte contraria no se opone.', false), ('C', 'Se admite el escrito y produce sus efectos legales.', true), ('D', 'Se admite, pero se impone una multa a la parte por el retraso.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 1. Marta solicita la suspensión cautelar de la sanción de 6.500 €. ¿Cómo se tramita el incidente cautelar?', 'El art. 131 LJCA ordena la pieza separada, la audiencia de la contraria (máximo diez días) y el auto en los cinco días siguientes.', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718'), 'Art. 131 LJCA', 'El incidente cautelar se sustanciará en pieza separada, con audiencia de la parte contraria, que ordenará el Secretario judicial por plazo que no excederá de diez días, y será resuelto por auto dentro de los cinco días siguientes.', null, '823142aee5919d8310c46984bb8b2c7984a71a2f246b8161dd26e9cadee77904', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '823142aee5919d8310c46984bb8b2c7984a71a2f246b8161dd26e9cadee77904')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En los autos principales, con audiencia de la parte contraria por cinco días, y se resuelve por sentencia.', false), ('B', 'En pieza separada, sin audiencia de la parte contraria, y se resuelve por decreto en tres días.', false), ('C', 'En pieza separada, con audiencia por veinte días, y se resuelve por providencia.', false), ('D', 'En pieza separada, con audiencia de la parte contraria por plazo no superior a diez días, y se resuelve por auto en los cinco días siguientes.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 1. El juez sospecha que el asunto planteado por Marta no corresponde al orden contencioso-administrativo. ¿Cómo debe proceder?', 'La jurisdicción contencioso-administrativa es improrrogable y la falta de jurisdicción se aprecia de oficio con audiencia de partes y Ministerio Fiscal por diez días comunes.', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718'), 'Art. 5.2 LJCA', '2\. Los órganos de este orden jurisdiccional apreciarán de oficio la falta de jurisdicción y resolverán sobre la misma, previa audiencia de las partes y del Ministerio Fiscal por plazo común de diez días.', null, '28dea56957043ba30c71fa4938fa0692b5ee625ff5e18abd34fc953bd41c568b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '28dea56957043ba30c71fa4938fa0692b5ee625ff5e18abd34fc953bd41c568b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Esperar a que la Administración demandada alegue la falta de jurisdicción.', false), ('B', 'Apreciar de oficio la falta de jurisdicción y resolver previa audiencia de las partes y del Ministerio Fiscal por plazo común de diez días.', true), ('C', 'Remitir directamente las actuaciones al órgano de otro orden jurisdiccional sin oír a nadie.', false), ('D', 'Oír solo al Ministerio Fiscal por plazo de cinco días.', false)) as v(label, body, ok)
)
