insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 36/2011, de 10 de octubre, reguladora de la jurisdicción social (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('jus-examen-2026-auxilio-casos', 'Examen réplica 2026 · Auxilio Judicial, segundo ejercicio (2 casos prácticos, 40 preguntas)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial') and t.slug = 'jus-examen-2026-auxilio-casos' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 2. Irene quiere demandar a la empresa sin abogado ni otro representante. Según el artículo 18.1 de la LRJS, ¿puede hacerlo?', 'En la instancia social las partes pueden comparecer por sí mismas (art. 18.1 LRJS).', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 18.1 LRJS', '1\. Las partes podrán comparecer por sí mismas o conferir su representación a abogado, procurador, graduado social colegiado o cualquier persona que se encuentre en el pleno ejercicio de sus derechos civiles.', null, '25e501d69366835121e848517951ebb1d4976f36d9f52ac959f8555f232c7cce', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '25e501d69366835121e848517951ebb1d4976f36d9f52ac959f8555f232c7cce')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No: en el proceso de despido es preceptiva la representación por procurador.', false), ('B', 'Sí: las partes pueden comparecer por sí mismas o conferir su representación a abogado, procurador, graduado social colegiado o cualquier persona en pleno ejercicio de sus derechos civiles.', true), ('C', 'No: debe estar asistida necesariamente por abogado o graduado social.', false), ('D', 'Solo si el Ministerio Fiscal no es parte en el proceso.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 2. Irene trabaja en la ciudad A y la empresa tiene su domicilio en la ciudad B; además demanda al jefe de almacén, que vive en una tercera ciudad. ¿Qué Juzgado de lo Social es competente?', 'La regla general del art. 10.1 LRJS es electiva (lugar de servicios o domicilio del demandado) y, con varios demandados, el fuero del domicilio permite elegir el de cualquiera.', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 10.1 LRJS', '1\. Con carácter general será juzgado competente el del lugar de prestación de los servicios o el del domicilio del demandado, a elección del demandante. […] En el caso de que sean varios los demandados, y se optare por el fuero del domicilio, el actor podrá elegir el de cualquiera de los demandados.', null, '6c03bd318c0bcbae9429187e113badbc4300ecab7d03a70b821bbc7f0e4ecd7b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6c03bd318c0bcbae9429187e113badbc4300ecab7d03a70b821bbc7f0e4ecd7b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Solo el del domicilio social de la empresa.', false), ('B', 'Solo el del domicilio de Irene.', false), ('C', 'A elección de Irene, el del lugar de prestación de los servicios o el del domicilio del demandado; si opta por el domicilio, el de cualquiera de los demandados.', true), ('D', 'El del lugar donde se firmó la carta de despido.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 2. ¿De qué plazo dispone Irene para reclamar contra su despido?', 'El art. 103.1 LRJS fija veinte días hábiles, plazo de caducidad a todos los efectos, sin computar sábados, domingos ni festivos en la sede del órgano.', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 103.1 LRJS', 'El trabajador podrá reclamar contra el despido, dentro de los veinte días hábiles siguientes a aquél en que se hubiera producido. Dicho plazo será de caducidad a todos los efectos y no se computarán los sábados, domingos y los festivos en la sede del órgano jurisdiccional.', null, 'ac5f53a877bfc764fb9355cbd9c44c7e22509c8bb3849c934f526645a49b0e35', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ac5f53a877bfc764fb9355cbd9c44c7e22509c8bb3849c934f526645a49b0e35')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Veinte días naturales siguientes al despido, de prescripción.', false), ('B', 'Treinta días hábiles siguientes al despido, de caducidad.', false), ('C', 'Dos meses desde el despido, de caducidad.', false), ('D', 'Veinte días hábiles siguientes al despido, de caducidad, sin computar sábados, domingos ni festivos en la sede del órgano.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 2. La demanda de Irene omite un documento de preceptiva aportación. ¿Qué plazo se le concede para subsanarlo?', 'El LAJ advierte de los defectos u omisiones de la demanda para que se subsanen en cuatro días (art. 81.1 LRJS).', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 81.1 LRJS', 'a fin de que los subsane dentro del plazo de cuatro días.', null, '9f155492e006fce10ab28a716c64d1e5087a0a07b30ff86b2758cf20c3861d21', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9f155492e006fce10ab28a716c64d1e5087a0a07b30ff86b2758cf20c3861d21')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cuatro días.', true), ('B', 'Diez días.', false), ('C', 'Quince días.', false), ('D', 'Dos días.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 2. Irene no subsana en plazo el defecto advertido en su demanda. ¿Qué hace el letrado o la letrada de la Administración de Justicia?', 'Si no se subsana, el LAJ da cuenta al juez, que resuelve sobre la admisibilidad en los tres días siguientes (art. 81.2 LRJS).', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 81.2 LRJS', 'En otro caso, dará cuenta al juez, jueza o tribunal para que por el mismo se resuelva, dentro de los tres días siguientes, sobre su admisibilidad.', null, '24c5496d394798dc18ae54f9b5c3bc3b366c38dfb835e763d53ca628d5d29630', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '24c5496d394798dc18ae54f9b5c3bc3b366c38dfb835e763d53ca628d5d29630')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Da cuenta al juez para que resuelva sobre la admisibilidad dentro de los tres días siguientes.', true), ('B', 'Archiva directamente la demanda por decreto.', false), ('C', 'Admite la demanda y señala el juicio.', false), ('D', 'Concede un nuevo plazo de diez días.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 2. Irene presenta la demanda sin acompañar la certificación del acto de conciliación previa. ¿Qué plazo tiene para acreditar su celebración o intento?', 'Sin perjuicio de admitir y señalar, el LAJ advierte que debe acreditarse la conciliación o su intento en quince días, con apercibimiento de archivo y de quedar sin efecto el señalamiento.', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 81.3 LRJS', 'advertirá al demandante que ha de acreditar la celebración o el intento del expresado acto en el plazo de quince días, contados a partir del día siguiente a la recepción de la notificación, con apercibimiento de archivo de las actuaciones', null, '8d12d4c3f81681821d480def1adc68ca85b4846dafade48c9d508f3bb46d716b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8d12d4c3f81681821d480def1adc68ca85b4846dafade48c9d508f3bb46d716b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cuatro días desde la notificación, con apercibimiento de inadmisión.', false), ('B', 'Diez días desde la presentación de la demanda.', false), ('C', 'Quince días desde el día siguiente a la recepción de la notificación, con apercibimiento de archivo.', true), ('D', 'Hasta el mismo día del juicio.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 2. Admitida la demanda de Irene, ¿cuándo se señalan los actos de conciliación y juicio y qué tiempo mínimo debe mediar hasta su celebración?', 'El LAJ señala día y hora en la propia resolución de admisión (decreto), debiendo mediar al menos diez días entre la citación y los actos (art. 82.1 LRJS).', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 82.1 LRJS', 'en la misma resolución de admisión a trámite el letrado o letrada de la Administración de Justicia señalará el día y la hora en que hayan de tener lugar, separada o sucesivamente, los actos de conciliación y de juicio, debiendo mediar un mínimo de diez días entre la citación y la efectiva celebración de dichos actos', null, 'f13a1182c816e68389a54e71a8a0cf648628e757a9431adb2954ddf1e023d4ea', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f13a1182c816e68389a54e71a8a0cf648628e757a9431adb2954ddf1e023d4ea')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En una resolución posterior del juez, con un mínimo de cinco días.', false), ('B', 'En la misma resolución de admisión, con un mínimo de veinte días.', false), ('C', 'Cuando la empresa conteste la demanda, con un mínimo de quince días.', false), ('D', 'En la misma resolución de admisión, con un mínimo de diez días entre la citación y la celebración.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 2. El decreto de admisión se comunica al Ministerio Fiscal por medios electrónicos con los requisitos del artículo 162.1 de la LEC. ¿Cuándo se tiene por realizado el acto de comunicación?', 'El art. 60.3 LRJS establece que las comunicaciones al Ministerio Fiscal, entre otros, se tienen por realizadas el día siguiente a la fecha de recepción.', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 60.3 LRJS', 'Los actos de comunicación al Ministerio Fiscal, a la Abogacía del Estado, a los letrados de las Cortes Generales y a los letrados de las Comunidades Autónomas y de la Administración de la Seguridad Social, así como las notificaciones a las partes, incluidas las que se realicen a través de los servicios organizados por los Colegios profesionales, se tendrán por realizados el día siguiente a la fecha de recepción', null, '4c82de5cdf55cb1f37bb1117df485dccea7d2d7c56f56e1d9bfda6253c9312ce', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4c82de5cdf55cb1f37bb1117df485dccea7d2d7c56f56e1d9bfda6253c9312ce')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El mismo día de su remisión.', false), ('B', 'El día siguiente a la fecha de recepción que conste en la diligencia o resguardo.', true), ('C', 'Transcurridos tres días desde su puesta a disposición.', false), ('D', 'Cuando el fiscal firme personalmente la diligencia.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 2. ¿Cuál de estas advertencias debe constar en las cédulas de citación de la empresa y del jefe de almacén?', 'El art. 82.4 LRJS impone esa advertencia y la de concurrir con todos los medios de prueba; las partes pueden conciliar antes de la fecha señalada.', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 82.4 LRJS', 'En las cédulas de citación se hará constar que los actos de conciliación y juicio no podrán suspenderse por incomparecencia del demandado, salvo causas justificadas y en los supuestos legalmente previstos.', null, '23814ff7e0aaea67ed5f5bb27acb16e916900edc6f367fa5a19487cea10eaaa6', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '23814ff7e0aaea67ed5f5bb27acb16e916900edc6f367fa5a19487cea10eaaa6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que los actos de conciliación y juicio no podrán suspenderse por incomparecencia del demandado, salvo causas justificadas y supuestos legalmente previstos.', true), ('B', 'Que la incomparecencia del demandado supondrá su condena automática.', false), ('C', 'Que deberán presentar contestación escrita a la demanda diez días antes del juicio.', false), ('D', 'Que la conciliación solo podrá alcanzarse el mismo día del juicio.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 2. La citación del jefe de almacén se practicó sin observar las formas legales, pero consta que se dio por enterado. ¿Qué efecto tiene?', 'Las comunicaciones irregulares son nulas, pero si el interesado se da por enterado la diligencia surte efecto desde ese momento (art. 61 LRJS).', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 61 LRJS', 'No obstante, si el interesado se hubiere dado por enterado o constara de forma suficiente su conocimiento procesal o extraprocesal de los elementos esenciales de la resolución, la diligencia surtirá efecto desde ese momento.', null, '7b30b80e4b42f34b9b964e06b8c53f652ca80c1a81c260dbecded88dc55c1e51', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7b30b80e4b42f34b9b964e06b8c53f652ca80c1a81c260dbecded88dc55c1e51')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es nula y debe repetirse en todo caso.', false), ('B', 'La diligencia surte efecto desde el momento en que se dio por enterado.', true), ('C', 'Es válida desde la fecha en que se practicó defectuosamente.', false), ('D', 'Es anulable solo si lo pide el Ministerio Fiscal.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 2. Fracasan las averiguaciones del domicilio del jefe de almacén y consta en el Registro Central de Rebeldes Civiles con los mismos datos. ¿Cómo acuerda el letrado o la letrada de la Administración de Justicia la comunicación edictal?', 'Comprobado el Registro Central de Rebeldes Civiles, el LAJ dicta diligencia de ordenación acordando directamente la comunicación edictal (art. 59.2 LRJS).', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 59.2 LRJS', 'En tal caso el letrado o letrada de la Administración de Justicia dictará diligencia de ordenación acordando directamente la comunicación edictal del interesado.', null, 'a51b92e6c49a241fec4dad8b71c0a844f40b2a2bc72d2c7b8772e6321306b2fe', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a51b92e6c49a241fec4dad8b71c0a844f40b2a2bc72d2c7b8772e6321306b2fe')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Mediante decreto, previa audiencia del demandante.', false), ('B', 'Dando cuenta al juez para que la acuerde por auto.', false), ('C', 'Mediante providencia del juez.', false), ('D', 'Directamente, mediante diligencia de ordenación.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 2. Durante el proceso se sabe que la empresa ha sido declarada insolvente. ¿Qué debe hacerse respecto del Fondo de Garantía Salarial?', 'En empresas insolventes, desaparecidas o en concurso se cita como parte al FOGASA con traslado de la demanda (art. 23.2 LRJS).', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 23.2 LRJS', 'el secretario judicial citará como parte al Fondo de Garantía Salarial, dándole traslado de la demanda a fin de que éste pueda asumir sus obligaciones legales e instar lo que convenga en Derecho.', null, 'b16d940780d5c94f4e48bc2b27c50f506f5ada51645ee2f496df26c468fe227b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b16d940780d5c94f4e48bc2b27c50f506f5ada51645ee2f496df26c468fe227b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Nada, porque solo interviene en la fase de ejecución.', false), ('B', 'Citarlo solo como testigo.', false), ('C', 'Esperar a que lo solicite la trabajadora.', false), ('D', 'Citarlo como parte, dándole traslado de la demanda.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 2. La citación del jefe de almacén, que no está obligado a relacionarse electrónicamente, debe practicarse fuera de la sede de la oficina judicial. ¿Cómo se hará como regla general?', 'Las comunicaciones fuera de la sede de la oficina judicial se hacen por correo certificado con acuse de recibo, uniéndose este a los autos (art. 56.1 LRJS).', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 56.1 LRJS', 'Las citaciones, notificaciones y emplazamientos que se practiquen fuera de la sede de la oficina judicial se harán, cualquiera que sea el destinatario, por correo certificado con acuse de recibo', null, 'dead8b4b886654988a2d620aded3640e744b56482aea6a5d62611fe155535347', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'dead8b4b886654988a2d620aded3640e744b56482aea6a5d62611fe155535347')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Por edicto en el Tablón Edictal Judicial Único.', false), ('B', 'Por correo certificado con acuse de recibo.', true), ('C', 'Por entrega personal del funcionario del Cuerpo de Auxilio Judicial en todo caso.', false), ('D', 'Por llamada telefónica documentada por diligencia.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 2. Se acude con la cédula al domicilio del jefe de almacén y no se le halla. ¿A quién puede entregarse?', 'El art. 57.1 LRJS permite la entrega a parientes, familiares o empleados mayores de catorce años y, en su defecto, al portero o conserje.', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 57.1 LRJS', 'si no fuese hallado se entregará aquélla al pariente más cercano o familiar o empleado, mayores de catorce años, que se hallaren en el domicilio y, en su defecto, a quien desempeñe funciones de portería o conserjería de la finca.', null, '50b37f0522f946d8cc1dcb665172babe394ff992df37b0bf260779fc9c014fc6', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '50b37f0522f946d8cc1dcb665172babe394ff992df37b0bf260779fc9c014fc6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Solo a su cónyuge, si es mayor de edad.', false), ('B', 'A cualquier vecino, sin límite de edad.', false), ('C', 'Al pariente más cercano, familiar o empleado mayor de catorce años que se halle en el domicilio y, en su defecto, a quien desempeñe funciones de portería o conserjería.', true), ('D', 'A nadie: debe intentarse de nuevo hasta hallarlo.', false)) as v(label, body, ok)
)
