with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 2. En el acto de conciliación ante el letrado o la letrada de la Administración de Justicia, Irene y la empresa llegan a un acuerdo. ¿Qué resolución se dicta?', 'Si hay avenencia, el LAJ dicta decreto aprobándola y acordando el archivo (art. 84.1 LRJS).', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 84.1 LRJS', 'Si las partes alcanzan la avenencia, dictará decreto aprobándola y acordando, además, el archivo de las actuaciones.', null, 'e5a95782854c2e584b590c5a4570678821da6dc083811d4d764fac001ce23766', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e5a95782854c2e584b590c5a4570678821da6dc083811d4d764fac001ce23766')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Decreto aprobando la avenencia y acordando el archivo de las actuaciones.', true), ('B', 'Sentencia homologando el acuerdo.', false), ('C', 'Auto del juez aprobando el acuerdo.', false), ('D', 'Diligencia de ordenación de archivo.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 2. La empresa, citada en forma, no comparece al acto de conciliación sin justificar su ausencia. ¿Qué consecuencia tiene?', 'La incomparecencia injustificada del demandado no impide la conciliación y el juicio, que continúa sin declarar la rebeldía, sin perjuicio de la sanción del art. 97.3 (art. 83.3 LRJS).', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 83.3 LRJS', 'La incomparecencia injustificada del demandado al acto de conciliación no impedirá la celebración de los actos de conciliación y juicio, continuando este sin necesidad de declarar su rebeldía', null, 'c748d9a0ed4f0ac6936e307a2d8b775f5e29bef054d878d2b35ea7c0afaa76ac', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c748d9a0ed4f0ac6936e307a2d8b775f5e29bef054d878d2b35ea7c0afaa76ac')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se suspenden los actos y se cita de nuevo a la empresa.', false), ('B', 'No impide la celebración de los actos de conciliación y juicio, que continúa sin necesidad de declarar su rebeldía.', true), ('C', 'Se declara a la empresa en rebeldía antes de seguir el juicio.', false), ('D', 'Se tiene a la empresa por allanada a la demanda.', false)) as v(label, body, ok)
)
