select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 2. Celebrado el juicio, ¿en qué plazos se dicta y se notifica la sentencia?', 'El art. 97.1 LRJS fija cinco días para dictar sentencia, que se publica inmediatamente y se notifica en los dos días siguientes.', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 97.1 LRJS', '1\. El juez o tribunal dictará sentencia en el plazo de cinco días, publicándose inmediatamente y notificándose a las partes o a sus representantes dentro de los dos días siguientes.', null, 'a1635ecd65359605108f720de0d320e45d7364d54a18812d49c4d09ec1049b58', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a1635ecd65359605108f720de0d320e45d7364d54a18812d49c4d09ec1049b58')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se dicta en cinco días y se notifica dentro de los dos días siguientes a su publicación.', true), ('B', 'Se dicta en diez días y se notifica en los tres días siguientes.', false), ('C', 'Se dicta en cinco días y se notifica en los cinco días siguientes.', false), ('D', 'Se dicta en veinte días y se notifica en los dos días siguientes.', false)) as v(label, body, ok)
)
