select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 2. Si se desestima la nulidad y se declara improcedente el despido de Irene, que no es representante de los trabajadores, ¿a qué se condena a la empresa?', 'En la improcedencia la opción entre readmisión con salarios de tramitación o indemnización corresponde al empresario (art. 110.1 LRJS), salvo si el despedido es representante legal o sindical (art. 110.2).', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 110.1 LRJS', 'Si el despido se declara improcedente, se condenará al empresario a la readmisión del trabajador en las mismas condiciones que regían antes de producirse el despido, así como al abono de los salarios de tramitación […] o, a elección de aquél, a que le abone una indemnización', null, 'fa6174ebb0592f0025f181a420c0d5bc55619436120d98be9159b74270e1c82a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'fa6174ebb0592f0025f181a420c0d5bc55619436120d98be9159b74270e1c82a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A readmitirla inmediatamente con abono de los salarios dejados de percibir, sin opción.', false), ('B', 'A abonarle únicamente la indemnización legal, sin opción de readmisión.', false), ('C', 'A readmitirla o indemnizarla, a elección de Irene.', false), ('D', 'A readmitirla con abono de los salarios de tramitación o, a elección del empresario, a abonarle la indemnización legal.', true)) as v(label, body, ok)
)
