select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso 2. Si se declara nulo el despido de Irene, ¿cuál es la condena?', 'La nulidad conlleva la inmediata readmisión con abono de los salarios dejados de percibir, y la sentencia se ejecuta provisionalmente aunque se recurra (art. 113 LRJS).', 'jus_examen_2026_auxilio_casos', (select id from public.topics where slug = 'jus-examen-2026-auxilio-casos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 113 LRJS', 'Si el despido fuera declarado nulo se condenará a la inmediata readmisión del trabajador con abono de los salarios dejados de percibir.', null, '2ffdc6552df7fba2f3b8a8505f86842ef9e8838e60ff30d24cd5aa50dff68c1d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2ffdc6552df7fba2f3b8a8505f86842ef9e8838e60ff30d24cd5aa50dff68c1d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La readmisión o la indemnización, a elección de la empresa.', false), ('B', 'Solo la indemnización por despido, incrementada.', false), ('C', 'La inmediata readmisión con abono de los salarios dejados de percibir.', true), ('D', 'La readmisión, sin abono de salarios.', false)) as v(label, body, ok)
)
