insert into public.sources (title, url, kind, publisher, published_on) values ('Carta de Derechos de los Ciudadanos ante la Justicia (aprobada por el Pleno del Congreso de los Diputados como Proposición no de Ley, 2002)', 'https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos', 'web_oficial'::public.source_kind, 'Consejo General del Poder Judicial (poderjudicial.es)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('jus-examen-2026-auxilio-test', 'Examen réplica 2026 · Auxilio Judicial, primer ejercicio (100 preguntas)') on conflict (slug) do nothing;
