with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el apartado 6 de la Carta de Derechos de los Ciudadanos ante la Justicia, el lenguaje utilizado en las vistas y comparecencias debe:', 'La Carta (apartado 6) reconoce el derecho a un lenguaje comprensible para quien no es especialista, sin renunciar a las exigencias técnicas.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 1, 'es', true, (select id from public.sources where url = 'https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos'), 'Carta, n.º 6', '6.- El ciudadano tiene derecho a que en las vistas y comparecencias se utilice un lenguaje que, respetando las exigencias técnicas necesarias, resulte comprensible para los ciudadanos que no sean especialistas en derecho.', null, '8d6a03886df6ecbf3a9b0870b1abde1ee0fa1b51e4bfc6ea62b0c2874d7b2d22', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8d6a03886df6ecbf3a9b0870b1abde1ee0fa1b51e4bfc6ea62b0c2874d7b2d22')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ajustarse en todo caso a la terminología técnica de las leyes procesales.', false), ('B', 'Resultar comprensible para los ciudadanos que no sean especialistas en derecho, respetando las exigencias técnicas necesarias.', true), ('C', 'Ser comprensible para los profesionales que intervengan, aunque no lo sea para los ciudadanos.', false), ('D', 'Traducirse por escrito a un lenguaje no técnico cuando lo pida cualquiera de las partes.', false)) as v(label, body, ok)
)
