with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el apartado 8 de la Carta de Derechos de los Ciudadanos ante la Justicia, el ciudadano puede disponer gratuitamente de los formularios necesarios para ejercer sus derechos ante los tribunales:', 'El apartado 8 de la Carta limita el derecho a los formularios gratuitos a los casos en que no es preceptiva la intervención de Abogado y Procurador.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 1, 'es', true, (select id from public.sources where url = 'https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos'), 'Carta, n.º 8', '8.- El ciudadano tiene derecho a disponer gratuitamente de los formularios necesarios para el ejercicio de sus derechos ante los tribunales cuando no sea preceptiva la intervención de Abogado y Procurador.', null, '97984afcf227a5572908810002bec7ae9041fb88e8ac37e96381cf88a513af2d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '97984afcf227a5572908810002bec7ae9041fb88e8ac37e96381cf88a513af2d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Solo si tiene reconocido el derecho a la asistencia jurídica gratuita.', false), ('B', 'En cualquier procedimiento, sea o no preceptiva la intervención de profesionales.', false), ('C', 'Cuando no sea preceptiva la intervención de Abogado y Procurador.', true), ('D', 'Únicamente en los procedimientos penales por delitos leves.', false)) as v(label, body, ok)
)
