with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El derecho del ciudadano a que no se le exija aportar documentos que ya obren en poder de las Administraciones Públicas, recogido en el apartado 20 de la Carta de Derechos de los Ciudadanos ante la Justicia, tiene como excepción:', 'La única salvedad del apartado 20 de la Carta es que las leyes procesales exijan expresamente la aportación.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 2, 'es', true, (select id from public.sources where url = 'https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos'), 'Carta, n.º 20', '20.- El ciudadano tiene derecho a que no se le exija la aportación de documentos que obren en poder de las Administraciones Públicas, salvo que las leyes procesales expresamente lo requieran.', null, '0995ebab7a64332252208fd5b3b75843ba75e4b232bf1964f855a19d885603bd', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0995ebab7a64332252208fd5b3b75843ba75e4b232bf1964f855a19d885603bd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que el documento tenga más de cinco años de antigüedad.', false), ('B', 'Que el órgano judicial lo considere conveniente por providencia.', false), ('C', 'Que la Administración que lo custodia no lo remita en diez días.', false), ('D', 'Que las leyes procesales expresamente lo requieran.', true)) as v(label, body, ok)
)
