with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El apartado 18 de la Carta de Derechos de los Ciudadanos ante la Justicia reconoce el derecho a exigir responsabilidades:', 'La Carta (apartado 18) recoge, como el art. 121 CE, la responsabilidad por error judicial y por funcionamiento anormal.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 1, 'es', true, (select id from public.sources where url = 'https://www.poderjudicial.es/cgpj/es/Servicios/Atencion-Ciudadana/Modelos-normalizados/Carta-de-Derechos-de-los-Ciudadanos'), 'Carta, n.º 18', '18.- El ciudadano tiene derecho a exigir responsabilidades por error judicial o por el funcionamiento anormal de la Administración de Justicia.', null, '28cc3d68a0c46b36b042bf90f06488315997ab4809d81864443462b247137669', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '28cc3d68a0c46b36b042bf90f06488315997ab4809d81864443462b247137669')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
