with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Constitución Española, ¿de conformidad con qué texto, entre otros, se interpretarán las normas relativas a los derechos fundamentales y libertades que la Constitución reconoce?', 'El art. 10.2 CE ordena interpretar los derechos fundamentales conforme a la DUDH y a los tratados y acuerdos internacionales ratificados por España.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 10.2 CE', '2. Las normas relativas a los derechos fundamentales y a las libertades que la Constitución reconoce se interpretarán de conformidad con la Declaración Universal de Derechos Humanos y los tratados y acuerdos internacionales sobre las mismas materias ratificados por España.', null, '47455196f8c0028b5bb657d8bbba9c0821fb5a1550f19f46cd0b2a93db4c8939', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '47455196f8c0028b5bb657d8bbba9c0821fb5a1550f19f46cd0b2a93db4c8939')
  returning id
