with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 16 de la Constitución Española:', 'El art. 16 CE garantiza la libertad ideológica y religiosa (limitada por el orden público), prohíbe obligar a declarar sobre creencias, declara que ninguna confesión es estatal y prevé relaciones de cooperación.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 16.2 CE', '2. Nadie podrá ser obligado a declarar sobre su ideología, religión o creencias. 3. Ninguna confesión tendrá carácter estatal.', null, 'c6e71c1495ebb9dae0283a9c08a65a2afecb8bfdb51e98bcdeab4df46166cece', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c6e71c1495ebb9dae0283a9c08a65a2afecb8bfdb51e98bcdeab4df46166cece')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Nadie podrá ser obligado a declarar sobre su ideología, religión o creencias.', true), ('B', 'La Iglesia Católica tiene carácter estatal.', false), ('C', 'La libertad religiosa no admite limitación alguna en sus manifestaciones.', false), ('D', 'Los poderes públicos no pueden mantener relaciones con ninguna confesión.', false)) as v(label, body, ok)
)
