with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 8 del Tratado de Funcionamiento de la Unión Europea, ¿qué objetivo se fija la Unión en todas sus acciones?', 'El art. 8 TFUE es una disposición de aplicación general: la igualdad entre hombres y mujeres es objetivo transversal de todas las acciones de la Unión.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 1, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12016E/TXT'), 'Art. 8 TFUE', 'En todas sus acciones, la Unión se fijará el objetivo de eliminar las desigualdades entre el hombre y la mujer y promover su igualdad.', null, 'ec29b1736850f3ee8dfbf02f1a521528b4218dff0669c5639a942288c38cf788', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ec29b1736850f3ee8dfbf02f1a521528b4218dff0669c5639a942288c38cf788')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Alcanzar el pleno empleo en todos los Estados miembros.', false), ('B', 'Garantizar la libre circulación de capitales con terceros países.', false), ('C', 'Eliminar las desigualdades entre el hombre y la mujer y promover su igualdad.', true), ('D', 'Armonizar las legislaciones nacionales en materia de igualdad.', false)) as v(label, body, ok)
)
