with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al Tratado de Funcionamiento de la Unión Europea, un ciudadano de la Unión que se encuentre en un tercer país donde no esté representado el Estado miembro del que es nacional:', 'Derecho de ciudadanía de los arts. 20.2.c) y 23 TFUE. La pregunta oficial correspondiente (n.º 69) fue anulada; la réplica pregunta por el mismo derecho con su artículo correcto.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 2, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12016E/TXT'), 'Art. 23 TFUE', 'Todo ciudadano de la Unión podrá acogerse, en el territorio de un tercer país en el que no esté representado el Estado miembro del que sea nacional, a la protección de las autoridades diplomáticas y consulares de cualquier Estado miembro, en las mismas condiciones que los nacionales de dicho Estado.', null, '69b1a0f8355b61f83a4487b67fa62767692052c76cd0036a91ff4728b20749f9', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '69b1a0f8355b61f83a4487b67fa62767692052c76cd0036a91ff4728b20749f9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Solo podrá acogerse a la protección de la delegación de la Unión en ese país.', false), ('B', 'Podrá acogerse a la protección de las autoridades diplomáticas y consulares de cualquier Estado miembro, en las mismas condiciones que los nacionales de dicho Estado.', true), ('C', 'Podrá acogerse a la protección de otro Estado miembro previo pago de las tasas consulares que correspondan a los extranjeros.', false), ('D', 'Carece de protección diplomática en ese país.', false)) as v(label, body, ok)
)
