with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 1 del Tratado de la Unión Europea, el Tratado de la Unión Europea y el Tratado de Funcionamiento de la Unión Europea:', 'El art. 1 TUE (y el art. 1.2 TFUE) declara que ambos Tratados tienen el mismo valor jurídico.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 1, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12016M/TXT'), 'Art. 1 TUE', 'La Unión se fundamenta en el presente Tratado y en el Tratado de Funcionamiento de la Unión Europea (en lo sucesivo denominados «los Tratados»). Ambos Tratados tienen el mismo valor jurídico.', null, 'b3a135116065ab7c2958ce1aeb17a75c5d2afe9fc1b9193a3329097619ad18fc', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b3a135116065ab7c2958ce1aeb17a75c5d2afe9fc1b9193a3329097619ad18fc')
  returning id
), o as (
