  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tienen distinto valor, prevaleciendo el Tratado de la Unión Europea.', false), ('B', 'Tienen distinto valor, prevaleciendo el Tratado de Funcionamiento.', false), ('C', 'Tienen el valor que les atribuya la Constitución de cada Estado miembro.', false), ('D', 'Tienen el mismo valor jurídico.', true)) as v(label, body, ok)
)
