with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 3 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, ¿cuál de las siguientes es una Entidad Local territorial?', 'Son territoriales el Municipio, la Provincia y la Isla en Baleares y Canarias; comarcas, áreas metropolitanas y mancomunidades son Entidades Locales pero no territoriales (art. 3.2 LBRL).', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392'), 'Art. 3.1 Ley 7/1985', '1. Son Entidades Locales territoriales: a) El Municipio. b) La Provincia. c) La Isla en los archipiélagos balear y canario.', null, 'b1eb69ca50fd8073313fdd25845e7ce797d586d636b020c8b73aefec68f0b66f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b1eb69ca50fd8073313fdd25845e7ce797d586d636b020c8b73aefec68f0b66f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La Comarca.', false), ('B', 'El Área Metropolitana.', false), ('C', 'La Isla en los archipiélagos balear y canario.', true), ('D', 'La Mancomunidad de Municipios.', false)) as v(label, body, ok)
)
