with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 15 de la Ley 7/1985, quien viva en varios municipios deberá inscribirse en el Padrón:', 'Cada persona se inscribe en un solo Padrón: el del municipio de residencia habitual o, si vive en varios, el de mayor permanencia anual; la condición de vecino se adquiere con la inscripción.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392'), 'Art. 15 Ley 7/1985', 'Quien viva en varios municipios deberá inscribirse únicamente en el que habite durante más tiempo al año.', null, 'c93c24e0ae837c5d2892a9910688a364651a66442560e6bc1758aacafa824069', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c93c24e0ae837c5d2892a9910688a364651a66442560e6bc1758aacafa824069')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'De todos los municipios en que resida.', false), ('B', 'Únicamente del municipio en el que habite durante más tiempo al año.', true), ('C', 'Del municipio en que haya nacido.', false), ('D', 'Del municipio que elija libremente, con independencia del tiempo que resida en él.', false)) as v(label, body, ok)
)
