with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 134.2 de la Ley de Enjuiciamiento Civil, la concurrencia de fuerza mayor que impida cumplir un plazo:', 'El art. 134.2 LEC: decreto del LAJ, de oficio o a instancia de la parte, con audiencia de las demás; recurso de revisión con efectos suspensivos.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 134.2 LEC', 'La concurrencia de fuerza mayor habrá de ser apreciada por el Letrado de la Administración de Justicia mediante decreto, de oficio o a instancia de la parte que la sufrió, con audiencia de las demás. Contra este decreto podrá interponerse recurso de revisión que producirá efectos suspensivos.', null, 'c57f162ab8cd788c36c42f0f52650385eb7e2fed246547ba7ae98be9297f88d6', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c57f162ab8cd788c36c42f0f52650385eb7e2fed246547ba7ae98be9297f88d6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La aprecia el Tribunal por providencia, sin recurso.', false), ('B', 'La aprecia el Letrado de la Administración de Justicia por diligencia de ordenación, recurrible en reposición.', false), ('C', 'La aprecia el Letrado de la Administración de Justicia por decreto, recurrible en revisión con efectos suspensivos.', true), ('D', 'La aprecia el Tribunal por auto, recurrible en apelación.', false)) as v(label, body, ok)
)
