  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 150.2 de la Ley de Enjuiciamiento Civil, por disposición del Tribunal se notificará la pendencia del proceso a las personas que puedan verse afectadas por la resolución que le ponga fin y, con los mismos requisitos, también:', 'El art. 150.2 LEC prevé esta comunicación a terceros afectados y cuando hay indicios de uso fraudulento del proceso.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 150.2 LEC', 'Esta comunicación se llevará a cabo, con los mismos requisitos, cuando el Tribunal advierta indicios de que las partes están utilizando el proceso con fines fraudulentos.', null, '5bd6c313c434d449b3892ec243b2b4f6a04346dbc78ec27c9e96887e8df5c179', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5bd6c313c434d449b3892ec243b2b4f6a04346dbc78ec27c9e96887e8df5c179')
