  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el texto vigente del artículo 137 bis.4 de la Ley de Enjuiciamiento Civil, el uso de medios de videoconferencia deberá solicitarse con la antelación suficiente y, en todo caso:', 'El texto consolidado vigente del art. 137 bis.4 LEC fija diez días de antelación mínima. La réplica sigue el texto vigente en el BOE.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 137 bis.4 LEC', '4. El uso de medios de videoconferencia deberá solicitarse con la antelación suficiente y, en todo caso, diez días antes del señalado para la actuación correspondiente.', null, 'a0fffeeedaa321e7200f4541752b563a45bd51f1644f8bebb4639ff5840ba654', false
