with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En el procedimiento por injurias y calumnias contra particulares, si hubiere causa justa y así se hiciere constar por certificación, ¿hasta cuántos días podrá ampliarse, según el artículo 809 de la Ley de Enjuiciamiento Criminal, el término para celebrar el juicio?', 'El juicio debe celebrarse en los tres días siguientes a la querella, ampliables hasta ocho con causa justa (art. 809 LECrim).', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 809 LECrim', 'El juicio deberá celebrarse dentro de los tres días siguientes al de la presentación de la querella ante el Juez instructor a quien corresponda su conocimiento. Si hubiere causa justa y se hiciere constar por certificación del Secretario, podrá ampliarse hasta ocho días el término para la celebración del juicio verbal.', null, '5151e083f20663e2bf0374d7371039befef8350fb5ff609d8351195f32958880', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5151e083f20663e2bf0374d7371039befef8350fb5ff609d8351195f32958880')
