with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En el procedimiento abreviado contencioso-administrativo, contra la resolución del Juez que deniega una prueba durante la vista, ¿qué recurso pueden interponer las partes conforme al artículo 78.17 de la Ley 29/1998?', 'El art. 78.17 LJCA prevé «recurso de súplica» en el acto, referencia que la disposición adicional 8.ª LJCA entiende hecha al recurso de reposición.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718'), 'Art. 78.17 Ley 29/1998', 'Contra las resoluciones del Juez sobre denegación de pruebas o sobre admisión de las que se denunciaran como obtenidas con violación de derechos fundamentales, las partes podrán interponer en el acto recurso de súplica […] La referencia al "recurso de súplica" se entiende hecha al "recurso de reposición"', null, '0489fec9ff651bbf947fe75a51545f76fd1ae30bb67d19eefb6ae0f2a04cd308', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0489fec9ff651bbf947fe75a51545f76fd1ae30bb67d19eefb6ae0f2a04cd308')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Recurso de reposición en el acto, que se sustanciará y resolverá seguidamente.', true), ('B', 'Recurso de apelación en el plazo de cinco días.', false), ('C', 'Recurso de revisión ante el Letrado de la Administración de Justicia.', false), ('D', 'Ningún recurso, sin perjuicio de hacer constar la protesta en el acta.', false)) as v(label, body, ok)
)
