  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 60.6 de la Ley 29/1998, en el acto de emisión de la prueba pericial, a petición de cualquiera de las partes, el Juez otorgará para solicitar aclaraciones al dictamen un plazo:', 'El art. 60.6 LJCA fija un plazo no superior a cinco días.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-16718'), 'Art. 60.6 Ley 29/1998', '6. En el acto de emisión de la prueba pericial, el Juez otorgará, a petición de cualquiera de las partes, un plazo no superior a cinco días para que las partes puedan solicitar aclaraciones al dictamen emitido.', null, '46d92192cb335b0a84f3457afa7b2801daf8d31a7edc0094a95752843e8c4ddc', false
