insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 11/1985, de 2 de agosto, de Libertad Sindical (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-16660', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
