insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('auxilio-judicial') and t.slug = 'jus-examen-2026-auxilio-test' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 7 de la Ley Orgánica 11/1985, de Libertad Sindical, para que un sindicato de ámbito autonómico sea más representativo en su Comunidad Autónoma debe obtener al menos el 15 por 100 de los delegados de personal y representantes de los trabajadores, contar con un mínimo de 1.500 representantes y, además:', 'El art. 7.1.a) LOLS exige el 15 %, un mínimo de 1.500 representantes y que el sindicato no esté federado ni confederado con organizaciones de ámbito estatal.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-16660'), 'Art. 7.1 LO 11/1985', 'Los sindicatos de dicho ámbito que acrediten en el mismo una especial audiencia expresada en la obtención de, al menos, el 15 por 100 de los delegados de personal y de los representantes de los trabajadores en los comités de empresa, y en los órganos correspondientes de las Administraciones públicas, siempre que cuenten con un mínimo de 1.500 representantes y no estén federados o confederados con organizaciones sindicales de ámbito estatal', null, '7c4b05ef6ad78dae799a9e1db1ff1e8bfdebfcb1b3a86d02b6503728778465d4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7c4b05ef6ad78dae799a9e1db1ff1e8bfdebfcb1b3a86d02b6503728778465d4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Estar federado con un sindicato más representativo a nivel estatal.', false), ('B', 'Haber negociado algún convenio colectivo en la Comunidad Autónoma en los últimos dos años.', false), ('C', 'No estar federado o confederado con organizaciones sindicales de ámbito estatal.', true), ('D', 'Estar inscrito en el registro de la Comunidad Autónoma con una antigüedad mínima de cuatro años.', false)) as v(label, body, ok)
)
