with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'A falta de acuerdos específicos, ¿cuántos delegados sindicales corresponden, según el artículo 10.2 de la Ley Orgánica de Libertad Sindical, a la sección sindical de un sindicato que obtuvo más del 10 por 100 de los votos en una empresa de 1.500 trabajadores?', 'La escala del art. 10.2 LOLS asigna dos delegados en el tramo de 751 a 2.000 trabajadores; si el sindicato no alcanza el 10 %, la sección tiene un solo delegado.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-16660'), 'Art. 10.2 LO 11/1985', 'De 250 a 750 trabajadores: Uno. De 751 a 2.000 trabajadores: Dos. De 2.001 a 5.000 trabajadores: Tres.', null, 'd25bba8ef3a1066d791651ae9dd65a8fe8b9b27238786e2027653179e11ebd8b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd25bba8ef3a1066d791651ae9dd65a8fe8b9b27238786e2027653179e11ebd8b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Uno.', false), ('B', 'Dos.', true), ('C', 'Tres.', false), ('D', 'Cuatro.', false)) as v(label, body, ok)
)
