with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Además del Presidente del Tribunal Supremo y de los Presidentes de Sala, ¿qué Magistrados de cada Sala forman parte de la Sala regulada en el artículo 61 de la Ley Orgánica del Poder Judicial?', 'La llamada Sala del artículo 61 la integran el Presidente del TS, los Presidentes de Sala y, de cada Sala, el Magistrado más antiguo y el más moderno.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 61.1 LOPJ', '1. Una Sala formada por el Presidente del Tribunal Supremo, los Presidentes de Sala y el Magistrado más antiguo y el más moderno de cada una de ellas conocerá:', null, '979f3c1ac23a1a68a84df0278557b32cede41e0181360a2d5bcb4ad4d4babede', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '979f3c1ac23a1a68a84df0278557b32cede41e0181360a2d5bcb4ad4d4babede')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El más antiguo y el más moderno de cada una de ellas.', true), ('B', 'Los dos más antiguos de cada una de ellas.', false), ('C', 'Únicamente el más moderno de cada una de ellas.', false), ('D', 'Los tres Magistrados de mayor antigüedad del Tribunal, cualquiera que sea su Sala.', false)) as v(label, body, ok)
)
