with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 74 de la Ley Orgánica del Poder Judicial, ¿de cuál de los siguientes recursos conocen en única instancia las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia?', 'El art. 74.1.g) LOPJ atribuye a las Salas de lo Contencioso-Administrativo de los TSJ los recursos sobre convenios entre Administraciones cuyas competencias se ejerzan en el territorio de la comunidad autónoma; los actos del Consejo de Ministros corresponden al Tribunal Supremo.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 74.1 LOPJ', 'g) Los convenios entre Administraciones públicas cuyas competencias se ejerzan en el ámbito territorial de la correspondiente comunidad autónoma.', null, '9941d862d744c2f123a1594ac7dadb37ded64dad42252b98edc5c07ac72025ce', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9941d862d744c2f123a1594ac7dadb37ded64dad42252b98edc5c07ac72025ce')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'De los que se deduzcan contra los actos del Consejo de Ministros.', false), ('B', 'De los que se deduzcan en relación con los convenios entre Administraciones públicas cuyas competencias se ejerzan en el ámbito territorial de la correspondiente comunidad autónoma.', true), ('C', 'De los que se deduzcan contra los actos de los Ministros y Secretarios de Estado en materia de personal.', false), ('D', 'De los recursos de casación para la unificación de doctrina entre Secciones de la Audiencia Nacional.', false)) as v(label, body, ok)
)
