with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 83 de la Ley Orgánica del Poder Judicial, ¿en qué ámbito se celebrará el juicio del Jurado?', 'El art. 83.1 LOPJ remite el juicio del Jurado al ámbito de la Audiencia Provincial «u otros Tribunales», en la forma que establezca la ley (LO 5/1995).', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 83.1 LOPJ', '1. El juicio del Jurado se celebrará en el ámbito de la Audiencia Provincial u otros Tribunales y en la forma que establezca la ley.', null, '64e60760246104612343a5112caa8e0abcff346dcaef637ff8899f5bc7dcf89f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '64e60760246104612343a5112caa8e0abcff346dcaef637ff8899f5bc7dcf89f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Exclusivamente en el de la Sección de lo Penal del Tribunal de Instancia.', false), ('B', 'Exclusivamente en el de la Sala de lo Civil y Penal del Tribunal Superior de Justicia.', false), ('C', 'En el de la Audiencia Provincial u otros Tribunales, en la forma que establezca la ley.', true), ('D', 'En el de la Sección de Instrucción que haya tramitado la causa.', false)) as v(label, body, ok)
)
