with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 65 de la Ley Orgánica del Poder Judicial, el enjuiciamiento de un delito de falsificación de moneda corresponde a la Sala de lo Penal de la Audiencia Nacional, salvo que corresponda en primera instancia a la Sección de lo Penal del Tribunal Central de Instancia, siempre que:', 'El art. 65.1.º b) LOPJ atribuye a la Sala de lo Penal de la AN la falsificación de moneda y de instrumentos de pago distintos del efectivo cometida por organizaciones o grupos criminales.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 65.1.º LOPJ', 'b) Falsificación de moneda y fabricación de tarjetas de crédito y débito falsas y cheques de viajero falsos o cualquier otro instrumento de pago distinto del efectivo, siempre que sean cometidos por organizaciones o grupos criminales.', null, 'f0b175bfe3a67a0b720ba45914cb985a9e47588539f93e56342daa3b455d1a26', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f0b175bfe3a67a0b720ba45914cb985a9e47588539f93e56342daa3b455d1a26')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Produzca efectos en el territorio de más de una comunidad autónoma.', false), ('B', 'El valor de lo falsificado supere el que fije anualmente el Consejo General del Poder Judicial.', false), ('C', 'Lo solicite el Ministerio Fiscal por razón de la complejidad de la causa.', false), ('D', 'Sea cometido por organizaciones o grupos criminales.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('auxilio-judicial');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 84.3 de la Ley Orgánica del Poder Judicial, una de las circunstancias que deben concurrir para que una Sección del Tribunal de Instancia cuente con Presidencia de Sección es:', 'El art. 84.3 LOPJ exige que haya dos o más Secciones en el Tribunal, que la Sección tenga ocho o más plazas y que el Tribunal sume doce o más plazas judiciales.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 84.3 LOPJ', 'a) Que en el Tribunal de Instancia hubiere dos o más Secciones. b) Que en la Sección de que se trate existan ocho o más plazas judiciales. c) Que el número total de plazas judiciales del Tribunal de Instancia sea igual o superior a doce.', null, 'fae85e6e80a12872468515e125254c209c72e5c6b45b4fb678ae8c137c23fa83', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'fae85e6e80a12872468515e125254c209c72e5c6b45b4fb678ae8c137c23fa83')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que en el Tribunal de Instancia hubiere dos o más Secciones.', true), ('B', 'Que en la Sección existan cinco o más plazas judiciales.', false), ('C', 'Que el Tribunal de Instancia tenga su sede en una capital de provincia.', false), ('D', 'Que el número total de plazas judiciales del Tribunal de Instancia sea igual o superior a ocho.', false)) as v(label, body, ok)
)
