with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Cuál de las siguientes Secciones NO figura entre las que, conforme al artículo 84.2 de la Ley Orgánica del Poder Judicial, pueden integrar además un Tribunal de Instancia?', 'El art. 84.2 LOPJ enumera las Secciones de Familia, Infancia y Capacidad; Mercantil; Violencia sobre la Mujer; Violencia contra la Infancia y la Adolescencia; Penal; Menores; Vigilancia Penitenciaria; Contencioso-Administrativo y Social. No hay una «Sección de Ejecución Civil».', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 84.2 LOPJ', 'a) De Familia, Infancia y Capacidad. b) De lo Mercantil. c) De Violencia sobre la Mujer. d) De Violencia contra la Infancia y la Adolescencia. e) De lo Penal. f) De Menores. g) De Vigilancia Penitenciaria.', null, '9ea5eb5b23e81965e03b1eab2a28fb51416b454fa11c08afc3f3c7be502bfa76', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9ea5eb5b23e81965e03b1eab2a28fb51416b454fa11c08afc3f3c7be502bfa76')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'De Familia, Infancia y Capacidad.', false), ('B', 'De Ejecución Civil.', true), ('C', 'De Violencia contra la Infancia y la Adolescencia.', false), ('D', 'De Vigilancia Penitenciaria.', false)) as v(label, body, ok)
)
