with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Producida una vacante en un Juzgado de Paz, ¿cuánto tiempo debe transcurrir sin propuesta del Ayuntamiento para que la Sala de Gobierno del Tribunal Superior de Justicia designe directamente al Juez de Paz, según el artículo 101.4 de la Ley Orgánica del Poder Judicial?', 'Si en tres meses desde la vacante el Ayuntamiento no propone, designa la Sala de Gobierno del TSJ (art. 101.4 LOPJ).', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 101.4 LOPJ', '4. Si en el plazo de tres meses, a contar desde que se produjera la vacante en un Juzgado de Paz, el Ayuntamiento correspondiente no efectuase la propuesta prevenida en los apartados anteriores, la Sala de Gobierno del Tribunal Superior de Justicia procederá a designar al Juez de Paz.', null, '434d1683290f8ec6e03a1f75087b621093b807addd6608e85f1545e81daff96a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '434d1683290f8ec6e03a1f75087b621093b807addd6608e85f1545e81daff96a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un mes desde que se produjo la vacante.', false), ('B', 'Seis meses desde que se produjo la vacante.', false), ('C', 'Dos meses desde que la Sala de Gobierno requirió al Ayuntamiento.', false), ('D', 'Tres meses desde que se produjo la vacante.', true)) as v(label, body, ok)
)
