with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 101 de la Ley Orgánica del Poder Judicial, los Jueces de Paz y sus sustitutos:', 'El Ayuntamiento elige (art. 101.2 LOPJ), pero nombra la Sala de Gobierno del TSJ, por cuatro años (art. 101.1).', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 101.1 LOPJ', '1. Los Jueces de Paz y sus sustitutos serán nombrados para un periodo de cuatro años por la Sala de Gobierno del Tribunal Superior de Justicia correspondiente. El nombramiento recaerá en las personas elegidas por el respectivo Ayuntamiento.', null, '13f14ae0b648b93cb64edc54f05bdac9b0230ca849622546708c1f96d90ea22c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '13f14ae0b648b93cb64edc54f05bdac9b0230ca849622546708c1f96d90ea22c')
  returning id
), o as (
