with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 243 de la Ley Orgánica del Poder Judicial, la nulidad de un acto procesal:', 'Los apartados 1 y 2 del art. 243 LOPJ recogen la conservación de los actos independientes y de las partes independientes del acto parcialmente nulo.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666'), 'Art. 243.1 LOPJ', '1. La nulidad de un acto no implicará la de los sucesivos que fueren independientes de aquél ni la de aquéllos cuyo contenido hubiese permanecido invariado aun sin haberse cometido la infracción que dio lugar a la nulidad.', null, '37311cddc4ba352302c7df2ce002a355d9d2a9bd30cddea781bb775aa04565c3', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '37311cddc4ba352302c7df2ce002a355d9d2a9bd30cddea781bb775aa04565c3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Arrastra siempre la de todos los actos posteriores del procedimiento.', false), ('B', 'Implicará la de todas las partes del acto, aunque sean independientes de la parte nula.', false), ('C', 'Solo puede declararse a instancia de parte.', false), ('D', 'No implicará la de los actos sucesivos que fueren independientes de aquél.', true)) as v(label, body, ok)
)
