with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 3 de la Ley 20/2011, del Registro Civil, ¿a quién corresponde la estructura, organización y funcionamiento de la base de datos única en la que se integran los datos del Registro Civil?', 'El art. 3.2 LRC declara el Registro Civil electrónico, con base de datos única competencia del Ministerio de Justicia.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628'), 'Art. 3.2 Ley 20/2011', '2. El Registro Civil es electrónico. Los datos serán objeto de tratamiento automatizado y se integrarán en una base de datos única cuya estructura, organización y funcionamiento es competencia del Ministerio de Justicia conforme a la presente Ley y a sus normas de desarrollo.', null, 'fc630a4977003a4eefa165a42ca29dadaf791baecb8c4ce4f87fc1177bb483bd', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'fc630a4977003a4eefa165a42ca29dadaf791baecb8c4ce4f87fc1177bb483bd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al Consejo General del Poder Judicial.', false), ('B', 'A cada Comunidad Autónoma en su territorio.', false), ('C', 'A la Agencia Española de Protección de Datos.', false), ('D', 'Al Ministerio de Justicia.', true)) as v(label, body, ok)
)
