with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 45 de la Ley 20/2011, del Registro Civil, ¿quién está obligado a promover la inscripción del nacimiento?', 'El art. 45 LRC obliga a la dirección de hospitales y clínicas, al personal sanitario si el parto fue fuera de establecimiento sanitario, a los progenitores (salvo la madre que renuncia) y al pariente más próximo o persona mayor de edad presente.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628'), 'Art. 45 Ley 20/2011', '1. La dirección de hospitales, clínicas y establecimientos sanitarios. 2. El personal médico o sanitario que haya atendido el parto, cuando éste haya tenido lugar fuera de establecimiento sanitario.', null, '57b0204595d74625f20cc80683c5f37dab11a4e9a139a29f9202c004435a2ea8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '57b0204595d74625f20cc80683c5f37dab11a4e9a139a29f9202c004435a2ea8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El personal sanitario que haya atendido el parto dentro de un establecimiento sanitario.', false), ('B', 'La dirección del hospital o clínica en que se haya producido el parto.', true), ('C', 'La madre que haya renunciado al hijo en el momento del parto.', false), ('D', 'Cualquier persona mayor de catorce años presente en el alumbramiento.', false)) as v(label, body, ok)
)
