with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 62.3 de la Ley 20/2011, del Registro Civil, en la inscripción de la defunción:', 'El art. 62.3 LRC reparte las tareas: el funcionario inscribe y certifica; el Encargado expide la licencia tras la inscripción.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-12628'), 'Art. 62.3 Ley 20/2011', '3. El funcionario competente, una vez recibida y examinada la documentación, practicará inmediatamente la inscripción y expedirá el certificado de la defunción. El Encargado, una vez practicada la inscripción, expedirá la licencia para el entierro o incineración en el plazo que reglamentariamente se establezca.', null, '7349ccd823c892e6004954b0d77014a2ebdb38e3532985aac766403a6c024367', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7349ccd823c892e6004954b0d77014a2ebdb38e3532985aac766403a6c024367')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El funcionario competente, recibida y examinada la documentación, practica la inscripción y expide el certificado de defunción, y el Encargado, practicada la inscripción, expide la licencia de entierro o incineración.', true), ('B', 'El Encargado expide la licencia de entierro antes de practicar la inscripción.', false), ('C', 'El médico forense expide la licencia de entierro o incineración.', false), ('D', 'La licencia de entierro la expide el Ayuntamiento del lugar del fallecimiento.', false)) as v(label, body, ok)
)
