  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Cuál de los siguientes NO es uno de los principios que el artículo 74.1 de la Ley 36/2011, reguladora de la jurisdicción social, establece para interpretar y aplicar las normas del proceso social ordinario?', 'Los principios del art. 74.1 LRJS son inmediación, oralidad, concentración y celeridad; la escritura es lo contrario de la oralidad.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 74.1 Ley 36/2011', 'interpretarán y aplicarán las normas reguladoras del proceso social ordinario según los principios de inmediación, oralidad, concentración y celeridad.', null, '9d757c42c9eee41a770de124e1b510d9afaa638d846126d61acb6c6d892dd022', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9d757c42c9eee41a770de124e1b510d9afaa638d846126d61acb6c6d892dd022')
  returning id
), o as (
