with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 92 de la Ley 36/2011, reguladora de la jurisdicción social, respecto de los testigos:', 'El art. 92 LRJS excluye las tachas y los escritos de preguntas, y permite al juez limitar los testigos si su número es excesivo; las observaciones se hacen solo en conclusiones.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 92.2 Ley 36/2011', '2. Los testigos no podrán ser tachados, y únicamente en conclusiones, las partes podrán hacer las observaciones que sean oportunas respecto de sus circunstancias personales y de la veracidad de sus manifestaciones.', null, '81ceb84b1da91a4130efeed96ed9c5d2a2a025442397649180459d92aff521a5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '81ceb84b1da91a4130efeed96ed9c5d2a2a025442397649180459d92aff521a5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Podrán ser tachados por escrito antes del juicio.', false), ('B', 'Las partes podrán presentar pliegos escritos de preguntas y repreguntas.', false), ('C', 'Su número no podrá limitarse por el órgano judicial.', false), ('D', 'No podrán ser tachados, y solo en conclusiones las partes podrán hacer observaciones sobre sus circunstancias personales y la veracidad de sus manifestaciones.', true)) as v(label, body, ok)
)
