with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la escala del artículo 35.2 de la Ley 31/1995, de Prevención de Riesgos Laborales, ¿cuántos Delegados de Prevención corresponden a un centro de 2.500 trabajadores?', 'La escala del art. 35.2 LPRL asigna 6 Delegados de Prevención al tramo de 2.001 a 3.000 trabajadores.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 35.2 Ley 31/1995', 'De 1.001 a 2.000 trabajadores: 5 Delegados de Prevención. De 2.001 a 3.000 trabajadores: 6 Delegados de Prevención. De 3.001 a 4.000 trabajadores: 7 Delegados de Prevención.', null, '7d490f69a3d2051c6ee795c4875476c5f330994c6a67d0b720a071cae2e9f15b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7d490f69a3d2051c6ee795c4875476c5f330994c6a67d0b720a071cae2e9f15b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '6 Delegados de Prevención.', true), ('B', '5 Delegados de Prevención.', false), ('C', '7 Delegados de Prevención.', false), ('D', '4 Delegados de Prevención.', false)) as v(label, body, ok)
)
