with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 4 de la Ley 31/1995, de Prevención de Riesgos Laborales, se entiende como «riesgo laboral»:', 'El art. 4.2.º LPRL define el riesgo laboral como posibilidad de daño; los daños derivados del trabajo (4.3.º), la prevención (4.1.º) y el equipo de trabajo (4.6.º) tienen definiciones propias.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 4.2.º Ley 31/1995', '2.º Se entenderá como «riesgo laboral» la posibilidad de que un trabajador sufra un determinado daño derivado del trabajo.', null, '0c969f4906f6ccea479a84d8ab8c375bd21a10d9b92981f6a7669481a152fc45', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0c969f4906f6ccea479a84d8ab8c375bd21a10d9b92981f6a7669481a152fc45')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Las enfermedades, patologías o lesiones sufridas con motivo u ocasión del trabajo.', false), ('B', 'El conjunto de actividades o medidas adoptadas para evitar o disminuir los daños derivados del trabajo.', false), ('C', 'Cualquier máquina, aparato o instalación utilizada en el trabajo.', false), ('D', 'La posibilidad de que un trabajador sufra un determinado daño derivado del trabajo.', true)) as v(label, body, ok)
)
