with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 13 del Real Decreto 937/2003, de modernización de los archivos judiciales, la remisión de documentos desde un Archivo Judicial de Gestión al Archivo Judicial Territorial o Central se formalizará periódicamente:', 'Art. 13.1 RD 937/2003: periodicidad mínima anual, con una relación de procedimientos según modelo uniforme y obligatorio.', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-15237'), 'Art. 13.1 RD 937/2003', 'se formalizará periódicamente, como mínimo con carácter anual, en función del volumen de gestión de cada archivo', null, '57b1ddbcd47eba47761fe86015625b3ffc4c20fa26d14284c0801238d5da3f6e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '57b1ddbcd47eba47761fe86015625b3ffc4c20fa26d14284c0801238d5da3f6e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Como mínimo con carácter anual, en función del volumen de gestión de cada archivo.', true), ('B', 'Como mínimo cada cinco años.', false), ('C', 'Cada seis meses, en todo caso.', false), ('D', 'Solo cuando lo acuerde la Junta de Expurgo.', false)) as v(label, body, ok)
)
