with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 7.3 del Real Decreto 937/2003, los documentos judiciales que puedan afectar a la intimidad de las personas, cuando no conste la fecha de su muerte ni medie su consentimiento, no podrán ser consultados públicamente hasta que transcurra:', 'Sin consentimiento expreso: 25 años desde la muerte si la fecha es conocida o, en otro caso, 50 años desde la fecha de los documentos (art. 7.3 RD 937/2003).', 'jus_examen_2026_auxilio_test', (select id from public.topics where slug = 'jus-examen-2026-auxilio-test'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-15237'), 'Art. 7.3 RD 937/2003', 'no podrán ser públicamente consultados sin que medie consentimiento expreso de los afectados o hasta que haya transcurrido un plazo de 25 años desde su muerte, si su fecha es conocida o, en otro caso, de 50 años a partir de la fecha de los documentos.', null, 'ea46c568372241756d3f2248b6650812632d8d1e24827e76ad0eaddabca4b964', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ea46c568372241756d3f2248b6650812632d8d1e24827e76ad0eaddabca4b964')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un plazo de 25 años a partir de la fecha de los documentos.', false), ('B', 'Un plazo de 50 años a partir de la fecha de los documentos.', true), ('C', 'Un plazo de 30 años desde la firmeza de la resolución.', false), ('D', 'Un plazo de 100 años desde el nacimiento del afectado.', false)) as v(label, body, ok)
)
