  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El desarrollo del programa legislativo del Estado en materia procesal.', false), ('B', 'La actualización y modificación de la organización judicial.', false), ('C', 'El funcionamiento de los servicios de inspección sobre los juzgados y tribunales.', false), ('D', 'La selección y formación inicial de los miembros de las carreras judicial y fiscal.', true)) as v(label, body, ok)
)
