with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 753 de la Ley de Enjuiciamiento Civil, salvo que expresamente se disponga otra cosa, los procesos sobre capacidad, filiación, matrimonio y menores se sustancian por los trámites del:', 'Se tramitan como juicio verbal, pero con contestación escrita en veinte días conforme al art. 405.', 'justra_18_procesos_especiales', (select id from public.topics where slug = 'justra-18-procesos-especiales'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 753.1 LEC', 'Salvo que expresamente se disponga otra cosa, los procesos a que se refiere este título se sustanciarán por los trámites del juicio verbal. […] emplazándoles para que la contesten en el plazo de veinte días, conforme a lo establecido en el artículo 405.', null, 'b17a1ebb7ec1aaa722616fead17aa363b695a3d6231b83e22bf84d5e24563d37', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b17a1ebb7ec1aaa722616fead17aa363b695a3d6231b83e22bf84d5e24563d37')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Juicio ordinario, con un plazo de veinte días para contestar a la demanda.', false), ('B', 'Juicio verbal, con un plazo de veinte días para contestar a la demanda.', true), ('C', 'Juicio verbal, con un plazo de diez días para contestar a la demanda.', false), ('D', 'Procedimiento de jurisdicción voluntaria.', false)) as v(label, body, ok)
)
