with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 753.3 de la Ley de Enjuiciamiento Civil, los procesos sobre capacidad, filiación, matrimonio y menores serán de tramitación preferente:', 'La preferencia depende de la presencia de menores, personas con apoyo representativo o ausentes legales.', 'justra_18_procesos_especiales', (select id from public.topics where slug = 'justra-18-procesos-especiales'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 753.3 LEC', 'Los procesos a los que se refiere este título serán de tramitación preferente siempre que alguno de los interesados en el procedimiento sea menor, persona con discapacidad con medidas judiciales de apoyo en las que se designe un apoyo con funciones representativas, o esté en situación de ausencia legal.', null, 'df39f0a3eb5469a08a701b5d762172e029f1c7fa5ff0b7debb2c5f828e0837a8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'df39f0a3eb5469a08a701b5d762172e029f1c7fa5ff0b7debb2c5f828e0837a8')
  returning id
), o as (
