  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Solo cuando lo solicite el Ministerio Fiscal.', false), ('B', 'En todo caso, con independencia de quiénes sean los interesados.', false), ('C', 'Únicamente en los procesos de separación y divorcio contenciosos.', false), ('D', 'Siempre que alguno de los interesados en el procedimiento sea menor, persona con discapacidad con medidas judiciales de apoyo en las que se designe un apoyo con funciones representativas, o esté en situación de ausencia legal.', true)) as v(label, body, ok)
)
