  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 770 de la Ley de Enjuiciamiento Civil, en un proceso contencioso de separación o divorcio, los hijos menores:', 'Regla 4.ª del art. 770 LEC: la edad relevante es doce años.', 'justra_18_procesos_especiales', (select id from public.topics where slug = 'justra-18-procesos-especiales'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 770.4ª LEC', 'podrán ser oídos cuando tengan menos de doce años, debiendo ser oídos en todo caso si hubieran alcanzado dicha edad.', null, '4bf240900440f4edd1af2bae6b9170d8f6aa5106c72a7440669b86c819068880', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4bf240900440f4edd1af2bae6b9170d8f6aa5106c72a7440669b86c819068880')
