  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un internamiento urgente, ¿en qué plazos debe el centro dar cuenta al tribunal y este ratificar la medida?', 'El art. 763.1 LEC fija 24 horas para dar cuenta y 72 horas para la ratificación.', 'justra_18_procesos_especiales', (select id from public.topics where slug = 'justra-18-procesos-especiales'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 763.1 LEC', 'deberá dar cuenta de éste al tribunal competente lo antes posible y, en todo caso, dentro del plazo de veinticuatro horas, a los efectos de que se proceda a la preceptiva ratificación de dicha medida, que deberá efectuarse en el plazo máximo de setenta y dos horas desde que el internamiento llegue a conocimiento del tribunal.', null, 'ee02e5efc3273ef38c83e6eb042cf2399fc03548878856a2cab154245f6afee2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ee02e5efc3273ef38c83e6eb042cf2399fc03548878856a2cab154245f6afee2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El centro, en cuarenta y ocho horas; el tribunal, en cinco días.', false), ('B', 'El centro, dentro de veinticuatro horas; el tribunal, en un máximo de setenta y dos horas desde que conoce el internamiento.', true), ('C', 'El centro, en tres días; el tribunal, en diez días.', false), ('D', 'El centro, de inmediato; el tribunal, en veinticuatro horas.', false)) as v(label, body, ok)
)
