with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Antes de autorizar o ratificar un internamiento, ¿qué debe hacer el tribunal?', 'El art. 763.3 LEC impone esas audiencias y el examen personal por el tribunal.', 'justra_18_procesos_especiales', (select id from public.topics where slug = 'justra-18-procesos-especiales'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 763.3 LEC', 'el tribunal oirá a la persona afectada por la decisión, al Ministerio Fiscal y a cualquier otra persona cuya comparecencia estime conveniente o le sea solicitada por el afectado por la medida. Además, y sin perjuicio de que pueda practicar cualquier otra prueba que estime relevante para el caso, el tribunal deberá examinar por sí mismo a la persona', null, '75ae335cf6ddcd63e84f45ceb1a42b9a6be4bf7c56fcf3aa72655198edfec005', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '75ae335cf6ddcd63e84f45ceb1a42b9a6be4bf7c56fcf3aa72655198edfec005')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Solo recabar el informe del centro.', false), ('B', 'Oír únicamente a los familiares.', false), ('C', 'Solo examinar el historial clínico.', false), ('D', 'Oír a la persona afectada, al Ministerio Fiscal y a quien estime conveniente, y examinar por sí mismo a la persona.', true)) as v(label, body, ok)
)
