with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En el proceso de restitución de menores, ¿puede el juez adoptar medidas cautelares de aseguramiento del menor?', 'El art. 778 quáter.8 LEC permite medidas cautelares durante todo el proceso, además de las del art. 158 CC.', 'justra_18_procesos_especiales', (select id from public.topics where slug = 'justra-18-procesos-especiales'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-323'), 'Art. 778 quáter.8 LEC', '8\. El Juez podrá acordar a lo largo de todo el proceso, de oficio, a petición de quien promueva el procedimiento o del Ministerio Fiscal, las medidas cautelares oportunas y de aseguramiento del menor', null, '1e077f42ad596604deea4493b9ec0c524441b454288a9923d7a8c8e87edd9de3', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1e077f42ad596604deea4493b9ec0c524441b454288a9923d7a8c8e87edd9de3')
