insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 15/2015, de 2 de julio, de la Jurisdicción Voluntaria (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-7391', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('justra-19-jurisdiccion-voluntaria', 'Tramitación, tema 19. La jurisdicción voluntaria: naturaleza y clases de procedimientos. Especial referencia a los actos de conciliación') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('tramitacion-procesal') and t.slug = 'justra-19-jurisdiccion-voluntaria' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 1 de la Ley 15/2015, de la Jurisdicción Voluntaria, se consideran expedientes de jurisdicción voluntaria todos aquellos que requieran la intervención de un órgano jurisdiccional para la tutela de derechos e intereses en materia de Derecho civil y mercantil:', 'La nota definitoria de la jurisdicción voluntaria es la ausencia de controversia que deba sustanciarse en un proceso contencioso.', 'justra_19_jurisdiccion_voluntaria', (select id from public.topics where slug = 'justra-19-jurisdiccion-voluntaria'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-7391'), 'Art. 1.2 LJV', 'Se consideran expedientes de jurisdicción voluntaria a los efectos de esta Ley todos aquellos que requieran la intervención de un órgano jurisdiccional para la tutela de derechos e intereses en materia de Derecho civil y mercantil, sin que exista controversia que deba sustanciarse en un proceso contencioso.', null, '928302d9024b7f80c6a360b1a1ba98e0c52c34ec77625c807ab25fc0bfc5b320', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '928302d9024b7f80c6a360b1a1ba98e0c52c34ec77625c807ab25fc0bfc5b320')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Siempre que exista oposición de algún interesado.', false), ('B', 'Sin que exista controversia que deba sustanciarse en un proceso contencioso.', true), ('C', 'Cuando la cuantía no exceda de 6.000 euros.', false), ('D', 'Únicamente cuando estén interesados menores de edad.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme a la Ley de la Jurisdicción Voluntaria, la competencia territorial en los expedientes de jurisdicción voluntaria:', 'El art. 2.2 LJV excluye la sumisión expresa o tácita: rige el fuero que fije el precepto aplicable a cada expediente.', 'justra_19_jurisdiccion_voluntaria', (select id from public.topics where slug = 'justra-19-jurisdiccion-voluntaria'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-7391'), 'Art. 2.2 LJV', 'En los expedientes de jurisdicción voluntaria la competencia territorial vendrá fijada por el precepto correspondiente en cada caso, sin que quepa modificarla por sumisión expresa o tácita.', null, 'ee8a8b554623eee95c064995ada5a2c1c89bf4dad412421c190087bbc318056d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ee8a8b554623eee95c064995ada5a2c1c89bf4dad412421c190087bbc318056d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Puede modificarse por sumisión expresa, pero no tácita.', false), ('B', 'Corresponde siempre al domicilio del solicitante.', false), ('C', 'Vendrá fijada por el precepto correspondiente en cada caso, sin que quepa modificarla por sumisión expresa o tácita.', true), ('D', 'Se determina libremente por el solicitante entre los órganos de la provincia.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('tramitacion-procesal');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 2.3 de la Ley de la Jurisdicción Voluntaria, el impulso y la dirección de los expedientes de jurisdicción voluntaria corresponde:', 'El impulso y dirección es del Secretario judicial (hoy LAJ); la decisión de fondo es del Juez o del LAJ según lo que disponga la ley.', 'justra_19_jurisdiccion_voluntaria', (select id from public.topics where slug = 'justra-19-jurisdiccion-voluntaria'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-7391'), 'Art. 2.3 LJV', 'El impulso y la dirección de los expedientes corresponderá a los Secretarios judiciales, atribuyéndose al Juez o al Secretario judicial, según el caso, la decisión de fondo que recaiga sobre aquellos', null, '84903dc9d3cc01d9ca2bb84568fb2d5980953e01c8488667437b9cc7579732be', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '84903dc9d3cc01d9ca2bb84568fb2d5980953e01c8488667437b9cc7579732be')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A los Letrados de la Administración de Justicia (Secretarios judiciales), atribuyéndose al Juez o al Letrado, según el caso, la decisión de fondo.', true), ('B', 'En todo caso al Juez, que decide además sobre el fondo.', false), ('C', 'Al Ministerio Fiscal.', false), ('D', 'A los Notarios y Registradores, salvo oposición.', false)) as v(label, body, ok)
)
