  select 'Contra lo convenido en un acto de conciliación, la Ley de la Jurisdicción Voluntaria solo admite la acción de nulidad por las causas que invalidan los contratos, que deberá ejercitarse mediante demanda interpuesta:', 'El art. 148 LJV fija quince días desde la celebración; acreditada la acción, queda en suspenso la ejecución de lo convenido.', 'justra_19_jurisdiccion_voluntaria', (select id from public.topics where slug = 'justra-19-jurisdiccion-voluntaria'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-7391'), 'Art. 148 LJV', 'La demanda ejercitando dicha acción deberá interponerse en un plazo de quince días desde que se celebró la conciliación ante el tribunal competente', null, '1eacb9f0b5b8b1863db9cd362c4c9286d166d42acf7ec9cde3af747d07a8c8ee', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1eacb9f0b5b8b1863db9cd362c4c9286d166d42acf7ec9cde3af747d07a8c8ee')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En el plazo de quince días desde que se celebró la conciliación.', true), ('B', 'En el plazo de un mes desde que se notificó el decreto.', false), ('C', 'En el plazo de veinte días desde la firmeza del decreto.', false), ('D', 'En el plazo de cuatro años desde la celebración del acto.', false)) as v(label, body, ok)
)
