with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso. ¿Qué órgano conoce en única instancia de la demanda de despido de Andrés según el artículo 6.1 de la LRJS?', 'El art. 6.1 LRJS atribuye a los Juzgados de lo Social la única instancia de todos los procesos sociales no atribuidos a otros órganos; tras la LO 1/2025 se integran como Secciones de lo Social de los Tribunales de Instancia.', 'justra_examen_2026_casos', (select id from public.topics where slug = 'justra-examen-2026-casos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 6.1 LRJS', '1\. Los Juzgados de lo Social conocerán en única instancia de todos los procesos atribuidos al orden jurisdiccional social, con excepción de los asignados expresamente a la competencia de otros órganos de este orden jurisdiccional', null, 'de94a2edaf3c451d1252215fa91d864c06821599876c5c4d1df6f060d5b79f94', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'de94a2edaf3c451d1252215fa91d864c06821599876c5c4d1df6f060d5b79f94')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Juzgado de lo Social (hoy, Sección de lo Social del Tribunal de Instancia).', true), ('B', 'La Sala de lo Social del Tribunal Superior de Justicia.', false), ('C', 'La Sala de lo Social de la Audiencia Nacional.', false), ('D', 'La Sección Civil del Tribunal de Instancia.', false)) as v(label, body, ok)
)
