with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso. ¿Puede Andrés reclamar en la misma demanda de despido las dos mensualidades que se le adeudan?', 'El art. 26.3 LRJS permite acumular a la acción de despido la reclamación de cantidades vencidas, exigibles y determinadas, sin alterar el orden de intervención del art. 105.1.', 'justra_examen_2026_casos', (select id from public.topics where slug = 'justra-examen-2026-casos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 26.3 LRJS', 'El trabajador podrá acumular a la acción de despido la reclamación de las cantidades vencidas, exigibles y de cuantía determinada adeudadas hasta esa fecha', null, '4e58d0cd9234da0081f0acfc40f70e5175ea2f399396b33011bb7f8bbc71479e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4e58d0cd9234da0081f0acfc40f70e5175ea2f399396b33011bb7f8bbc71479e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No, la acción de despido no admite acumulación de ninguna otra acción.', false), ('B', 'Solo si la empresa presta su conformidad.', false), ('C', 'Sí, puede acumular la reclamación de las cantidades vencidas, exigibles y de cuantía determinada adeudadas hasta esa fecha.', true), ('D', 'Solo mediante una demanda independiente que luego se acumule de oficio.', false)) as v(label, body, ok)
)
