with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso. Antes de presentar la demanda de despido, ¿qué requisito debe cumplir Andrés como regla general?', 'El art. 63 LRJS exige como requisito previo el intento de conciliación o mediación ante el servicio administrativo u órgano equivalente.', 'justra_examen_2026_casos', (select id from public.topics where slug = 'justra-examen-2026-casos'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 63 LRJS', 'Será requisito previo para la tramitación del proceso el intento de conciliación o, en su caso, de mediación ante el servicio administrativo correspondiente o ante el órgano que asuma estas funciones', null, '25d19ffcfce5c513b1fb636f7bff0ef38401344b7f1f59e1f5d89b2e25b39c36', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '25d19ffcfce5c513b1fb636f7bff0ef38401344b7f1f59e1f5d89b2e25b39c36')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Presentar reclamación previa ante la Inspección de Trabajo.', false), ('B', 'Obtener informe del comité de empresa.', false), ('C', 'Ninguno, porque el despido está exento de conciliación previa.', false), ('D', 'Intentar la conciliación o, en su caso, la mediación ante el servicio administrativo correspondiente u órgano que asuma esas funciones.', true)) as v(label, body, ok)
)
