with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso. Andrés quiere comparecer en el juicio asistido de su abogado. ¿Qué debe hacer según el artículo 21 de la LRJS?', 'La defensa por abogado es facultativa en la instancia; si el demandante quiere comparecer asistido, debe indicarlo en la demanda (art. 21.2 LRJS).', 'justra_examen_2026_casos', (select id from public.topics where slug = 'justra-examen-2026-casos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 21.2 LRJS', '2\. Si el demandante pretendiese comparecer en el juicio asistido de abogado, representado técnicamente por graduado social o representado por procurador, lo hará constar en la demanda, indicando los datos de contacto del profesional.', null, '227ec96bdeb5bbb21627cb50474d656b17893059cab4ce8c7e2c8549280cc301', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '227ec96bdeb5bbb21627cb50474d656b17893059cab4ce8c7e2c8549280cc301')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Comunicarlo verbalmente al inicio del juicio.', false), ('B', 'Solicitar autorización al juez mediante escrito independiente.', false), ('C', 'Nada, porque la defensa por abogado es preceptiva en la instancia.', false), ('D', 'Hacerlo constar en la demanda, indicando los datos de contacto del profesional.', true)) as v(label, body, ok)
)
