  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Caso. Contra la sentencia que resuelva el despido de Andrés, ¿cabe recurso de suplicación?', 'El art. 191.3.a) LRJS admite en todo caso la suplicación en los procesos por despido o extinción del contrato, salvo el despido colectivo impugnado por los representantes.', 'justra_examen_2026_casos', (select id from public.topics where slug = 'justra-examen-2026-casos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2011-15936'), 'Art. 191.3.a) LRJS', 'a) En procesos por despido o extinción del contrato, salvo en los procesos por despido colectivo impugnados por los representantes de los trabajadores.', null, 'b1584073b1b726caa5fa9b797a355db870fc268befe3f82b1cc4af3fdd130347', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b1584073b1b726caa5fa9b797a355db870fc268befe3f82b1cc4af3fdd130347')
