with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Real Decreto 937/2003, de modernización de los archivos judiciales, la remisión de documentos de un Archivo Judicial de Gestión al Archivo Judicial Territorial o Central:', 'El art. 13.1 del RD 937/2003 exige remisión al menos anual con una relación de procedimientos según modelo uniforme y obligatorio.', 'justra_examen_2026_test', (select id from public.topics where slug = 'justra-examen-2026-test'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-15237'), 'Art. 13 RD 937/2003', 'se formalizará periódicamente, como mínimo con carácter anual, en función del volumen de gestión de cada archivo, e irá acompañada necesariamente de una relación de los procedimientos o actuaciones judiciales en los que se integran', null, '8b8a15617fe6f49a4d30a0d7b9ae5257ed88ba70e9b3a6c883eb85a1bbdcd48d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8b8a15617fe6f49a4d30a0d7b9ae5257ed88ba70e9b3a6c883eb85a1bbdcd48d')
  returning id
