with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Diccionario de la lengua española, en Economía, la globalización es el proceso por el que las economías y mercados adquieren una dimensión mundial, de modo que dependen cada vez más:', 'La acepción 4 (Economía) vincula la globalización al desarrollo de las tecnologías de la comunicación y a una mayor dependencia de los mercados externos frente a la regulación de los Gobiernos.', 'pn_28_globalizacion', (select id from public.topics where slug = 'pn-28-globalizacion'), 3, 'es', true, (select id from public.sources where url = 'https://dle.rae.es/'), 'DLE, globalización 4', 'Proceso por el que las economías y mercados, con el desarrollo de las tecnologías de la comunicación, adquieren una dimensión mundial, de modo que dependen cada vez más de los mercados externos y menos de la acción reguladora de los Gobiernos.', null, 'b25920c94b91904cd4d3f549c6efd5186d9410048a97a646466dd57e71dd7651', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b25920c94b91904cd4d3f549c6efd5186d9410048a97a646466dd57e71dd7651')
  returning id
), o as (
