  select q.id, v.label, v.body, v.ok from q, (values ('A', 'De los mercados externos y menos de la acción reguladora de los Gobiernos.', true), ('B', 'De la acción reguladora de los Gobiernos y menos de los mercados externos.', false), ('C', 'De los organismos financieros internacionales y menos de los mercados internos.', false)) as v(label, body, ok)
