insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 15/2022, de 12 de julio, integral para la igualdad de trato y la no discriminación (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2022-11589', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-29-actitudes-valores', 'Tema 29. Actitudes y valores sociales: formación de las actitudes, estereotipos, prejuicios y discriminación, personalidad autoritaria (xenofobia y dogmatismo) y grupos sociales') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-29-actitudes-valores' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 15/2022, la situación en que se encuentra una persona o grupo que sea, haya sido o pudiera ser tratada de manera menos favorable que otras en situación análoga o comparable por alguna de las causas de discriminación previstas se denomina:', 'El art. 6.1.a define la discriminación directa. La indirecta nace de una disposición, criterio o práctica aparentemente neutros (art. 6.1.b) y el acoso busca atentar contra la dignidad creando un entorno intimidatorio u ofensivo (art. 6.4).', 'pn_29_actitudes_valores', (select id from public.topics where slug = 'pn-29-actitudes-valores'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2022-11589'), 'Art. 6.1.a Ley 15/2022', 'a) La discriminación directa es la situación en que se encuentra una persona o grupo en que se integra que sea, haya sido o pudiera ser tratada de manera menos favorable que otras en situación análoga o comparable por razón de las causas previstas en el apartado 1 del artículo 2.', null, '2fd50a1ad2ec00dcc652fbe8d34e72d72fdbfd5615c833feefd0c36b3f45c14d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2fd50a1ad2ec00dcc652fbe8d34e72d72fdbfd5615c833feefd0c36b3f45c14d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Discriminación directa.', true), ('B', 'Discriminación indirecta.', false), ('C', 'Acoso discriminatorio.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 15/2022, la discriminación que se funda en una apreciación incorrecta acerca de las características de la persona o personas discriminadas es la discriminación:', 'El art. 6.2.b define la discriminación por error. La discriminación por asociación se produce por la relación de la persona con otra en quien concurre una causa de discriminación (art. 6.2.a).', 'pn_29_actitudes_valores', (select id from public.topics where slug = 'pn-29-actitudes-valores'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2022-11589'), 'Art. 6.2.b Ley 15/2022', 'b) La discriminación por error es aquella que se funda en una apreciación incorrecta acerca de las características de la persona o personas discriminadas.', null, '47098bc2223a18f0e993268ca0f7e30277c2e9c36ba91897e28f7c89bb3cbbbc', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '47098bc2223a18f0e993268ca0f7e30277c2e9c36ba91897e28f7c89bb3cbbbc')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Por asociación.', false), ('B', 'Por error.', true), ('C', 'Interseccional.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 18.1 de la Ley 15/2022, las Fuerzas y Cuerpos de Seguridad evitarán la utilización de perfiles discriminatorios:', 'El art. 18.1, relativo a la seguridad ciudadana, obliga a las Fuerzas y Cuerpos de Seguridad a evitar los perfiles discriminatorios que carezcan de una justificación objetiva; el art. 18.2 extiende la obligación a la seguridad privada.', 'pn_29_actitudes_valores', (select id from public.topics where slug = 'pn-29-actitudes-valores'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2022-11589'), 'Art. 18.1 Ley 15/2022', '1\. A los efectos de esta ley, las Fuerzas y Cuerpos de Seguridad evitarán la utilización de perfiles discriminatorios sin una justificación objetiva.', null, 'c578f17c75b7dbc22649dd3f6008f44f07da92e98d762ef3e3c493bfeac80cab', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c578f17c75b7dbc22649dd3f6008f44f07da92e98d762ef3e3c493bfeac80cab')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En todo caso y sin excepción alguna.', false), ('B', 'Salvo autorización expresa del Ministerio Fiscal.', false), ('C', 'Sin una justificación objetiva.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley 15/2022, cuando concurren o interactúan diversas causas de discriminación, generando una forma específica de discriminación, se produce discriminación:', 'El art. 6.3.b define la discriminación interseccional. En la múltiple (art. 6.3.a) la persona es discriminada de manera simultánea o consecutiva por dos o más causas, sin que se genere necesariamente una forma específica nueva.', 'pn_29_actitudes_valores', (select id from public.topics where slug = 'pn-29-actitudes-valores'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2022-11589'), 'Art. 6.3.b Ley 15/2022', 'b) Se produce discriminación interseccional cuando concurren o interactúan diversas causas de las previstas en esta ley, generando una forma específica de discriminación.', null, 'cbcb8877ea2874362ba38f812aac1c59f87ce7fdd03c65b2dee9272673d6232d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'cbcb8877ea2874362ba38f812aac1c59f87ce7fdd03c65b2dee9272673d6232d')
  returning id
), o as (
