  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Diccionario de la lengua española, en una de sus acepciones, la actitud es la:', 'La acepción 2 de «actitud» en el DLE es la disposición de ánimo manifestada de algún modo. La posición en la sociedad es el estatus y la cualidad de las realidades estimables es el valor en sentido filosófico.', 'pn_29_actitudes_valores', (select id from public.topics where slug = 'pn-29-actitudes-valores'), 1, 'es', true, (select id from public.sources where url = 'https://dle.rae.es/'), 'DLE, actitud 2', 'Disposición de ánimo manifestada de algún modo.', null, '19bdda8e6e82c7f2924a0803e06dc96dea91c7490f4a7d2b98efd1788e4523da', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '19bdda8e6e82c7f2924a0803e06dc96dea91c7490f4a7d2b98efd1788e4523da')
  returning id
