insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-40-inteligencia-osint' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la guía CCN-STIC-425 del Centro Criptológico Nacional, las actividades de inteligencia pueden agruparse en seis fases: Dirección y Planificación, Recolección, Transformación, Análisis y Producción, Difusión y:', 'La guía CCN-STIC-425 enumera seis fases del Ciclo de Inteligencia; la de Evaluación tiene lugar tras cada una de las otras cinco para alinear sus resultados con los objetivos.', 'pn_40_inteligencia_osint', (select id from public.topics where slug = 'pn-40-inteligencia-osint'), 2, 'es', true, (select id from public.sources where url = 'https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file'), 'CCN-STIC-425, apdo. 2.2, párr. 9', '9. Las actividades de inteligencia pueden agruparse en las siguientes seis fases: […] Dirección y Planificación. […] Recolección. […] Transformación. […] Análisis y Producción. […] Difusión. […] Evaluación.', null, 'eb50a2ed0515a73fae36e8344b679cbea4afc4f00075503700880b1e9f2f021b', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'eb50a2ed0515a73fae36e8344b679cbea4afc4f00075503700880b1e9f2f021b')
  returning id
), o as (
