with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la guía CCN-STIC-425, el objetivo de la fase de Recolección es recopilar:', 'La guía distingue la información (datos en bruto) de la inteligencia (producto final). Establecer los requisitos corresponde a la fase de Dirección y Planificación.', 'pn_40_inteligencia_osint', (select id from public.topics where slug = 'pn-40-inteligencia-osint'), 1, 'es', true, (select id from public.sources where url = 'https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file'), 'CCN-STIC-425, apdo. 2.2.2, párr. 16', '16. El objetivo de esta fase es recopilar los datos en bruto necesarios (información) para producir el producto final deseado (inteligencia).', null, 'dc21a3c7ec779928f072e6daf5a3cb0f80904f4c8d30c77f2f3d1e001baa13a5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'dc21a3c7ec779928f072e6daf5a3cb0f80904f4c8d30c77f2f3d1e001baa13a5')
