with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la guía CCN-STIC-425, el único tipo de inteligencia en el que los encargados de recabar la información la obtienen directamente de las fuentes, pudiendo incluso controlar el tema tratado y dirigir la respuesta de la fuente, es la:', 'La HUMINT procede de fuentes humanas, por vía oral o documental, y puede obtenerse de manera abierta o confidencial; quienes la recaban se denominan oficiales de obtención.', 'pn_40_inteligencia_osint', (select id from public.topics where slug = 'pn-40-inteligencia-osint'), 2, 'es', true, (select id from public.sources where url = 'https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file'), 'CCN-STIC-425, apdo. 2.2.2, párr. 20', 'Se trata del único tipo de inteligencia en la que los encargados de recabar la información (denominados oficiales de obtención) la obtienen directamente de las fuentes (con su conocimiento o no), pudiendo incluso controlar el tema tratado y dirigir la respuesta de la fuente.', null, '522aa13d1cfe1ad0505b3be55df65c4d1fa3bb4ea1408efe220cc649769bfc63', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '522aa13d1cfe1ad0505b3be55df65c4d1fa3bb4ea1408efe220cc649769bfc63')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'HUMINT (Inteligencia Humana).', true), ('B', 'OSINT (Inteligencia de Fuentes Abiertas).', false), ('C', 'SIGINT (Inteligencia de Señales).', false)) as v(label, body, ok)
)
