select q.id, b.id from q, public.exam_bodies b where b.slug in ('policia-nacional-basica');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la guía CCN-STIC-425, la Inteligencia de Señales (SIGINT) incluye la Inteligencia de Comunicaciones (COMINT), la Inteligencia de Señales de Instrumentos Extranjeros (FISINT) y la Inteligencia Electrónica (ELINT), cuyas fuentes más comunes son:', 'La nota 3 de la guía define la ELINT como la información derivada de señales electrónicas que no contienen voz o texto (que serían COMINT) y señala que sus fuentes más comunes son las señales de radar.', 'pn_40_inteligencia_osint', (select id from public.topics where slug = 'pn-40-inteligencia-osint'), 3, 'es', true, (select id from public.sources where url = 'https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file'), 'CCN-STIC-425, apdo. 2.2.2, párr. 22 y nota 3', 'ELINT es la información derivada básicamente de señales electrónicas que no contienen voz o texto (consideradas COMINT). Las fuentes más comunes de ELINT son las señales de radar.', null, '01cab0686ce09b774702df0f6ebb99e81075f7d0516cb25d5c50cfc0738e4408', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '01cab0686ce09b774702df0f6ebb99e81075f7d0516cb25d5c50cfc0738e4408')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Las imágenes tomadas desde satélites.', false), ('B', 'Las conversaciones telefónicas interceptadas.', false), ('C', 'Las señales de radar.', true)) as v(label, body, ok)
)
