with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la guía CCN-STIC-425, la fase del Ciclo de Inteligencia que tiene por objeto convertir el formato de los datos en bruto recabados de las distintas fuentes en aquellos otros formatos que posibiliten su posterior tratamiento y análisis es la de:', 'La Transformación incluye, entre otros procesos, la traducción, el descifrado, la conversión de datos telemétricos y la de informes HUMINT en contenido comprensible. El Análisis y Producción integra y evalúa la información ya procesada para obtener inteligencia.', 'pn_40_inteligencia_osint', (select id from public.topics where slug = 'pn-40-inteligencia-osint'), 3, 'es', true, (select id from public.sources where url = 'https://www.ccn-cert.cni.es/es/series-ccn-stic/guias-de-acceso-publico-ccn-stic/1093-ccn-stic-425-ciclo-de-inteligencia-y-analisis-de-intrusiones/file'), 'CCN-STIC-425, apdo. 2.2.3, párr. 23', '23. Esta fase tiene por objeto convertir el formato de los datos en bruto recabados de las distintas fuentes, en aquellos otros formatos que posibiliten su posterior tratamiento y análisis.', null, '63c30f50980a3b63504bb0a1aa96a6e351545295bb8a32ee57037b07565e0570', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '63c30f50980a3b63504bb0a1aa96a6e351545295bb8a32ee57037b07565e0570')
  returning id
