  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según INCIBE, la técnica utilizada por ciberdelincuentes para obtener información bancaria y personal de tiendas online legítimas, que posteriormente será vendida en el mercado negro o utilizada en su propio beneficio, es el:', 'En el e-skimming los atacantes acceden a la tienda y modifican su código fuente para que los datos introducidos por el cliente se envíen al banco y también a ellos; el pago se completa y ni cliente ni comercio advierten el robo.', 'pn_41_ciberdelincuencia', (select id from public.topics where slug = 'pn-41-ciberdelincuencia'), 2, 'es', true, (select id from public.sources where url = 'https://www.incibe.es/ciudadania/blog/deep-web-y-dark-web-descubre-que-son-y-en-que-se-diferencian'), 'INCIBE, E-skimming (2019)', 'El e-skimming o web skimming es una técnica utilizada por ciberdelincuentes para obtener información bancaria y personal de tiendas online legítimas que posteriormente será vendida en el mercado negro, o utilizada directamente por los ciberdelincuentes en su propio beneficio.', null, '8438661d06ad9fd49393ad6180863477cd235971f323b9b7c52ccdf12c6194cf', false
