with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Real Decreto 773/1997, se entenderá por «equipo de protección individual»:', 'El art. 2.1 define el EPI e incluye cualquier complemento o accesorio destinado a tal fin; la ropa de trabajo corriente y los uniformes no destinados específicamente a proteger están excluidos (art. 2.2.a).', 'pn_45_prl_seguridad_vial', (select id from public.topics where slug = 'pn-45-prl-seguridad-vial'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1997-12735'), 'Art. 2.1 RD 773/1997', 'se entenderá por «equipo de protección individual», cualquier equipo destinado a ser llevado o sujetado por el trabajador para que le proteja de uno o varios riesgos que puedan amenazar su seguridad o su salud, así como cualquier complemento o accesorio destinado a tal fin.', null, '963e8ba9bc920577d51597d51472a4fab15778414eab443642bcb4115147f2c5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '963e8ba9bc920577d51597d51472a4fab15778414eab443642bcb4115147f2c5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cualquier medio técnico de protección colectiva instalado en el lugar de trabajo.', false), ('B', 'Cualquier equipo destinado a ser llevado o sujetado por el trabajador para que le proteja de uno o varios riesgos que puedan amenazar su seguridad o su salud.', true), ('C', 'La ropa de trabajo corriente y los uniformes facilitados por el empresario.', false)) as v(label, body, ok)
)
