insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Sinónimos: palabras de significado igual o parecido en una acepción concreta"},{"n":"1.1","title":"Cómo leer el apartado «Sinónimos y afines» del DLE (va unido a cada acepción)"},{"n":"2","title":"Antónimos: palabras de significado opuesto («Antónimos y opuestos» del DLE)"},{"n":"3","title":"Parónimos que se confunden en los tests (inocuo/inicuo, perspicaz/suspicaz, prolijo/prolífico)"},{"n":"4","title":"Ortografía de las letras: h, b/v, g/j, x/s, grupo sc"},{"n":"5","title":"Ortografía de expresiones: sino / si no; porque / por que"},{"n":"6","title":"Acentuación: monosílabos sin tilde (fue, vio, guion)"},{"n":"7","title":"Vocabulario: significado de voces cultas frecuentes en los psicotécnicos"}]'::jsonb, '["DLE, efímero DLE (RAE): «adj. Pasajero, de corta duración.»","DLE, inocuo DLE (RAE): «adj. Que no hace daño.»","DLE, inicuo DLE (RAE): «adj. Contrario a la equidad.»","DLE, perspicaz DLE (RAE): «adj. Dicho del ingenio, agudo y penetrativo.»","DLE, prolijo DLE (RAE): «adj. Largo, dilatado con exceso.»","DLE, prolífico DLE (RAE): «adj. Que se reproduce o es capaz de reproducirse en abundancia.»","DLE, lacónico DLE (RAE): «Antónimos y opuestos de lacónico, lacónica locuaz - verboso, verbosa»","DLE, exiguo DLE (RAE): «Antónimos y opuestos de exiguo, exigua abundante - cuantioso, cuantiosa»","DLE, óbice DLE (RAE): «m. Obstáculo, embarazo, estorbo, impedimento.»","DLE, pusilánime DLE (RAE): «adj. Dicho de una persona, falta de ánimo y valor para tomar decisiones o afrontar situaciones comprometidas.»","DLE, exuberante DLE (RAE): «adj. Muy abundante y copioso.»","DLE, cónyuge DLE (RAE): «m. y f. Persona unida a otra en matrimonio.»","DPD, sino 2.1 DPD (RAE): «Se usa para introducir un elemento que reemplaza o sustituye al negado en la oración precedente»","DPD, sino 3 DPD (RAE): «No debe confundirse la conjunción adversativa sino antes descrita con si no, secuencia formada por la conjunción si (→ si) seguida del adverbio de negación no»","DPD, porque 2.a DPD (RAE): «Se escribe por que, en dos palabras, en los casos siguientes: a) Cuando el pronombre relativo que va precedido de la preposición por.»","DPD, tilde 1.1 DPD (RAE): «Las palabras de una sola sílaba no se acentúan nunca gráficamente, salvo en los casos de tilde diacrítica (→ 3.1): mes, bien, fe, fue, vio, guion, hui, riais.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://dle.rae.es/'), 'https://dle.rae.es/', null, null, null, 'Otras normas citadas: DPD (RAE) (https://www.rae.es/dpd/)'
  from public.topics t where t.slug = 'age-aux-psicotecnicos-verbales'
