insert into public.sources (title, url, kind, publisher, published_on) values ('FMI · La globalización: ¿Amenaza u oportunidad? (estudio temático, abril de 2000)', 'https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm', 'web_oficial'::public.source_kind, 'Fondo Monetario Internacional (organismo de las Naciones Unidas)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('pn-28-globalizacion', 'Tema 28. Globalización y antiglobalización: conceptos, características, consecuencias, reacciones, movimiento antiglobalización y Foro Social Mundial') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('policia-nacional-basica') and t.slug = 'pn-28-globalizacion' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Concepto de globalización: definición del FMI y acepciones del DLE"},{"n":"2","title":"Características: comercio exterior, movimientos de capital, migraciones y difusión de los conocimientos"},{"n":"3","title":"Consecuencias: crecimiento, desigualdades entre regiones y soberanía nacional"},{"n":"4","title":"Reacciones: antiglobalización y altermundismo"},{"n":"5","title":"Por una globalización justa (OIT, 2004): gobernanza, enfoque centrado en las personas y Foro Social Mundial"}]'::jsonb, '["FMI, ¿Qué es la globalización? FMI, «La globalización: ¿Amenaza u oportunidad?»: «La \"globalización\" económica es un proceso histórico, el resultado de la innovación humana y el progreso tecnológico. Se refiere a la creciente integración de las economías de todo el mundo, especialmente a través del comercio y los flujos financieros.»","FMI, ¿Qué es la globalización? FMI, «La globalización: ¿Amenaza u oportunidad?»: «El uso de este término se utiliza comúnmente desde los años ochenta, es decir, desde que los adelantos tecnológicos han facilitado y acelerado las transacciones internacionales comerciales y financieras.»","DLE, globalización 3 DLE (RAE): «Difusión mundial de modos, valores o tendencias que fomenta la uniformidad de gustos y costumbres.»","DLE, globalización 4 DLE (RAE): «Proceso por el que las economías y mercados, con el desarrollo de las tecnologías de la comunicación, adquieren una dimensión mundial, de modo que dependen cada vez más de los mercados externos y menos de la acción reguladora de los Gobiernos.»","FMI, Aspectos de la globalización FMI, «La globalización: ¿Amenaza u oportunidad?»: «Considérense cuatro aspectos de la globalización:»","FMI, Comercio exterior FMI, «La globalización: ¿Amenaza u oportunidad?»: «La participación del conjunto de países en desarrollo en el comercio mundial aumentó del 19% en 1971 al 29% en 1999.»","FMI, Movimientos de capital FMI, «La globalización: ¿Amenaza u oportunidad?»: «La inversión extranjera directa ha pasado a ser la categoría más importante.»","FMI, Migraciones FMI, «La globalización: ¿Amenaza u oportunidad?»: «Los trabajadores se desplazan de un país a otro en parte en busca de mejores oportunidades de empleo.»","FMI, Evolución en el siglo XX FMI, «La globalización: ¿Amenaza u oportunidad?»: «En el siglo XX hubo un crecimiento económico sin precedente, que casi quintuplicó el PIB mundial per cápita.»","FMI, Evolución en el siglo XX FMI, «La globalización: ¿Amenaza u oportunidad?»: «el crecimiento del ingreso per cápita se redujo a menos del 1% entre 1913 y 1950.»","FMI, Recuadro 1 FMI, «La globalización: ¿Amenaza u oportunidad?»: «En resumen, la globalización no reduce la soberanía nacional. Crea fuertes incentivos para que los países apliquen políticas económicas correctas.»","DLE, antiglobalización 1.b DLE (RAE): «Conjunto de movimientos sociales contrarios a la globalización económica.»","DLE, altermundismo DLE (RAE): «Movimiento reformista heterogéneo que se opone a la globalización del neoliberalismo y aboga por modelos económicos y sociales alternativos.»","OIT, Sinopsis OIT, «Por una globalización justa» (2004): «Consideramos que los problemas que hemos descrito no se deben a la globalización en sí, sino a deficiencias en su gobernanza.»","OIT, Sinopsis OIT, «Por una globalización justa» (2004): «Un enfoque centrado en las personas. La piedra angular de una globalización más justa es la satisfacción de las demandas de todas las personas en lo que atañe al»","OIT, párr. 119 OIT, «Por una globalización justa» (2004): «También se consideró que un debate con el Foro Social Mundial podría beneficiar a ambas partes.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm'), 'https://www.imf.org/external/np/exr/ib/2000/esl/041200s.htm', null, null, null, 'Otras normas citadas: DLE (RAE) (https://dle.rae.es/), OIT, «Por una globalización justa» (2004) (https://webapps.ilo.org/public/spanish/wcsdg/docs/report.pdf)'
  from public.topics t where t.slug = 'pn-28-globalizacion'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
